// =========================================================================
// 2. AUTH & JWT MIDDLEWARE (User -> Supabase Auth -> JWT -> Fastify -> requireAuth)
// =========================================================================

function createDakshoraJwt(payload, secret = (process.env.SUPABASE_SERVICE_ROLE_KEY || "dakshora-enterprise-jwt-secret-2026"), expiresInSeconds = 7 * 86400) {
  const header = { alg: "HS256", typ: "JWT" };
  const now = Math.floor(Date.now() / 1000);
  const claims = {
    ...payload,
    iat: now,
    exp: now + expiresInSeconds,
    iss: "dakshora-auth"
  };
  const b64Header = Buffer.from(JSON.stringify(header)).toString("base64url");
  const b64Payload = Buffer.from(JSON.stringify(claims)).toString("base64url");
  const signature = crypto
    .createHmac("sha256", secret)
    .update(`${b64Header}.${b64Payload}`)
    .digest("base64url");
  return `${b64Header}.${b64Payload}.${signature}`;
}

function verifyDakshoraToken(token, secret = (process.env.SUPABASE_SERVICE_ROLE_KEY || "dakshora-enterprise-jwt-secret-2026")) {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;
    const [b64Header, b64Payload, signature] = parts;
    const expectedSignature = crypto
      .createHmac("sha256", secret)
      .update(`${b64Header}.${b64Payload}`)
      .digest("base64url");

    if (signature !== expectedSignature) return null;

    const payloadStr = Buffer.from(b64Payload, "base64url").toString("utf-8");
    const payload = JSON.parse(payloadStr);

    const now = Math.floor(Date.now() / 1000);
    if (payload.exp && payload.exp < now) return null;

    const isSuperAdmin = payload.role === "superadmin" || payload.app_metadata?.role === "superadmin" || payload.isSuperAdmin === true;
    const role = isSuperAdmin ? "superadmin" : (payload.role || payload.app_metadata?.role || "school-admin");
    const organizationId = payload.organizationId || payload.app_metadata?.organization_id || "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";

    return {
      id: payload.sub || payload.id || "dakshora-user",
      email: payload.email,
      phone: payload.phone,
      name: payload.name || "Mobile User",
      role,
      isSuperAdmin,
      organizationId,
      permissions: isSuperAdmin ? ["*"] : (payload.permissions || ["websites.view", "websites.edit", "leads.view", "leads.manage", "school.manage", "ai.use"]),
      user_metadata: payload.user_metadata || {},
      app_metadata: payload.app_metadata || {}
    };
  } catch {
    return null;
  }
}

// requireAuth middleware validates incoming Bearer JWT from Supabase Auth cryptographically
async function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization || req.headers.Authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({
      success: false,
      code: "AUTH_REQUIRED",
      message: "Authorization header with 'Bearer <JWT_TOKEN>' is required 🔒",
      pipeline: "User → Supabase Auth → JWT → requireAuth()"
    });
  }

  const token = authHeader.split(" ")[1];

  try {
    // Cryptographically verify token strictly with Supabase Auth
    let user = null;
    let authError = null;

    if (supabase) {
      try {
        const { data, error } = await supabase.auth.getUser(token);
        if (data && data.user) {
          user = data.user;
        } else {
          authError = error;
        }
      } catch (err) {
        authError = err;
      }
    }

    if (!user) {
      return res.status(401).json({
        success: false,
        code: "INVALID_JWT",
        message: "Invalid or expired JWT token. Please sign in again 🔒",
        pipeline: "User → Supabase Auth → JWT → requireAuth()",
        error: authError?.message || "Invalid token signature"
      });
    }

    // STRICT: Only trust app_metadata for superadmin role (server-managed claim)
    const isSuperAdmin = user.app_metadata?.role === "superadmin";
    let role = isSuperAdmin ? "superadmin" : (user.app_metadata?.role || null);
    let organizationId = user.app_metadata?.organization_id || user.user_metadata?.organization_id || null;

    if (!isSuperAdmin && (!organizationId || !role) && supabase) {
      try {
        const { data: membership } = await supabase
          .from("organization_members")
          .select("organization_id, roles(name)")
          .eq("user_id", user.id)
          .limit(1)
          .maybeSingle();

        if (membership) {
          organizationId = organizationId || membership.organization_id;
          if (!role && membership.roles) {
            const roleData = membership.roles;
            role = Array.isArray(roleData) ? roleData[0]?.name : roleData?.name;
          }
        }
        if (!organizationId) {
          const { data: dbUser } = await supabase
            .from("users")
            .select("organization_id, role")
            .eq("id", user.id)
            .maybeSingle();
          if (dbUser) {
            organizationId = dbUser.organization_id || organizationId;
            role = role || dbUser.role;
          }
        }
      } catch (dbErr) {
        // Fallback gracefully
      }
    }

    role = role || (isSuperAdmin ? "superadmin" : "school-admin");

    req.user = {
      id: user.id,
      email: user.email,
      name: user.user_metadata?.name || user.email,
      role,
      isSuperAdmin,
      permissions: isSuperAdmin ? ["*"] : ["websites.view", "websites.edit", "leads.view", "leads.manage", "school.manage", "ai.use"],
      organizationId: organizationId || null
    };

    // Multi-Tenant Security: Block access if the school tenant is deactivated/suspended
    if (!isSuperAdmin && organizationId) {
      let tenantOrg = IN_MEMORY_ORGANIZATIONS.find(o => o.id === organizationId);
      if (!tenantOrg && supabase) {
        try {
          const { data } = await supabase.from("organizations").select("id, name, status").eq("id", organizationId).maybeSingle();
          if (data) tenantOrg = data;
        } catch (_) {}
      }
      if (tenantOrg && (tenantOrg.status === 'suspended' || tenantOrg.status === 'deactivated' || tenantOrg.status === 'archived')) {
        return res.status(403).json({
          success: false,
          code: "TENANT_DEACTIVATED",
          message: `Access Suspended: School '${tenantOrg.name}' has been deactivated by Dakshora Platform Administration. Please contact administration for assistance.`,
          status: tenantOrg.status
        });
      }
    }

    if (organizationId && supabase) {
      try {
        const [subRes, ovrRes] = await Promise.all([
          supabase.from("saas_subscriptions").select("*").eq("organization_id", organizationId).limit(1).maybeSingle(),
          supabase.from("saas_entitlement_overrides").select("*").eq("organization_id", organizationId)
        ]);

        if (subRes.data) {
          const idx = SAAS_SUBSCRIPTIONS.findIndex(s => s.organization_id === organizationId);
          const subObj = {
            id: subRes.data.id,
            organization_id: subRes.data.organization_id,
            plan_id: subRes.data.plan_id,
            status: subRes.data.status,
            billing_interval: subRes.data.billing_interval,
            amountINR: Number(subRes.data.amount),
            currency: subRes.data.currency,
            current_period_start: subRes.data.current_period_start,
            current_period_end: subRes.data.current_period_end
          };
          if (idx !== -1) {
            SAAS_SUBSCRIPTIONS[idx] = subObj;
          } else {
            SAAS_SUBSCRIPTIONS.push(subObj);
          }
        }

        if (ovrRes.data && ovrRes.data.length > 0) {
          for (let i = SAAS_OVERRIDES.length - 1; i >= 0; i--) {
            if (SAAS_OVERRIDES[i].organization_id === organizationId) {
              SAAS_OVERRIDES.splice(i, 1);
            }
          }
          ovrRes.data.forEach(o => SAAS_OVERRIDES.push(o));
        }
      } catch (_) {}
    }

    next();
  } catch (err) {
    return res.status(401).json({
      success: false,
      code: "AUTH_EXCEPTION",
      message: "Authentication verification failed",
      error: err.message
    });
  }
}

// SuperAdmin Authorization Middleware
async function requireSuperAdmin(req, res, next) {
  if (!req.user) {
    return requireAuth(req, res, () => {
      if (!req.user?.isSuperAdmin && req.user?.role !== "superadmin") {
        return res.status(403).json({
          success: false,
          code: "FORBIDDEN_SUPERADMIN",
          message: "Access Denied: Platform SuperAdmin privilege required."
        });
      }
      next();
    });
  }

  if (!req.user.isSuperAdmin && req.user.role !== "superadmin") {
    return res.status(403).json({
      success: false,
      code: "FORBIDDEN_SUPERADMIN",
      message: "Access Denied: Platform SuperAdmin privilege required."
    });
  }

  next();
}

// Role-based authorization middleware
function requireRole(allowedRoles = []) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ success: false, message: "Authentication required" });
    }
    if (req.user.isSuperAdmin || allowedRoles.includes(req.user.role)) {
      return next();
    }
    return res.status(403).json({
      success: false,
      code: "FORBIDDEN_ROLE",
      message: `Access denied. Allowed roles: [${allowedRoles.join(", ")}]. Current role: ${req.user.role}`
    });
  };
}

