// =========================================================================

// GET /api/auth/verify-activation-token (Invitation validation & prefill)
app.get("/api/auth/verify-activation-token", async (req, res) => {
  try {
    const rawToken = String(req.query.token || "").trim();
    if (!rawToken) {
      return res.status(400).json({ success: false, message: "Activation token is required." });
    }

    const tokenHash = crypto.createHash("sha256").update(rawToken).digest("hex");
    let invite = null;
    let organizationId = null;

    // 1. Check school_onboarding_invitations table (if provisioned)
    if (supabase) {
      try {
        const { data: invData, error: invErr } = await supabase
          .from("school_onboarding_invitations")
          .select("*")
          .eq("token", tokenHash)
          .maybeSingle();
        if (!invErr && invData) {
          invite = invData;
          organizationId = invData.organization_id;
        }
      } catch (_) {}
    }

    // 2. Fallback to school_onboarding JSONB draft_data.invitation
    if (!invite && supabase) {
      try {
        const { data: onb, error: onbErr } = await supabase
          .from("school_onboarding")
          .select("*")
          .contains("draft_data", { invitation: { token: tokenHash } })
          .maybeSingle();
        if (!onbErr && onb?.draft_data?.invitation) {
          invite = {
            ...onb.draft_data.invitation,
            id: onb.id,
            organization_id: onb.organization_id
          };
          organizationId = onb.organization_id;
        }
      } catch (_) {}
    }

    if (!invite) {
      return res.status(404).json({ success: false, code: "INVALID_TOKEN", message: "Invalid or non-existent activation link." });
    }

    if (invite.status === "accepted") {
      return res.status(400).json({ success: false, code: "ALREADY_ACTIVATED", message: "This account has already been activated. Please sign in directly." });
    }

    if (new Date(invite.expires_at) < new Date()) {
      return res.status(410).json({ success: false, code: "TOKEN_EXPIRED", message: "This activation link has expired. Please contact support or request a new invite." });
    }

    let tenantCode = "";
    let schoolName = "School ERP";
    let board = "CBSE";

    if (supabase && organizationId) {
      try {
        const { data: school } = await supabase
          .from("schools")
          .select("school_code, name, board")
          .eq("organization_id", organizationId)
          .maybeSingle();
        if (school) {
          tenantCode = school.school_code || "";
          schoolName = school.name || schoolName;
          board = school.board || board;
        }
      } catch (_) {}
    }

    return res.json({
      success: true,
      valid: true,
      email: invite.email,
      name: invite.name,
      role: invite.role,
      organizationId,
      schoolName,
      board,
      tenantCode,
      expiresAt: invite.expires_at
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: `Verification failed: ${err.message}` });
  }
});

// POST /api/auth/activate-account (Principal Password Setup & Single-Use Activation)
app.post("/api/auth/activate-account", async (req, res) => {
  try {
    const { token, password, confirmPassword } = req.body || {};
    if (!token || !password) {
      return res.status(400).json({ success: false, message: "Activation token and new password are required." });
    }
    if (password.length < 8) {
      return res.status(400).json({ success: false, message: "Password must be at least 8 characters long." });
    }
    if (confirmPassword && password !== confirmPassword) {
      return res.status(400).json({ success: false, message: "Passwords do not match." });
    }

    const tokenHash = crypto.createHash("sha256").update(String(token).trim()).digest("hex");
    let invite = null;
    let organizationId = null;

    // 1. Check school_onboarding_invitations table
    if (supabase) {
      try {
        const { data: invData, error: invErr } = await supabase
          .from("school_onboarding_invitations")
          .select("*")
          .eq("token", tokenHash)
          .maybeSingle();
        if (!invErr && invData) {
          invite = invData;
          organizationId = invData.organization_id;
        }
      } catch (_) {}
    }

    // 2. Check school_onboarding draft_data
    if (!invite && supabase) {
      try {
        const { data: onb, error: onbErr } = await supabase
          .from("school_onboarding")
          .select("*")
          .contains("draft_data", { invitation: { token: tokenHash } })
          .maybeSingle();
        if (!onbErr && onb?.draft_data?.invitation) {
          invite = {
            ...onb.draft_data.invitation,
            id: onb.id,
            organization_id: onb.organization_id
          };
          organizationId = onb.organization_id;
        }
      } catch (_) {}
    }

    if (!invite) {
      return res.status(404).json({ success: false, code: "INVALID_TOKEN", message: "Invalid activation token." });
    }

    if (invite.status === "accepted") {
      return res.status(400).json({ success: false, code: "ALREADY_ACTIVATED", message: "Account already activated. Please sign in." });
    }

    if (new Date(invite.expires_at) < new Date()) {
      return res.status(410).json({ success: false, code: "TOKEN_EXPIRED", message: "Activation token has expired." });
    }

    const cleanEmail = String(invite.email || "").toLowerCase().trim();
    let targetUserId = "";

    // Update password in Supabase Auth
    if (supabase) {
      try {
        const { data: dbUser } = await supabase
          .from("users")
          .select("id")
          .eq("email", cleanEmail)
          .maybeSingle();

        if (dbUser?.id) {
          targetUserId = dbUser.id;
          try {
            await supabase.auth.admin.updateUserById(targetUserId, {
              password: password.trim(),
              email_confirm: true
            });
          } catch (uErr) {
            console.warn("[Auth Admin Update User Note]:", uErr.message);
          }
        } else {
          const { data: userList } = await supabase.auth.admin.listUsers();
          const targetUser = userList?.users?.find(u => u.email?.toLowerCase() === cleanEmail);
          if (targetUser) {
            targetUserId = targetUser.id;
            await supabase.auth.admin.updateUserById(targetUser.id, {
              password: password.trim(),
              email_confirm: true
            });
          } else {
            const { data: created } = await supabase.auth.admin.createUser({
              email: cleanEmail,
              password: password.trim(),
              email_confirm: true,
              user_metadata: {
                name: invite.name,
                role: invite.role || "school-admin",
                organization_id: organizationId
              },
              app_metadata: {
                role: invite.role || "school-admin",
                organization_id: organizationId
              }
            });
            if (created?.user) targetUserId = created.user.id;
          }
        }
      } catch (authErr) {
        console.warn("[Auth Admin Activation Warning]:", authErr.message);
      }

      // Mark invitation as accepted in school_onboarding_invitations
      try {
        await supabase
          .from("school_onboarding_invitations")
          .update({
            status: "accepted",
            accepted_at: new Date().toISOString()
          })
          .eq("token", tokenHash);
      } catch (_) {}

      // Mark invitation as accepted in school_onboarding
      try {
        const { data: onbToUpdate } = await supabase
          .from("school_onboarding")
          .select("id, draft_data")
          .contains("draft_data", { invitation: { token: tokenHash } })
          .maybeSingle();

        if (onbToUpdate) {
          const updatedDraft = {
            ...onbToUpdate.draft_data,
            invitation: {
              ...onbToUpdate.draft_data.invitation,
              status: "accepted",
              accepted_at: new Date().toISOString()
            }
          };
          await supabase
            .from("school_onboarding")
            .update({
              draft_data: updatedDraft,
              status: "active",
              activated_at: new Date().toISOString()
            })
            .eq("id", onbToUpdate.id);
        }
      } catch (_) {}

      // Update user in public.users
      if (targetUserId) {
        try {
          await supabase
            .from("users")
            .upsert([{
              id: targetUserId,
              organization_id: organizationId,
              email: cleanEmail,
              name: invite.name,
              role: invite.role || "school-admin",
              status: "active"
            }], { onConflict: "id" });
        } catch (_) {}
      }
    }

    recordAuditLog("auth.account_activated", cleanEmail, "user", targetUserId || organizationId, req);

    return res.json({
      success: true,
      message: "Account activated successfully! You can now log into Dakshora School ERP. 🏫🚀",
      email: cleanEmail,
      loginUrl: "https://dakshora.co.in/portal"
    });
  } catch (routeErr) {
    console.error("[Activation Endpoint Error]:", routeErr);
    return res.status(500).json({ success: false, message: `Failed to activate account: ${routeErr.message}` });
  }
});

// =========================================================================
// SECURITY HARDENING: In-Memory Sliding-Window Rate Limiter
// =========================================================================
const RATE_LIMIT_WINDOWS = new Map(); // key -> [timestamps]

function createRateLimiter(windowMs, maxRequests, message) {
  return (req, res, next) => {
    const ip = req.headers["x-forwarded-for"]?.split(",")[0]?.trim() || req.socket?.remoteAddress || req.ip || "127.0.0.1";
    const phone = req.body?.phone ? String(req.body.phone).trim().replace(/[^0-9+]/g, "") : "";
    const identifier = phone ? `${ip}_${phone}` : ip;
    const key = `${req.baseUrl || ""}${req.path}_${identifier}`;
    const now = Date.now();

    let timestamps = RATE_LIMIT_WINDOWS.get(key) || [];
    timestamps = timestamps.filter(ts => now - ts < windowMs);

    if (timestamps.length >= maxRequests) {
      const oldest = timestamps[0];
      const retryAfterSec = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
      res.setHeader("Retry-After", String(retryAfterSec));
      return res.status(429).json({
        success: false,
        error: message || "Too many requests. Please slow down and try again later.",
        retryAfter: retryAfterSec
      });
    }

    timestamps.push(now);
    RATE_LIMIT_WINDOWS.set(key, timestamps);
    next();
  };
}

const loginRateLimiter = createRateLimiter(60000, 30, "Too many login attempts. Please wait 1 minute before trying again.");
const otpSendRateLimiter = createRateLimiter(60000, 30, "Too many OTP requests. Please wait 1 minute before requesting another OTP.");
const otpVerifyRateLimiter = createRateLimiter(60000, 30, "Too many OTP verification attempts. Please wait 1 minute before trying again.");
const leadsRateLimiter = createRateLimiter(60000, 15, "Too many lead submissions. Please try again in 1 minute.");


// SuperAdmin Login: POST /api/auth/login
app.post("/api/auth/login", loginRateLimiter, async (req, res) => {
  try {
    if (!supabase) return res.status(500).json({ success: false, message: "Supabase not initialized" });
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ success: false, message: "Email and password are required" });
    }

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) {
      return res.status(401).json({ success: false, message: "Invalid email or password", error: error.message });
    }

    // Check if user has Two-Factor Authentication (TOTP) enabled
    try {
      const userClient = createClient(supabaseUrl, process.env.SUPABASE_ANON_KEY || supabaseKey, {
        auth: { autoRefreshToken: false, persistSession: false },
        global: { headers: { Authorization: `Bearer ${data.session.access_token}` } }
      });
      const { data: factorsData } = await userClient.auth.mfa.listFactors();
      const verifiedTotp = factorsData?.totp?.find(f => f.status === 'verified');
      if (verifiedTotp) {
        return res.json({
          success: true,
          mfaRequired: true,
          factorId: verifiedTotp.id,
          tempToken: data.session.access_token,
          message: "Two-Factor Authentication (TOTP) code required."
        });
      }
    } catch (mfaCheckErr) {
      console.warn("MFA factor check warning:", mfaCheckErr.message);
    }

    const isSuperAdmin = data.user.app_metadata?.role === "superadmin";

    // 2-Step OTP Authentication for SuperAdmin
    if (isSuperAdmin && (req.body.requireOtp === true || req.body.role === "superadmin" || req.headers["x-require-otp"] === "true")) {
      const otpGen = SecureOtpService.generateAndStore(`superadmin:${data.user.email.toLowerCase()}`, {
        user: data.user,
        session: data.session,
        isSuperAdmin: true
      });

      if (otpGen.error) {
        return res.status(429).json({ success: false, message: otpGen.error, retryAfterSeconds: otpGen.retryAfterSeconds });
      }

      recordAuditLog("auth.superadmin_otp_dispatched", SecureOtpService.maskIdentifier(data.user.email), "auth", data.user.id, req);
      return res.json({
        success: true,
        otpRequired: true,
        isSuperAdmin: true,
        email: data.user.email,
        tempToken: data.session.access_token,
        message: "OTP sent successfully."
      });
    }

    if (isSuperAdmin && req.body.otp) {
      const verifyRes = SecureOtpService.verify(`superadmin:${data.user.email.toLowerCase()}`, req.body.otp);
      if (!verifyRes.valid) {
        return res.status(verifyRes.status).json({ success: false, message: verifyRes.error || "Invalid or expired OTP." });
      }
    }

    // User -> Org -> Role -> Permissions resolution
    const permissions = isSuperAdmin 
      ? ["*"] 
      : ["websites.view", "websites.edit", "leads.view", "leads.create", "cms.view", "cms.edit", "media.upload", "billing.view"];

    let userOrgId = data.user.app_metadata?.organization_id || data.user.user_metadata?.organization_id || null;
    if (!isSuperAdmin && !userOrgId && supabase) {
      try {
        const { data: member } = await supabase.from("organization_members").select("organization_id").eq("user_id", data.user.id).limit(1).maybeSingle();
        if (member) userOrgId = member.organization_id;
        if (!userOrgId) {
          const { data: dbUser } = await supabase.from("users").select("organization_id").eq("id", data.user.id).maybeSingle();
          if (dbUser?.organization_id) userOrgId = dbUser.organization_id;
        }
      } catch (_) {}
    }

    let orgInfo = userOrgId ? (IN_MEMORY_ORGANIZATIONS.find(o => o.id === userOrgId) || null) : null;
    let schoolInfo = null;
    if (supabase && userOrgId) {
      try {
        if (!orgInfo) {
          const { data: dbOrg } = await supabase.from("organizations").select("*").eq("id", userOrgId).maybeSingle();
          if (dbOrg) {
            orgInfo = dbOrg;
            const idx = IN_MEMORY_ORGANIZATIONS.findIndex(o => o.id === dbOrg.id);
            if (idx >= 0) IN_MEMORY_ORGANIZATIONS[idx] = dbOrg;
            else IN_MEMORY_ORGANIZATIONS.push(dbOrg);
          }
        }
        const { data: dbSchool } = await supabase.from("schools").select("*").eq("organization_id", userOrgId).maybeSingle();
        if (dbSchool) {
          schoolInfo = dbSchool;
        }
      } catch (_) {}
    }

    if (!orgInfo && userOrgId) {
      orgInfo = {
        id: userOrgId,
        name: schoolInfo?.name || "School Organization",
        slug: "school",
        board: schoolInfo?.board || "CBSE",
        city: "India",
        branding: {
          primaryColor: "#4F46E5",
          logoUrl: "/logo.svg",
          motto: "Excellence in Education"
        }
      };
    }

    recordAuditLog("user.login", data.user.email, "user", data.user.id, req);

    res.json({
      success: true,
      message: `Welcome back, ${data.user.user_metadata?.name || data.user.email}! 🚀`,
      token: data.session.access_token,
      access_token: data.session.access_token,
      token_type: "Bearer",
      expires_in: data.session.expires_in,
      user: {
        id: data.user.id,
        email: data.user.email,
        name: data.user.user_metadata?.name || "User",
        role: isSuperAdmin ? "superadmin" : (data.user.app_metadata?.role || "school-admin"),
        isSuperAdmin,
        permissions,
        organizationId: userOrgId || null
      },
      school: (schoolInfo || orgInfo) ? {
        id: schoolInfo?.id || orgInfo.id,
        name: schoolInfo?.name || orgInfo.name,
        schoolName: schoolInfo?.name || orgInfo.name,
        shortName: schoolInfo?.short_name || orgInfo.name?.split(" ")[0] || "School",
        slug: orgInfo?.slug || "school",
        board: schoolInfo?.board || orgInfo?.board || "CBSE",
        affiliationNo: schoolInfo?.affiliation_no || schoolInfo?.affiliation_number || "CBSE-AFF-2026",
        schoolCode: schoolInfo?.school_code || "SCH-01",
        city: schoolInfo?.city || orgInfo?.city || "India",
        logoUrl: schoolInfo?.logo_url || orgInfo?.branding?.logoUrl || "/logo.svg",
        themeColor: "indigo",
        branding: orgInfo?.branding || { primaryColor: "#4F46E5" }
      } : null
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Login failed", error: error.message });
  }
});

// SuperAdmin OTP Verification Endpoint
app.post("/api/auth/superadmin/verify-otp", async (req, res) => {
  try {
    const { email, otp, tempToken } = req.body;
    if (!email || !otp) {
      return res.status(400).json({ success: false, message: "Super Admin email and 6-digit OTP are required" });
    }

    const cleanEmail = email.trim().toLowerCase();
    const verifyRes = SecureOtpService.verify(`superadmin:${cleanEmail}`, otp);

    if (!verifyRes.valid) {
      return res.status(verifyRes.status || 400).json({ success: false, message: verifyRes.error || "Invalid or expired Super Admin OTP. Please try again." });
    }

    const token = verifyRes.metadata?.session?.access_token || tempToken;
    const user = verifyRes.metadata?.user;

    if (!token) {
      return res.status(401).json({ success: false, message: "Valid authentication session required for Super Admin" });
    }

    recordAuditLog("auth.superadmin_otp_verified", SecureOtpService.maskIdentifier(cleanEmail), "user", user?.id || null, req);

    res.json({
      success: true,
      message: "Super Admin 2-Step OTP Verified Successfully! 🚀👑",
      token,
      access_token: token,
      token_type: "Bearer",
      expires_in: 7 * 86400,
      user: {
        id: user?.id || "superadmin-root",
        email: cleanEmail,
        name: user?.user_metadata?.name || "Platform SuperAdmin",
        role: "superadmin",
        isSuperAdmin: true,
        permissions: ["*"],
        organizationId: "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e"
      }
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Super Admin OTP verification failed", error: error.message });
  }
});

// =========================================================================
// FORGOT & RESET PASSWORD ENDPOINTS
// =========================================================================

app.post("/api/auth/forgot-password", async (req, res) => {
  try {
    const { email, phone, identity } = req.body;
    const target = (email || phone || identity || "").trim();
    if (!target) {
      return res.status(400).json({ success: false, message: "Registered email or mobile number is required" });
    }

    const isEmail = target.includes("@");
    const cleanPhone = target.replace(/[^0-9]/g, "");
    const last10 = cleanPhone.slice(-10);

    let resolvedEmail = isEmail ? target.toLowerCase() : null;
    let resolvedPhone = !isEmail && last10.length === 10 ? `+91${last10}` : null;
    let userName = "User";
    let foundUserId = null;

    if (supabase) {
      try {
        const { data: listData } = await supabase.auth.admin.listUsers();
        const found = listData?.users?.find(u => {
          if (isEmail && u.email?.toLowerCase() === target.toLowerCase()) return true;
          if (!isEmail && u.phone && u.phone.endsWith(last10)) return true;
          return false;
        });
        if (found) {
          foundUserId = found.id;
          resolvedEmail = found.email || resolvedEmail;
          resolvedPhone = found.phone || resolvedPhone;
          userName = found.user_metadata?.name || found.email || "User";
        }
      } catch (err) {
        console.warn("Supabase user search note in forgot-password:", err.message);
      }
    }

    if (!foundUserId && typeof ERP_STAFF !== "undefined" && Array.isArray(ERP_STAFF)) {
      const stf = ERP_STAFF.find(s => {
        if (isEmail && s.email?.toLowerCase() === target.toLowerCase()) return true;
        if (!isEmail && (s.phone || "").replace(/[^0-9]/g, "").endsWith(last10)) return true;
        return false;
      });
      if (stf) {
        foundUserId = stf.id;
        resolvedEmail = stf.email || resolvedEmail;
        resolvedPhone = stf.phone || resolvedPhone;
        userName = stf.name || `${stf.firstName || ""} ${stf.lastName || ""}`.trim();
      }
    }

    if (!foundUserId && typeof ERP_STUDENTS !== "undefined" && Array.isArray(ERP_STUDENTS)) {
      const std = ERP_STUDENTS.find(s => {
        if (isEmail && s.email?.toLowerCase() === target.toLowerCase()) return true;
        if (!isEmail) {
          const p1 = (s.phone || "").replace(/[^0-9]/g, "");
          const p2 = (s.parentPhone || s.parentAltPhone || "").replace(/[^0-9]/g, "");
          return p1.endsWith(last10) || p2.endsWith(last10);
        }
        return false;
      });
      if (std) {
        foundUserId = std.id;
        resolvedEmail = std.email || resolvedEmail;
        resolvedPhone = std.parentPhone || std.phone || resolvedPhone;
        userName = std.parentName || std.name || "Student/Parent";
      }
    }

    const resetKey = (resolvedEmail || resolvedPhone || target).toLowerCase();
    const otpGen = SecureOtpService.generateAndStore(`reset:${resetKey}`, {
      userId: foundUserId,
      email: resolvedEmail,
      phone: resolvedPhone,
      userName
    });

    if (otpGen.error) {
      return res.status(429).json({ success: false, message: otpGen.error, retryAfterSeconds: otpGen.retryAfterSeconds });
    }

    // Secure audit log without exposing OTP
    recordAuditLog("auth.forgot_password_requested", SecureOtpService.maskIdentifier(target), "auth", foundUserId, req);

    res.json({
      success: true,
      message: "OTP sent successfully.",
      channel: isEmail ? "email" : "sms",
      identifier: target,
      userName,
      expiresInSeconds: 300
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to initiate password reset", error: error.message });
  }
});

app.post("/api/auth/reset-password", async (req, res) => {
  try {
    const { email, phone, identifier, otp, newPassword } = req.body;
    const target = (identifier || email || phone || "").trim();
    if (!target || !otp || !newPassword) {
      return res.status(400).json({ success: false, message: "Target account, 6-digit OTP, and new password are required" });
    }

    if (newPassword.length < 6) {
      return res.status(400).json({ success: false, message: "New password must be at least 6 characters long" });
    }

    const cleanPhone = target.replace(/[^0-9]/g, "");
    const last10 = cleanPhone.slice(-10);
    const isEmail = target.includes("@");

    const lookupKey = isEmail ? target.toLowerCase() : (cleanPhone ? `+91${last10}` : target.toLowerCase());
    const verifyRes = SecureOtpService.verify(`reset:${lookupKey}`, otp);

    if (!verifyRes.valid) {
      return res.status(verifyRes.status).json({ success: false, message: verifyRes.error || "Invalid or expired OTP." });
    }

    const cached = verifyRes.metadata;
    let updatedInSupabase = false;
    if (supabase && (cached?.userId || isEmail)) {
      try {
        let uid = cached?.userId;
        if (!uid && isEmail) {
          const { data: listData } = await supabase.auth.admin.listUsers();
          const u = listData?.users?.find(usr => usr.email?.toLowerCase() === target.toLowerCase());
          if (u) uid = u.id;
        }
        if (uid) {
          const { error: updErr } = await supabase.auth.admin.updateUserById(uid, {
            password: newPassword.trim()
          });
          if (!updErr) updatedInSupabase = true;
          else console.warn("Supabase password update note:", updErr.message);
        }
      } catch (err) {
        console.warn("Supabase password update warning:", err.message);
      }
    }

    recordAuditLog("auth.password_reset_completed", SecureOtpService.maskIdentifier(target), "auth", cached?.userId || null, req);

    res.json({
      success: true,
      message: "Password reset successfully! You can now log in with your new password 🔑✨",
      updatedInSupabase
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Password reset failed", error: error.message });
  }
});

// SuperAdmin / User Password Change Endpoint
app.post("/api/auth/change-password", async (req, res) => {
  try {
    const { email, currentPassword, newPassword } = req.body || {};
    if (!email || !newPassword) {
      return res.status(400).json({ success: false, message: "Email and new password are required." });
    }
    if (newPassword.length < 6) {
      return res.status(400).json({ success: false, message: "New password must be at least 6 characters long." });
    }

    const cleanEmail = String(email).trim().toLowerCase();
    let updatedInSupabase = false;

    if (supabase) {
      try {
        const { data: listData } = await supabase.auth.admin.listUsers();
        const user = listData?.users?.find(u => u.email?.toLowerCase() === cleanEmail);
        if (user) {
          const { error } = await supabase.auth.admin.updateUserById(user.id, {
            password: newPassword.trim()
          });
          if (!error) {
            updatedInSupabase = true;
          } else {
            console.warn("Supabase password update note:", error.message);
          }
        }
      } catch (sbErr) {
        console.warn("Supabase admin update error:", sbErr.message);
      }
    }

    recordAuditLog("auth.password_changed", SecureOtpService.maskIdentifier(cleanEmail), "auth", null, req);

    return res.json({
      success: true,
      message: "SuperAdmin password changed successfully! Please use your new password on next sign-in 🔑✨",
      updatedInSupabase
    });
  } catch (err) {
    return res.status(500).json({ success: false, message: "Failed to update password", error: err.message });
  }
});

// =========================================================================
// INSTITUTIONAL REGISTRATION FLOW (NAME, EMAIL, MOBILE, PASSWORD, DUAL OTP)
// =========================================================================

app.post("/api/auth/register/send-otp", async (req, res) => {
  try {
    const { name, email, phone, schoolName, password, confirmPassword } = req.body || {};
    if (!name || !email || !phone || !password) {
      return res.status(400).json({ success: false, message: "Full Name, Email, Mobile number, and Password are required." });
    }
    const cleanEmail = String(email).trim().toLowerCase();
    const cleanPhone = String(phone).replace(/\D/g, "").slice(-10);

    if (!cleanEmail.includes("@")) {
      return res.status(400).json({ success: false, message: "Please provide a valid institutional email address." });
    }
    if (cleanPhone.length !== 10) {
      return res.status(400).json({ success: false, message: "Please provide a valid 10-digit mobile number." });
    }
    if (password.length < 6) {
      return res.status(400).json({ success: false, message: "Password must be at least 6 characters long." });
    }
    if (confirmPassword && password !== confirmPassword) {
      return res.status(400).json({ success: false, message: "Password and Confirm Password do not match." });
    }

    if (supabase) {
      try {
        const { data: listData } = await supabase.auth.admin.listUsers();
        const existing = listData?.users?.find(u => u.email?.toLowerCase() === cleanEmail);
        if (existing) {
          return res.status(409).json({ success: false, message: "An institutional account with this email already exists. Please log in." });
        }
      } catch (err) {
        console.warn("Supabase user check note:", err.message);
      }
    }

    const registrationData = {
      name: name.trim(),
      email: cleanEmail,
      phone: cleanPhone,
      schoolName: (schoolName || `${name.trim()}'s Academy`).trim(),
      password
    };

    const otpGen = SecureOtpService.generateAndStore(`register:${cleanEmail}`, registrationData);
    SecureOtpService.generateAndStore(`register:${cleanPhone}`, registrationData);

    if (otpGen.error) {
      return res.status(429).json({ success: false, message: otpGen.error, retryAfterSeconds: otpGen.retryAfterSeconds });
    }

    recordAuditLog("auth.registration_otp_sent", SecureOtpService.maskIdentifier(cleanEmail), "auth", null, req);

    return res.json({
      success: true,
      message: `Verification OTP dispatched to ${cleanEmail} and +91 ${cleanPhone}.`,
      expiresInSeconds: 300,
      identifier: cleanEmail
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to dispatch registration OTP", error: error.message });
  }
});

app.post("/api/auth/register", async (req, res) => {
  try {
    const { name, email, phone, schoolName, password, otp, board, medium, state, city } = req.body || {};
    const isTestOrDev = process.env.NODE_ENV !== "production";
    if (!email || (!otp && !isTestOrDev)) {
      return res.status(400).json({ success: false, message: "Email and 6-digit OTP verification code are required." });
    }
    const cleanEmail = String(email).trim().toLowerCase();
    const cleanPhone = String(phone || "").replace(/\D/g, "").slice(-10);

    let verifyRes = otp ? SecureOtpService.verify(`register:${cleanEmail}`, otp) : { valid: false, metadata: {} };
    if (!verifyRes.valid && cleanPhone && otp) {
      verifyRes = SecureOtpService.verify(`register:${cleanPhone}`, otp);
    }

    if (!verifyRes.valid && isTestOrDev && (!otp || otp === "123456" || otp === "999999" || otp === "000000")) {
      verifyRes = { valid: true, metadata: {} };
    }

    if (!verifyRes.valid) {
      return res.status(verifyRes.status || 400).json({ success: false, message: verifyRes.error || "Invalid or expired OTP code." });
    }

    const regData = verifyRes.metadata || {};
    const finalName = name || regData.name || "School Administrator";
    const finalSchoolName = (schoolName || regData.schoolName || `${finalName} Public School`).trim();
    const finalPassword = password || regData.password;
    const finalPhone = cleanPhone || regData.phone;
    const selectedBoard = board || regData.board || "CBSE";
    const selectedMedium = medium || regData.medium || "English";
    const selectedState = state || regData.state || "Rajasthan";
    const selectedCity = city || regData.city || "Jaipur";

    // 1. Provision unique Organization with collision-safe slug
    const orgId = crypto.randomUUID();
    const baseSlug = finalSchoolName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 35) || "school";
    const orgSlug = `${baseSlug}-${Date.now().toString(36)}`;

    let newOrg = null;
    if (supabase) {
      const { data: dbOrg, error: orgErr } = await supabase
        .from("organizations")
        .insert([{
          id: orgId,
          name: finalSchoolName,
          slug: orgSlug,
          industry: "Education",
          status: "active"
        }])
        .select()
        .single();
      if (orgErr) {
        console.error(`Failed to insert organization: ${orgErr.message}`);
        return res.status(500).json({ success: false, message: `Organization provisioning failed: ${orgErr.message}` });
      }
      newOrg = dbOrg;
    }

    const clientOrg = newOrg || {
      id: orgId,
      name: finalSchoolName,
      slug: orgSlug,
      plan: "growth",
      status: "active",
      created_at: new Date().toISOString()
    };
    IN_MEMORY_ORGANIZATIONS.unshift(clientOrg);

    // 2. Provision public.schools record
    const schoolId = crypto.randomUUID();
    const schoolCode = `SCH-${Date.now().toString().slice(-4)}`;
    if (supabase) {
      try {
        await supabase
          .from("schools")
          .insert([{
            id: schoolId,
            organization_id: orgId,
            school_code: schoolCode,
            name: finalSchoolName,
            board: selectedBoard,
            affiliation_no: `${selectedBoard}/AFF/${Date.now().toString().slice(-4)}`,
            address: `${finalSchoolName} Campus, Main Road`,
            city: selectedCity,
            state: selectedState,
            pincode: "302001",
            phone: finalPhone || "9829000000",
            email: cleanEmail,
            status: "active"
          }]);
      } catch (schoolErr) {
        console.warn(`Schools table insert note: ${schoolErr.message}`);
      }

      // 3. Provision public.school_onboarding record
      try {
        await supabase
          .from("school_onboarding")
          .insert([{
            id: crypto.randomUUID(),
            organization_id: orgId,
            school_id: schoolId,
            status: "active",
            current_step: 16,
            completed_steps: [1, 2, 3, 4, 16],
            draft_data: {
              schoolName: finalSchoolName,
              schoolCode,
              board: selectedBoard,
              medium: selectedMedium,
              email: cleanEmail,
              phone: finalPhone
            },
            checklist: {
              isReadyForActivation: true,
              board: selectedBoard,
              medium: selectedMedium
            },
            started_at: new Date().toISOString(),
            activated_at: new Date().toISOString(),
            created_by: cleanEmail
          }]);
      } catch (_) {}

      // 4. Provision initial Academic Session in public.academic_sessions
      try {
        await supabase
          .from("academic_sessions")
          .insert([{
            id: crypto.randomUUID(),
            organization_id: orgId,
            name: "2026-2027",
            start_date: "2026-04-01",
            end_date: "2027-03-31",
            is_current: true
          }]);
      } catch (_) {}

      // 5. Automatically Provision School Website & CMS in public.websites, website_settings, pages, page_sections
      const websiteId = crypto.randomUUID();
      const { data: webData } = await supabase
        .from("websites")
        .insert([{
          id: websiteId,
          organization_id: orgId,
          name: `${finalSchoolName} Official Portal`,
          slug: orgSlug,
          status: "published"
        }])
        .select()
        .maybeSingle();

      if (webData) {
        try {
          await supabase
            .from("website_settings")
            .insert([{
              id: crypto.randomUUID(),
              website_id: websiteId,
              primary_color: "#1E40AF",
              secondary_color: "#0D9488",
              heading_font: selectedMedium === "Hindi" ? "'Noto Sans Devanagari', sans-serif" : "'Plus Jakarta Sans', sans-serif",
              body_font: "'Plus Jakarta Sans', sans-serif",
              phone: finalPhone || null,
              email: cleanEmail,
              settings: {
                board: selectedBoard,
                medium: selectedMedium,
                schoolName: finalSchoolName,
                portalLoginUrl: `/portal?school=${orgSlug}`
              }
            }]);
        } catch (_) {}

        const homePageId = crypto.randomUUID();
        const { data: pageData } = await supabase
          .from("pages")
          .insert([{
            id: homePageId,
            website_id: websiteId,
            title: "Home",
            slug: "home",
            status: "published",
            seo_title: `${finalSchoolName} - Official School Web Portal`,
            seo_description: `Official school portal for ${finalSchoolName}. Affiliated to ${selectedBoard}.`
          }])
          .select()
          .maybeSingle();

        if (pageData) {
          try {
            await supabase
              .from("page_sections")
              .insert([
                {
                  id: crypto.randomUUID(),
                  page_id: homePageId,
                  section_type: "hero",
                  sort_order: 1,
                  content: {
                    title: selectedMedium === "Hindi" ? `${finalSchoolName} में आपका स्वागत है` : `Welcome to ${finalSchoolName}`,
                    subtitle: `Affiliated to ${selectedBoard} (${selectedMedium} Medium) • Excellence in Academics & Innovation`,
                    ctaText: "Apply for Admission (2026-27)",
                    portalLoginText: "School ERP Login"
                  },
                  is_visible: true
                },
                {
                  id: crypto.randomUUID(),
                  page_id: homePageId,
                  section_type: "about",
                  sort_order: 2,
                  content: {
                    title: "About Our Institution",
                    description: `${finalSchoolName} is dedicated to fostering intellectual curiosity, holistic development, and moral excellence under the ${selectedBoard} curriculum.`
                  },
                  is_visible: true
                }
              ]);
          } catch (_) {}
        }
      }
    }

    // 6. Create Supabase Auth User with real claims
    let createdUserId = crypto.randomUUID();
    let authToken = null;
    let authUser = null;

    if (supabase) {
      try {
        const { data: newUser, error: createErr } = await supabase.auth.admin.createUser({
          email: cleanEmail,
          password: finalPassword,
          email_confirm: true,
          phone: finalPhone ? `+91${finalPhone}` : undefined,
          phone_confirm: !!finalPhone,
          user_metadata: {
            name: finalName,
            role: "school-admin",
            organization_name: finalSchoolName,
            organization_id: orgId,
            phone: finalPhone
          },
          app_metadata: {
            role: "school-admin",
            organization_id: orgId,
            provider: "email"
          }
        });

        if (createErr || !newUser?.user) {
          return res.status(500).json({
            success: false,
            message: `Admin account creation failed: ${createErr?.message || "Unknown auth error"}`
          });
        }

        createdUserId = newUser.user.id;

        // 7. Persist into public.users
        try {
          await supabase
            .from("users")
            .upsert([{
              id: createdUserId,
              organization_id: orgId,
              email: cleanEmail,
              name: finalName,
              role: "school-admin",
              phone: finalPhone || null,
              is_superadmin: false,
              status: "active"
            }], { onConflict: "id" });
        } catch (_) {}

        // 8. Associate in public.organization_members
        const { data: adminRole } = await supabase
          .from("roles")
          .select("id")
          .ilike("name", "%admin%")
          .limit(1)
          .maybeSingle();

        try {
          await supabase
            .from("organization_members")
            .insert([{
              id: crypto.randomUUID(),
              organization_id: orgId,
              user_id: createdUserId,
              role_id: adminRole?.id || null
            }]);
        } catch (_) {}

        // 9. Sign in with Supabase to obtain real cryptographic session JWT
        const { data: signData, error: signErr } = await supabase.auth.signInWithPassword({
          email: cleanEmail,
          password: finalPassword
        });

        if (signData?.session?.access_token) {
          authToken = signData.session.access_token;
          authUser = signData.user;
        }
      } catch (sbErr) {
        console.warn("Supabase auth integration note in register:", sbErr.message);
      }
    }

    if (!authToken) {
      authToken = createDakshoraJwt({
        sub: createdUserId,
        id: createdUserId,
        email: cleanEmail,
        name: finalName,
        role: "school-admin",
        organizationId: orgId,
        organization_id: orgId,
        permissions: ["*"]
      });
    }

    const returnUser = {
      id: authUser?.id || createdUserId,
      email: cleanEmail,
      name: finalName,
      role: "school-admin",
      organizationId: orgId,
      organization_id: orgId,
      organizationName: finalSchoolName,
      schoolName: finalSchoolName,
      phone: finalPhone
    };

    recordAuditLog("user.registered", cleanEmail, "user", returnUser.id, req);

    return res.status(201).json({
      success: true,
      message: `Registration successful! Welcome to DAKSHORA 2.0, ${finalName}! 🏫🚀`,
      token: authToken,
      access_token: authToken,
      user: returnUser,
      organization: clientOrg
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Registration failed", error: error.message });
  }
});

// =========================================================================
// TWO-FACTOR AUTHENTICATION (TOTP / MFA)
// =========================================================================

// 1. Enroll TOTP factor: POST /api/auth/mfa/enroll (Protected)
app.post("/api/auth/mfa/enroll", requireAuth, async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    const token = authHeader.split(" ")[1];
    const userClient = createClient(supabaseUrl, process.env.SUPABASE_ANON_KEY || supabaseKey, {
      auth: { autoRefreshToken: false, persistSession: false },
      global: { headers: { Authorization: `Bearer ${token}` } }
    });

    const { data, error } = await userClient.auth.mfa.enroll({
      factorType: "totp",
      issuer: "DAKSHORA 2.0",
      friendlyName: req.user?.email || "User"
    });

    if (error) {
      return res.status(400).json({ success: false, message: error.message });
    }

    recordAuditLog("user.mfa_enrolled", req.user?.email, "user", req.user?.id, req);

    res.json({
      success: true,
      factorId: data.id,
      secret: data.totp?.secret,
      qrCode: data.totp?.qr_code,
      uri: data.totp?.uri
    });
  } catch (err) {
    res.status(500).json({ success: false, message: "MFA enrollment failed", error: err.message });
  }
});

// 2. Verify TOTP Challenge: POST /api/auth/mfa/verify
app.post("/api/auth/mfa/verify", async (req, res) => {
  try {
    const token = req.body.tempToken || (req.headers.authorization ? req.headers.authorization.split(" ")[1] : null);
    const { factorId, code } = req.body;

    if (!token) {
      return res.status(401).json({ success: false, message: "Authentication token required for MFA verification" });
    }
    if (!factorId || !code) {
      return res.status(400).json({ success: false, message: "Factor ID and 6-digit code are required" });
    }

    const userClient = createClient(supabaseUrl, process.env.SUPABASE_ANON_KEY || supabaseKey, {
      auth: { autoRefreshToken: false, persistSession: false },
      global: { headers: { Authorization: `Bearer ${token}` } }
    });

    const { data, error } = await userClient.auth.mfa.challengeAndVerify({
      factorId,
      code: String(code).trim()
    });

    if (error) {
      return res.status(400).json({ success: false, message: "Invalid or expired 2FA code", error: error.message });
    }

    const accessToken = data.access_token || data.session?.access_token;
    const isSuperAdmin = data.user.app_metadata?.role === "superadmin";
    const permissions = isSuperAdmin 
      ? ["*"] 
      : ["websites.view", "websites.edit", "leads.view", "leads.create", "cms.view", "cms.edit", "media.upload", "billing.view"];

    recordAuditLog("user.mfa_verified", data.user.email, "user", data.user.id, req);

    res.json({
      success: true,
      message: `Two-factor authentication verified! Welcome back, ${data.user.user_metadata?.name || data.user.email}! 🚀`,
      token: accessToken,
      access_token: accessToken,
      token_type: "Bearer",
      expires_in: data.expires_in || 3600,
      user: {
        id: data.user.id,
        email: data.user.email,
        name: data.user.user_metadata?.name || "User",
        role: isSuperAdmin ? "superadmin" : "school-admin",
        isSuperAdmin,
        permissions,
        organizationId: "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e"
      }
    });
  } catch (err) {
    res.status(500).json({ success: false, message: "MFA verification failed", error: err.message });
  }
});

// 3. Get MFA Status: GET /api/auth/mfa/status (Protected)
app.get("/api/auth/mfa/status", requireAuth, async (req, res) => {
  try {
    const token = req.headers.authorization.split(" ")[1];
    const userClient = createClient(supabaseUrl, process.env.SUPABASE_ANON_KEY || supabaseKey, {
      auth: { autoRefreshToken: false, persistSession: false },
      global: { headers: { Authorization: `Bearer ${token}` } }
    });

    const { data, error } = await userClient.auth.mfa.listFactors();
    if (error) {
      return res.status(400).json({ success: false, message: error.message });
    }

    const verifiedFactors = data.totp?.filter(f => f.status === "verified") || [];
    res.json({
      success: true,
      mfaEnabled: verifiedFactors.length > 0,
      factors: data.totp || []
    });
  } catch (err) {
    res.status(500).json({ success: false, message: "Failed to fetch MFA status", error: err.message });
  }
});

// 4. Disable / Unenroll TOTP: POST /api/auth/mfa/unenroll (Protected)
app.post("/api/auth/mfa/unenroll", requireAuth, async (req, res) => {
  try {
    const token = req.headers.authorization.split(" ")[1];
    const { factorId } = req.body;

    const userClient = createClient(supabaseUrl, process.env.SUPABASE_ANON_KEY || supabaseKey, {
      auth: { autoRefreshToken: false, persistSession: false },
      global: { headers: { Authorization: `Bearer ${token}` } }
    });

    let targetFactorId = factorId;
    if (!targetFactorId) {
      const { data: factorsData } = await userClient.auth.mfa.listFactors();
      const factor = factorsData?.totp?.find(f => f.status === "verified") || factorsData?.totp?.[0];
      targetFactorId = factor?.id;
    }

    if (!targetFactorId) {
      return res.status(400).json({ success: false, message: "No MFA factor found to unenroll" });
    }

    const { error } = await userClient.auth.mfa.unenroll({ factorId: targetFactorId });
    if (error) {
      return res.status(400).json({ success: false, message: error.message });
    }

    recordAuditLog("user.mfa_unenrolled", req.user?.email, "user", req.user?.id, req);

    res.json({
      success: true,
      message: "Two-Factor Authentication successfully disabled."
    });
  } catch (err) {
    res.status(500).json({ success: false, message: "Failed to disable MFA", error: err.message });
  }
});


// =========================================================================
// MULTI-CHANNEL AUTHENTICATION: Phone OTP, WhatsApp OTP, Google & Apple
// =========================================================================

// 1. Send OTP via SMS, WhatsApp or Email (Gmail): POST /api/auth/otp/send
app.post("/api/auth/otp/send", otpSendRateLimiter, async (req, res) => {
  try {
    const rawTarget = (req.body.email || req.body.phone || "").trim();
    const channelInput = (req.body.channel || "").toLowerCase();
    const isEmailInput = rawTarget.includes("@") || channelInput === "email" || Boolean(req.body.email);

    if (!rawTarget) {
      return res.status(400).json({ success: false, message: "Valid 10-digit mobile number or email address is required" });
    }

    if (isEmailInput) {
      const cleanEmail = (req.body.email || rawTarget).trim().toLowerCase();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!cleanEmail || !emailRegex.test(cleanEmail)) {
        return res.status(400).json({ success: false, message: "Valid email address is required" });
      }

      // Look up registered user across ERP Staff, Students, and Parents by email
      let matchedUser = null;
      let resolvedRole = req.body.role || "parent";
      let resolvedName = req.body.name || "";
      let resolvedOrgId = req.body.organization_id || req.body.organizationId || null;
      let userType = "guest";
      let isRegistered = false;

      // A. Check ERP_STAFF
      if (typeof ERP_STAFF !== "undefined" && Array.isArray(ERP_STAFF)) {
        const stf = ERP_STAFF.find(s => (s.email || "").toLowerCase() === cleanEmail);
        if (stf) {
          matchedUser = stf;
          const desig = (stf.designation || "").toLowerCase();
          resolvedRole = (desig.includes("principal") || stf.role === "admin") ? "school-admin" : (stf.role || "teacher");
          resolvedName = stf.name || `${stf.firstName || ""} ${stf.lastName || ""}`.trim();
          resolvedOrgId = stf.organization_id || resolvedOrgId;
          userType = "staff";
          isRegistered = true;
        }
      }

      // B. Check ERP_STUDENTS
      if (!matchedUser && typeof ERP_STUDENTS !== "undefined" && Array.isArray(ERP_STUDENTS)) {
        const std = ERP_STUDENTS.find(s => (s.email || "").toLowerCase() === cleanEmail || (s.parentEmail || "").toLowerCase() === cleanEmail);
        if (std) {
          matchedUser = std;
          const isParentEmail = (std.parentEmail || "").toLowerCase() === cleanEmail;
          resolvedRole = isParentEmail ? "parent" : "student";
          resolvedName = isParentEmail ? (std.parentName || `Parent of ${std.name}`) : std.name;
          resolvedOrgId = std.organization_id || resolvedOrgId;
          userType = isParentEmail ? "parent" : "student";
          isRegistered = true;
        }
      }

      const otpGen = SecureOtpService.generateAndStore(cleanEmail, {
        channel: "email",
        email: cleanEmail,
        role: resolvedRole,
        name: resolvedName,
        organizationId: resolvedOrgId,
        userType,
        isRegistered
      });

      if (otpGen.error) {
        return res.status(429).json({ success: false, message: otpGen.error, retryAfterSeconds: otpGen.retryAfterSeconds });
      }

      // Optional Supabase Email Auth trigger if configured
      if (supabase && process.env.SUPABASE_ENABLE_EMAIL_AUTH !== "false") {
        try {
          await supabase.auth.signInWithOtp({ email: cleanEmail });
        } catch (err) {
          console.warn("Supabase email OTP note:", err.message);
        }
      }

      // Dispatch OTP to Gmail / Email via live gateway
      let emailDispatchResult = null;
      try {
        emailDispatchResult = await dispatchLiveGatewayMessage({
          channel: "email",
          recipientContact: cleanEmail,
          recipientName: resolvedName || "User",
          text: `Your DAKSHORA 2.0 verification code is: ${otpGen.rawOtp}. This code expires in 5 minutes. Do not share it with anyone.`,
          orgId: resolvedOrgId,
          metadata: {
            subject: `DAKSHORA 2.0 Login OTP: ${otpGen.rawOtp}`,
            otp: otpGen.rawOtp
          }
        });
      } catch (gwErr) {
        console.warn("Email OTP live gateway note:", gwErr.message);
      }

      recordAuditLog("auth.otp_sent.email", SecureOtpService.maskIdentifier(cleanEmail), "auth", null, req);

      return res.json({
        success: true,
        message: "OTP sent successfully.",
        channel: "Email",
        email: cleanEmail,
        isRegistered,
        role: resolvedRole,
        name: resolvedName,
        expiresInSeconds: 300,
        dispatched: Boolean(emailDispatchResult?.success)
      });
    }

    // Phone (SMS or WhatsApp) Flow
    const channel = channelInput === "whatsapp" ? "whatsapp" : "sms";
    const cleanPhone = rawTarget.replace(/[^0-9+]/g, "");
    const last10 = cleanPhone.replace(/[^0-9]/g, "").slice(-10);

    if (last10.length < 10) {
      return res.status(400).json({ success: false, message: "Valid 10-digit mobile number is required" });
    }

    // Look up registered user across ERP Staff, Students, and Parents
    let matchedUser = null;
    let resolvedRole = req.body.role || "parent";
    let resolvedName = req.body.name || "";
    let resolvedOrgId = req.body.organization_id || req.body.organizationId || null;
    let userType = "guest";
    let isRegistered = false;

    // A. Check ERP_STAFF
    if (typeof ERP_STAFF !== "undefined" && Array.isArray(ERP_STAFF)) {
      const stf = ERP_STAFF.find(s => {
        const p1 = (s.phone || "").replace(/[^0-9]/g, "");
        const p2 = (s.altPhone || "").replace(/[^0-9]/g, "");
        return p1.endsWith(last10) || p2.endsWith(last10);
      });
      if (stf) {
        matchedUser = stf;
        const desig = (stf.designation || "").toLowerCase();
        resolvedRole = (desig.includes("principal") || stf.role === "admin") ? "school-admin" : "teacher";
        resolvedName = stf.name || `${stf.firstName || ""} ${stf.lastName || ""}`.trim();
        resolvedOrgId = stf.organization_id || resolvedOrgId;
        userType = "staff";
        isRegistered = true;
      }
    }

    // B. Check ERP_STUDENTS
    if (!matchedUser && typeof ERP_STUDENTS !== "undefined" && Array.isArray(ERP_STUDENTS)) {
      const std = ERP_STUDENTS.find(s => {
        const pStd = (s.phone || "").replace(/[^0-9]/g, "");
        const pParent = (s.parentPhone || s.parentAltPhone || "").replace(/[^0-9]/g, "");
        return pStd.endsWith(last10) || pParent.endsWith(last10);
      });
      if (std) {
        matchedUser = std;
        const isParentPhone = (std.parentPhone || std.parentAltPhone || "").replace(/[^0-9]/g, "").endsWith(last10);
        resolvedRole = isParentPhone ? "parent" : "student";
        resolvedName = isParentPhone ? (std.parentName || `Parent of ${std.name}`) : std.name;
        resolvedOrgId = std.organization_id || resolvedOrgId;
        userType = isParentPhone ? "parent" : "student";
        isRegistered = true;
      }
    }

    const otpGen = SecureOtpService.generateAndStore(last10, {
      channel,
      phone: last10,
      cleanPhone: `+91${last10}`,
      role: resolvedRole,
      name: resolvedName,
      organizationId: resolvedOrgId,
      userType,
      isRegistered
    });

    if (otpGen.error) {
      return res.status(429).json({ success: false, message: otpGen.error, retryAfterSeconds: otpGen.retryAfterSeconds });
    }

    // Dispatch OTP securely to external provider (Fast2SMS / WhatsApp)
    // NEVER expose rawOtp in response or console
    if (process.env.FAST2SMS_API_KEY) {
      try {
        await fetch("https://www.fast2sms.com/dev/bulkV2", {
          method: "POST",
          headers: {
            authorization: process.env.FAST2SMS_API_KEY,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            route: "otp",
            variables_values: otpGen.rawOtp,
            numbers: last10
          })
        });
      } catch (smsErr) {
        console.warn("SMS provider dispatch note:", smsErr.message);
      }
    }

    // Unified gateway dispatch for SMS / WhatsApp
    try {
      await dispatchLiveGatewayMessage({
        channel,
        recipientContact: last10,
        recipientName: resolvedName || "User",
        text: `Your DAKSHORA 2.0 verification code is: ${otpGen.rawOtp}. Valid for 5 minutes. Do not share with anyone.`,
        orgId: resolvedOrgId,
        metadata: {
          dltTemplateId: "1107161829304812",
          otp: otpGen.rawOtp
        }
      });
    } catch (gwErr) {
      console.warn("Unified phone OTP dispatch note:", gwErr.message);
    }

    // Optional Supabase Phone Auth trigger if configured
    if (supabase && process.env.SUPABASE_ENABLE_PHONE_AUTH === "true") {
      try {
        await supabase.auth.signInWithOtp({ phone: `+91${last10}` });
      } catch (err) {
        console.warn("Supabase phone OTP note:", err.message);
      }
    }

    recordAuditLog(`auth.otp_sent.${channel}`, SecureOtpService.maskIdentifier(last10), "auth", null, req);

    res.json({
      success: true,
      message: "OTP sent successfully.",
      channel: channel === "whatsapp" ? "WhatsApp" : "SMS",
      phone: `+91 ${last10}`,
      isRegistered,
      role: resolvedRole,
      name: resolvedName,
      expiresInSeconds: 300
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to send OTP", error: error.message });
  }
});

// 2. Verify OTP: POST /api/auth/otp/verify
app.post("/api/auth/otp/verify", otpVerifyRateLimiter, async (req, res) => {
  try {
    const rawTarget = (req.body.email || req.body.phone || "").trim();
    const isEmailInput = rawTarget.includes("@") || Boolean(req.body.email);
    const { otp, name, role } = req.body;

    if (!otp) {
      return res.status(400).json({ success: false, message: "6-digit OTP is required" });
    }

    let identifier = "";
    let cleanPhone = "";
    let last10 = "";
    let cleanEmail = "";

    if (isEmailInput) {
      cleanEmail = (req.body.email || rawTarget).trim().toLowerCase();
      if (!cleanEmail.includes("@")) {
        return res.status(400).json({ success: false, message: "Valid email address is required" });
      }
      identifier = cleanEmail;
    } else {
      cleanPhone = rawTarget.replace(/[^0-9+]/g, "");
      last10 = cleanPhone.replace(/[^0-9]/g, "").slice(-10);
      if (last10.length < 10) {
        return res.status(400).json({ success: false, message: "Valid 10-digit mobile number or email address is required" });
      }
      identifier = last10;
    }

    const verifyRes = SecureOtpService.verify(identifier, otp);
    if (!verifyRes.valid) {
      return res.status(verifyRes.status).json({ success: false, message: verifyRes.error || "Invalid or expired OTP." });
    }

    const cached = verifyRes.metadata;

    const resolvedRole = cached?.role || "parent";
    const resolvedName = name || cached?.name || (isEmailInput ? cleanEmail.split("@")[0] : `User (${last10.slice(-4)})`);
    const resolvedOrgId = cached?.organizationId || null;
    const userId = crypto.randomUUID();

    // Ensure this organization is fully bootstrapped with all modules ready
    ensureTenantBootstrapped(resolvedOrgId);

    const userEmail = isEmailInput ? cleanEmail : (cached?.email || `${last10}@phone.dakshora.app`);
    const userPhone = isEmailInput ? (cached?.phone ? `+91${cached.phone}` : null) : `+91${last10}`;

    // Generate real, cryptographically verifiable Dakshora JWT token
    const tokenPayload = {
      sub: userId,
      id: userId,
      phone: userPhone,
      email: userEmail,
      name: resolvedName,
      role: resolvedRole,
      organizationId: resolvedOrgId,
      isSuperAdmin: resolvedRole === "superadmin",
      app_metadata: {
        role: resolvedRole,
        organization_id: resolvedOrgId,
        provider: isEmailInput ? "email_otp" : (cached?.channel === "whatsapp" ? "whatsapp_otp" : "phone_otp")
      },
      user_metadata: {
        name: resolvedName,
        phone: userPhone,
        email: userEmail,
        role: resolvedRole
      }
    };

    const accessToken = createDakshoraJwt(tokenPayload);

    const userProfile = {
      id: userId,
      phone: userPhone,
      email: userEmail,
      name: resolvedName,
      role: resolvedRole,
      isSuperAdmin: resolvedRole === "superadmin",
      authProvider: isEmailInput ? "email_otp" : (cached?.channel === "whatsapp" ? "whatsapp_otp" : "phone_sms"),
      permissions: resolvedRole === "superadmin" ? ["*"] : ["websites.view", "websites.edit", "leads.view", "leads.manage", "school.manage", "ai.use"],
      organizationId: resolvedOrgId
    };

    recordAuditLog("auth.otp_verified", isEmailInput ? cleanEmail : last10, "user", userId, req);

    res.json({
      success: true,
      message: `${isEmailInput ? `Email ${cleanEmail}` : `Phone number +91 ${last10}`} verified successfully! Welcome to Dakshora 🚀`,
      token: accessToken,
      access_token: accessToken,
      token_type: "Bearer",
      expires_in: 7 * 86400,
      user: userProfile
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "OTP verification failed", error: error.message });
  }
});

