// Create SuperAdmin: POST /api/auth/create-superadmin (Protected: SuperAdmin Only)
app.post("/api/auth/create-superadmin", requireAuth, (req, res, next) => {
  if (!req.user?.isSuperAdmin && req.user?.role !== "superadmin") {
    return res.status(403).json({
      success: false,
      code: "FORBIDDEN",
      message: "Security violation: Only verified Platform SuperAdmins can provision SuperAdmin accounts."
    });
  }
  next();
}, async (req, res) => {
  try {
    if (!supabase) return res.status(500).json({ success: false, message: "Supabase not initialized" });
    const { email, password, name } = req.body;

    const { data, error } = await supabase.auth.admin.createUser({
      email,
      password,
      email_confirm: true,
      user_metadata: { name: name || "Super Admin", role: "superadmin", is_superadmin: true },
      app_metadata: { role: "superadmin", provider: "email" }
    });

    if (error) {
      if (error.message.includes("already registered") || error.code === "email_exists") {
        const { data: listData } = await supabase.auth.admin.listUsers();
        const existingUser = listData?.users?.find(u => u.email === email);
        if (existingUser) {
          await supabase.auth.admin.updateUserById(existingUser.id, {
            password,
            email_confirm: true,
            user_metadata: { name: name || "Super Admin", role: "superadmin", is_superadmin: true },
            app_metadata: { role: "superadmin" }
          });
          recordAuditLog("superadmin.updated", email, "user", existingUser.id, req);
          return res.json({
            success: true,
            message: "Existing user promoted to SuperAdmin & password updated ✅",
            user: { id: existingUser.id, email: existingUser.email, role: "superadmin" }
          });
        }
      }
      throw error;
    }

    recordAuditLog("superadmin.created", email, "user", data.user.id, req);

    res.json({
      success: true,
      message: "SuperAdmin user created successfully in Supabase Auth ✅",
      user: { id: data.user.id, email: data.user.email, role: "superadmin" }
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to create superadmin", error: error.message });
  }
});

// Create Client / School User: POST /api/auth/create-client-user (Protected: SuperAdmin or authorized staff)
app.post("/api/auth/create-client-user", requireAuth, async (req, res) => {
  try {
    if (!req.user?.isSuperAdmin && req.user?.role !== "superadmin") {
      return res.status(403).json({ success: false, code: "FORBIDDEN", message: "Only SuperAdmins can create school client accounts" });
    }
    if (!supabase) return res.status(500).json({ success: false, message: "Supabase not initialized" });
    const { email, password, name, role = "school-admin", organization_name } = req.body;

    if (!email || !password) {
      return res.status(400).json({ success: false, message: "Email and password are required" });
    }

    const orgName = (organization_name || (name ? `${name} School` : "School Client")).trim();
    const orgSlug = orgName.toLowerCase().replace(/[^a-z0-9]/g, "-").replace(/-+/g, "-");
    let clientOrg = IN_MEMORY_ORGANIZATIONS.find(o => o.name.toLowerCase() === orgName.toLowerCase() || o.slug === orgSlug);
    if (!clientOrg) {
      clientOrg = {
        id: crypto.randomUUID(),
        name: orgName,
        slug: orgSlug,
        plan: "growth",
        status: "active",
        created_at: new Date().toISOString()
      };
      IN_MEMORY_ORGANIZATIONS.unshift(clientOrg);
      if (supabase) {
        supabase.from("organizations").insert([clientOrg]).catch(() => {});
      }
    }

    // Auto-bootstrap client organization foundation with all modules
    ensureTenantBootstrapped(clientOrg.id, clientOrg.name, clientOrg.slug, "growth");

    const { data, error } = await supabase.auth.admin.createUser({
      email,
      password,
      email_confirm: true,
      user_metadata: { name: name || "School Principal", role, organization_name: orgName, organization_id: clientOrg.id },
      app_metadata: { role, organization_id: clientOrg.id, provider: "email" }
    });

    if (error) {
      if (error.message.includes("already registered") || error.code === "email_exists") {
        const { data: listData } = await supabase.auth.admin.listUsers();
        const existingUser = listData?.users?.find(u => u.email === email);
        if (existingUser) {
          await supabase.auth.admin.updateUserById(existingUser.id, {
            password,
            email_confirm: true,
            user_metadata: { name: name || "School Principal", role, organization_name: orgName, organization_id: clientOrg.id },
            app_metadata: { role, organization_id: clientOrg.id }
          });
          return res.json({
            success: true,
            message: `Client credentials updated for ${email} ✅`,
            client: { email, password, role, organization_id: clientOrg.id, organization_name: orgName, loginUrl: "/customer-portal" }
          });
        }
      }
      throw error;
    }

    recordAuditLog("client.user_created", email, "user", data.user.id, req);

    res.json({
      success: true,
      message: `School Client Account created for ${name} (${email}) ✅`,
      client: {
        id: data.user.id,
        email,
        name: name || "School Principal",
        role,
        organization_name: organization_name || "School Client",
        loginUrl: "/customer-portal"
      }
    });
  } catch (error) {
    res.status(500).json({ success: false, message: "Failed to create client user", error: error.message });
  }
});

