// Security Helper to locate website and enforce strict tenant ownership
async function findAuthorizedWebsite(id, req, res) {
  let site = IN_MEMORY_WEBSITES.find(s => s.id === id);
  if (!site && supabase) {
    try {
      const { data } = await supabase.from("websites").select("*").eq("id", id).maybeSingle();
      if (data) {
        site = {
          id: data.id,
          name: data.name,
          domain: `${data.slug}.school.dakshora.app`,
          template: "tpl-school-saas",
          status: data.status,
          organization_id: data.organization_id,
          created_at: data.created_at
        };
      }
    } catch (_) {}
  }
  if (!site) {
    res.status(404).json({ success: false, code: "NOT_FOUND", message: `Website '${id}' not found` });
    return null;
  }
  // Check authorization
  const isSuper = req.user?.isSuperAdmin || req.user?.role === "superadmin";
  if (!isSuper) {
    if (!req.user?.organizationId || site.organization_id !== req.user.organizationId) {
      res.status(403).json({
        success: false,
        code: "FORBIDDEN_TENANT_MISMATCH",
        message: "Access Denied: You do not have permission to manage this website."
      });
      return null;
    }
  }
  return site;
}

// Helper to load persisted CMS tree from DB across server restarts
async function loadPersistedCmsTree(site) {
  if (WEBSITE_CMS_TREES.has(site.id)) {
    return WEBSITE_CMS_TREES.get(site.id);
  }
  if (supabase && site.organization_id) {
    try {
      const { data: onb } = await supabase
        .from("school_onboarding")
        .select("draft_data")
        .eq("organization_id", site.organization_id)
        .maybeSingle();

      if (onb?.draft_data?.cms_trees?.[site.id]) {
        const persistedTree = onb.draft_data.cms_trees[site.id];
        WEBSITE_CMS_TREES.set(site.id, persistedTree);
        return persistedTree;
      }
    } catch (_) {}
  }
  return getOrCreateCmsTree(site);
}

// Helper to persist CMS tree to DB across restarts
async function persistCmsTree(site, tree) {
  WEBSITE_CMS_TREES.set(site.id, tree);
  if (supabase && site.organization_id) {
    try {
      const { data: existingOnb } = await supabase
        .from("school_onboarding")
        .select("id, draft_data")
        .eq("organization_id", site.organization_id)
        .maybeSingle();

      const existingDraft = existingOnb?.draft_data || {};
      const updatedDraft = {
        ...existingDraft,
        cms_trees: {
          ...(existingDraft.cms_trees || {}),
          [site.id]: tree
        }
      };

      if (existingOnb?.id) {
        await supabase
          .from("school_onboarding")
          .update({
            draft_data: updatedDraft,
            updated_at: new Date().toISOString()
          })
          .eq("id", existingOnb.id);
      } else {
        await supabase
          .from("school_onboarding")
          .insert([{
            id: crypto.randomUUID(),
            organization_id: site.organization_id,
            status: "draft",
            current_step: 1,
            completed_steps: [],
            draft_data: updatedDraft
          }]);
      }

      // Relational persistence into public.website_settings
      const settingsPayload = {
        website_id: site.id,
        primary_color: tree.branding?.primaryColor || "#1E40AF",
        secondary_color: tree.branding?.secondaryColor || "#0D9488",
        accent_color: tree.branding?.accentColor || "#F59E0B",
        heading_font: tree.template?.fontFamily || "'Plus Jakarta Sans', sans-serif",
        body_font: "'Plus Jakarta Sans', sans-serif",
        phone: tree.schoolInfo?.phone || null,
        email: tree.schoolInfo?.email || null,
        address: tree.schoolInfo?.address || null,
        settings: {
          heroHeadline: tree.content?.heroHeadline,
          heroSubheadline: tree.content?.heroSubheadline,
          principalMessage: tree.content?.principalMessage,
          schoolMotto: tree.content?.schoolMotto,
          ctaText: tree.content?.ctaText
        }
      };
      await supabase.from("website_settings").upsert([settingsPayload], { onConflict: "website_id" }).catch(() => {});

      // Relational persistence for pages
      if (Array.isArray(tree.pages)) {
        for (const p of tree.pages) {
          const pageRow = {
            id: (p.id && !p.id.startsWith("pg-")) ? p.id : crypto.randomUUID(),
            website_id: site.id,
            title: p.title,
            slug: (p.slug || "page").replace(/^\//, "") || "home",
            status: p.visible !== false ? "published" : "draft"
          };
          await supabase.from("pages").upsert([pageRow], { onConflict: "id" }).catch(() => {});
        }
      }
    } catch (err) {
      console.warn("[CMS DB] Failed to persist CMS tree:", err.message);
    }
  }
}

// GET /api/websites/:id/cms (Get full 9-layer CMS tree with DB Persistence)
app.get("/api/websites/:id/cms", requireAuth, async (req, res) => {
  const site = await findAuthorizedWebsite(req.params.id, req, res);
  if (!site) return;
  const tree = await loadPersistedCmsTree(site);
  res.json({ success: true, tree });
});

// PUT /api/websites/:id/cms (Update any of the 9 layers with DB Persistence)
app.put("/api/websites/:id/cms", requireAuth, async (req, res) => {
  const site = await findAuthorizedWebsite(req.params.id, req, res);
  if (!site) return;
  const existing = await loadPersistedCmsTree(site);

  const updated = {
    ...existing,
    ...req.body,
    websiteId: site.id
  };

  await persistCmsTree(site, updated);
  recordAuditLog("cms.tree_updated", req.user?.email || "admin", "website", site.id, req);
  res.json({ success: true, message: "CMS Tree updated successfully ✅", tree: updated });
});

// POST /api/websites/:id/publish (1-Click Publish to Production with DB Persistence)
app.post("/api/websites/:id/publish", requireAuth, async (req, res) => {
  const site = await findAuthorizedWebsite(req.params.id, req, res);
  if (!site) return;
  const tree = await loadPersistedCmsTree(site);

  tree.publishing.status = "live";
  tree.publishing.version = (tree.publishing.version || 1) + 1;
  tree.publishing.lastPublishedAt = new Date().toISOString();

  await persistCmsTree(site, tree);

  if (supabase) {
    try {
      await supabase
        .from("websites")
        .update({
          status: "published",
          updated_at: new Date().toISOString()
        })
        .eq("id", site.id);
    } catch (_) {}
  }

  recordAuditLog("website.publish", req.user?.email || "admin", "website", site.id, req);

  res.json({
    success: true,
    message: `Website published live to https://${tree.domain.subdomain} (v${tree.publishing.version}) 🚀`,
    publishing: tree.publishing
  });
});

// POST /api/websites/cascade-generate
// Pipeline: Template -> Website -> Pages -> Sections -> Components -> Content -> Publish
app.post("/api/websites/cascade-generate", (req, res) => {
  const { templateId = "tpl-cbse-secondary", schoolName = "Delhi Public Heritage School", domain } = req.body;

  const siteId = crypto.randomUUID();
  const siteDomain = domain || `${schoolName.toLowerCase().replace(/[^a-z0-9]/g, "-")}.school.dakshora.app`;

  const newSite = {
    id: siteId,
    name: schoolName,
    domain: siteDomain,
    template: templateId,
    status: "live",
    created_at: new Date().toISOString()
  };

  IN_MEMORY_WEBSITES.unshift(newSite);
  const tree = getOrCreateCmsTree(newSite);

  recordAuditLog("website.cascade_generate", "admin", "website", siteId, req);

  res.json({
    success: true,
    message: "7-Step Cascading CMS Pipeline Executed Successfully ✅",
    pipeline: [
      { step: 1, layer: "Template", status: "applied", details: `Selected [${templateId}] theme blueprint & palette` },
      { step: 2, layer: "Website", status: "provisioned", details: `Instantiated entity: ${schoolName} (${siteDomain})` },
      { step: 3, layer: "Pages", status: "routed", details: `Generated ${tree.pages.length} route nodes (/, /about, /admissions, /labs, /faculty, /contact)` },
      { step: 4, layer: "Sections", status: "rendered", details: `Attached ${tree.sections.length} modular blocks (Hero, Thoughts, Stats, Labs, Vision, Form)` },
      { step: 5, layer: "Components", status: "bound", details: `Wired ${tree.components.length} interactive engines (AdmissionEngine, AiTeacherCopilot)` },
      { step: 6, layer: "Content", status: "populated", details: `Dynamic copy, headlines & Principal Vision quote injected` },
      { step: 7, layer: "Publish", status: "live", details: `Deployed to Edge CDN https://${siteDomain} (v1 Active)` }
    ],
    website: newSite,
    tree
  });
});

