// Synchronize SaaS plans, subscriptions, overrides, and invoices from Supabase
async function syncSaasStateFromSupabase() {
  if (!supabase) return;
  try {
    const [plansRes, subsRes, ovrRes, invRes] = await Promise.all([
      supabase.from("saas_plans").select("*").order("display_order", { ascending: true }),
      supabase.from("saas_subscriptions").select("*"),
      supabase.from("saas_entitlement_overrides").select("*"),
      supabase.from("saas_invoices").select("*").order("created_at", { ascending: false })
    ]);

    if (plansRes.data && plansRes.data.length > 0) {
      SAAS_PLANS.length = 0;
      plansRes.data.forEach(p => {
        SAAS_PLANS.push({
          id: p.id,
          name: p.name,
          code: p.code,
          description: p.description,
          priceINR: Number(p.price_inr),
          price_inr: Number(p.price_inr),
          billingInterval: p.billing_interval,
          billing_interval: p.billing_interval,
          currency: p.currency,
          isActive: p.is_active,
          is_active: p.is_active,
          displayOrder: p.display_order,
          display_order: p.display_order,
          features: Array.isArray(p.features) ? p.features : [],
          modules: Array.isArray(p.modules) ? p.modules : [],
          limits: p.limits || {}
        });
      });
    }

    if (subsRes.data && subsRes.data.length > 0) {
      SAAS_SUBSCRIPTIONS = subsRes.data.map(s => ({
        id: s.id,
        organization_id: s.organization_id,
        plan_id: s.plan_id,
        status: s.status,
        billing_interval: s.billing_interval,
        amountINR: Number(s.amount),
        amount: Number(s.amount),
        currency: s.currency,
        trial_start: s.trial_start,
        trial_end: s.trial_end,
        current_period_start: s.current_period_start,
        current_period_end: s.current_period_end,
        cancel_at_period_end: s.cancel_at_period_end,
        canceled_at: s.canceled_at,
        created_at: s.created_at,
        updated_at: s.updated_at
      }));
    }

    if (ovrRes.data && ovrRes.data.length > 0) {
      SAAS_OVERRIDES = ovrRes.data;
    }

    if (invRes.data && invRes.data.length > 0) {
      SAAS_INVOICES = invRes.data.map(i => ({
        id: i.id,
        organization_id: i.organization_id,
        subscription_id: i.subscription_id,
        invoiceNumber: i.invoice_number,
        plan: i.plan_name,
        planId: i.plan_name?.toLowerCase().includes("platinum") ? "enterprise" : (i.plan_name?.toLowerCase().includes("gold") ? "growth" : "starter"),
        amountINR: Number(i.total_amount),
        subtotalINR: Number(i.subtotal),
        taxGstINR: Number(i.tax_gst),
        currency: i.currency,
        status: i.status,
        billingPeriod: `${i.issue_date || ""} - ${i.due_date || ""}`,
        issueDate: i.issue_date,
        dueDate: i.due_date,
        paidDate: i.paid_date,
        date: i.issue_date,
        receiptUrl: `/api/billing/invoices/${i.id}/receipt`,
        created_at: i.created_at
      }));
    }
  } catch (err) {
    console.warn("[SaaS Sync] Failed to sync from Supabase:", err.message);
  }
}

// Initial sync on startup
syncSaasStateFromSupabase();

// =========================================================================
// CENTRAL ENTITLEMENT SERVICE
// =========================================================================

const EntitlementService = {
  getSubscription(orgId) {
    let sub = SAAS_SUBSCRIPTIONS.find(s => s.organization_id === orgId);
    if (!sub) {
      const isSeed = orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";
      sub = {
        id: "sub-" + (orgId ? orgId.slice(0, 8) : "default"),
        organization_id: orgId || "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e",
        plan_id: isSeed ? "enterprise" : "starter",
        status: isSeed ? "active" : "trial",
        billing_interval: "month",
        amountINR: isSeed ? 8999 : 0,
        currency: "INR",
        trial_start: isSeed ? null : new Date().toISOString(),
        trial_end: isSeed ? null : new Date(Date.now() + 14 * 86400000).toISOString(),
        current_period_start: new Date().toISOString(),
        current_period_end: new Date(Date.now() + 14 * 86400000).toISOString(),
        cancel_at_period_end: false,
        canceled_at: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };
      SAAS_SUBSCRIPTIONS.push(sub);
      if (supabase && orgId) {
        supabase.from("saas_subscriptions").upsert([{
          id: sub.id,
          organization_id: sub.organization_id,
          plan_id: sub.plan_id,
          status: sub.status,
          billing_interval: sub.billing_interval,
          amount: sub.amountINR,
          currency: sub.currency,
          current_period_start: sub.current_period_start,
          current_period_end: sub.current_period_end
        }]).then(({ error }) => {
          if (error) console.warn("[SaaS DB] Upsert subscription warning:", error.message);
        }).catch(err => console.warn("[SaaS DB] Exception:", err.message));
      }
    }
    return sub;
  },

  getPlan(orgId) {
    const sub = this.getSubscription(orgId);
    const plan = SAAS_PLANS.find(p => p.id === sub.plan_id) || SAAS_PLANS[0];
    return { plan, subscription: sub };
  },

  getEntitlements(orgId) {
    const { plan, subscription } = this.getPlan(orgId);
    const overrides = SAAS_OVERRIDES.filter(o => o.organization_id === orgId);

    const effectiveModules = [...plan.modules];
    const effectiveLimits = { ...plan.limits };

    for (const ov of overrides) {
      if (ov.override_type === "feature" || ov.override_type === "boolean" || ov.override_type === "module") {
        const isEnabled = ov.value === true || ov.value === "true" || ov.value === 1 || ov.value === "1";
        if (isEnabled) {
          if (!effectiveModules.includes(ov.feature_key)) {
            effectiveModules.push(ov.feature_key);
          }
        } else {
          const idx = effectiveModules.indexOf(ov.feature_key);
          if (idx !== -1) {
            effectiveModules.splice(idx, 1);
          }
        }
      } else if (ov.override_type === "limit" || ov.override_type === "number" || ov.override_type === "quota") {
        effectiveLimits[ov.feature_key] = ov.value === null || ov.value === "null" ? null : Number(ov.value);
      }
    }

    const isExpired = subscription.status === "expired";
    const isCancelledEnded = subscription.status === "cancelled" && subscription.current_period_end && new Date(subscription.current_period_end) < new Date();

    return {
      organizationId: orgId,
      subscriptionId: subscription.id,
      planId: plan.id,
      planName: plan.name,
      status: subscription.status,
      isRestricted: Boolean(isExpired || isCancelledEnded),
      renewalDate: subscription.current_period_end,
      billingInterval: subscription.billing_interval,
      modules: effectiveModules,
      features: plan.features,
      limits: effectiveLimits,
      overrides: overrides
    };
  },

  hasFeature(orgId, featureOrModule) {
    const entitlements = this.getEntitlements(orgId);
    if (entitlements.status === "expired") return false;
    return entitlements.modules.includes(featureOrModule);
  },

  getLimit(orgId, limitKey) {
    const entitlements = this.getEntitlements(orgId);
    return entitlements.limits[limitKey] !== undefined ? entitlements.limits[limitKey] : null;
  },

  checkLimit(orgId, limitKey, requestedAdditional = 1) {
    const limit = this.getLimit(orgId, limitKey);
    if (limit === null || limit === undefined) {
      return { allowed: true, current: 0, limit: null, remaining: null };
    }

    const current = UsageService.getCurrentUsage(orgId, limitKey);
    const wouldBe = current + requestedAdditional;
    const allowed = wouldBe <= limit;

    const resourceName = limitKey.replace('max_', '').replace('_', ' ');
    return {
      allowed,
      current,
      limit,
      requested: requestedAdditional,
      remaining: Math.max(0, limit - current),
      message: allowed
        ? "Within limit"
        : `Your current plan allows up to ${limit.toLocaleString()} active ${resourceName}. Upgrade your plan or increase your limit to add more.`
    };
  }
};

// =========================================================================
// REAL USAGE CALCULATION SERVICE (TENANT-SCOPED DB COUNTS)
// =========================================================================

const TENANT_USAGE_COUNTS = new Map();

const UsageService = {
  async syncMetricsFromDb(orgId) {
    if (!supabase || !orgId) return;
    try {
      const { count: stdCount } = await supabase
        .from("students")
        .select("id", { count: "exact", head: true })
        .eq("organization_id", orgId)
        .eq("admission_status", "admitted");

      const { count: stfCount } = await supabase
        .from("staff")
        .select("id", { count: "exact", head: true })
        .eq("organization_id", orgId)
        .eq("is_active", true);

      TENANT_USAGE_COUNTS.set(orgId, {
        students: stdCount !== null && stdCount !== undefined ? stdCount : 0,
        staff: stfCount !== null && stfCount !== undefined ? stfCount : 0
      });
    } catch (_) {}
  },

  getStudentUsage(orgId) {
    const cached = TENANT_USAGE_COUNTS.get(orgId);
    if (cached?.students !== undefined && cached.students !== null) {
      return cached.students;
    }
    if (typeof ERP_STUDENTS === "undefined") return 0;
    const isSeed = orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";
    return ERP_STUDENTS.filter(s => (s.organization_id ? s.organization_id === orgId : isSeed) && s.status === 'active').length;
  },

  getStaffUsage(orgId) {
    const cached = TENANT_USAGE_COUNTS.get(orgId);
    if (cached?.staff !== undefined && cached.staff !== null) {
      return cached.staff;
    }
    if (typeof ERP_STAFF === "undefined") return 0;
    const isSeed = orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";
    return ERP_STAFF.filter(s => (s.organization_id ? s.organization_id === orgId : isSeed) && (s.status === 'active' || s.isActive !== false)).length;
  },

  getCampusUsage(orgId) {
    if (typeof ERP_CAMPUSES !== "undefined") {
      const isSeed = orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";
      return ERP_CAMPUSES.filter(c => (c.organization_id ? c.organization_id === orgId : isSeed)).length;
    }
    return 0;
  },

  getAIUsage(orgId) {
    return SAAS_AI_USAGE_LOGS.filter(l => l.organization_id === orgId).length;
  },

  getCommunicationUsage(orgId) {
    if (typeof ERP_COMMUNICATION_MESSAGES !== "undefined") {
      return ERP_COMMUNICATION_MESSAGES.filter(m => m.organization_id === orgId).length;
    }
    return 0;
  },

  getCurrentUsage(orgId, limitKey) {
    switch (limitKey) {
      case 'max_students': return this.getStudentUsage(orgId);
      case 'max_staff': return this.getStaffUsage(orgId);
      case 'max_campuses': return this.getCampusUsage(orgId);
      case 'max_ai_requests': return this.getAIUsage(orgId);
      case 'max_communication_messages': return this.getCommunicationUsage(orgId);
      default: return 0;
    }
  },

  getAllMetrics(orgId) {
    const entitlements = EntitlementService.getEntitlements(orgId);
    const studentsUsed = this.getStudentUsage(orgId);
    const staffUsed = this.getStaffUsage(orgId);
    const campusesUsed = this.getCampusUsage(orgId);
    const aiUsed = this.getAIUsage(orgId);
    const commsUsed = this.getCommunicationUsage(orgId);

    const limits = entitlements.limits;

    return {
      organizationId: orgId,
      planId: entitlements.planId,
      planName: entitlements.planName,
      status: entitlements.status,
      renewalDate: entitlements.renewalDate,
      usage: {
        students: {
          current: studentsUsed,
          limit: limits.max_students,
          percentage: limits.max_students ? Math.min(100, Math.round((studentsUsed / limits.max_students) * 100)) : 0,
          unlimited: limits.max_students === null
        },
        staff: {
          current: staffUsed,
          limit: limits.max_staff,
          percentage: limits.max_staff ? Math.min(100, Math.round((staffUsed / limits.max_staff) * 100)) : 0,
          unlimited: limits.max_staff === null
        },
        campuses: {
          current: campusesUsed,
          limit: limits.max_campuses,
          percentage: limits.max_campuses ? Math.min(100, Math.round((campusesUsed / limits.max_campuses) * 100)) : 0,
          unlimited: limits.max_campuses === null
        },
        aiRequests: {
          current: aiUsed,
          limit: limits.max_ai_requests,
          percentage: limits.max_ai_requests ? Math.min(100, Math.round((aiUsed / limits.max_ai_requests) * 100)) : 0,
          unlimited: limits.max_ai_requests === null
        },
        communications: {
          current: commsUsed,
          limit: limits.max_communication_messages,
          percentage: limits.max_communication_messages ? Math.min(100, Math.round((commsUsed / limits.max_communication_messages) * 100)) : 0,
          unlimited: limits.max_communication_messages === null
        },
        storageGb: {
          current: 1.4,
          limit: limits.max_storage_gb || 25,
          percentage: Math.round((1.4 / (limits.max_storage_gb || 25)) * 100),
          unlimited: false
        }
      }
    };
  }
};

// =========================================================================
// PRODUCTION RAZORPAY PAYMENT & WEBHOOK GATEWAY SERVICE
// =========================================================================

const PaymentService = {
  getRazorpay() {
    const key_id = process.env.RAZORPAY_KEY_ID;
    const key_secret = process.env.RAZORPAY_KEY_SECRET;
    if (!key_id || !key_secret) {
      throw new Error("Razorpay credentials (RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET) are not configured on the server.");
    }
    return new Razorpay({ key_id, key_secret });
  },

  verifySignature(orderId, paymentId, signature) {
    if (!orderId || !paymentId || !signature) return false;
    const secret = process.env.RAZORPAY_KEY_SECRET;
    if (!secret) {
      throw new Error("RAZORPAY_KEY_SECRET is not configured on server.");
    }
    try {
      const expectedSignature = crypto.createHmac("sha256", secret).update(`${orderId}|${paymentId}`).digest("hex");
      const sigBuf = Buffer.from(signature, "utf8");
      const expBuf = Buffer.from(expectedSignature, "utf8");
      if (sigBuf.length !== expBuf.length) return false;
      return crypto.timingSafeEqual(sigBuf, expBuf);
    } catch (err) {
      return false;
    }
  },

  verifyWebhookSignature(payload, signature) {
    if (!signature) return false;
    const secret = process.env.RAZORPAY_WEBHOOK_SECRET;
    if (!secret) {
      throw new Error("RAZORPAY_WEBHOOK_SECRET is not configured on server.");
    }
    try {
      const payloadString = typeof payload === "string" ? payload : JSON.stringify(payload);
      const expectedSignature = crypto.createHmac("sha256", secret).update(payloadString).digest("hex");
      const sigBuf = Buffer.from(signature, "utf8");
      const expBuf = Buffer.from(expectedSignature, "utf8");
      if (sigBuf.length !== expBuf.length) return false;
      return crypto.timingSafeEqual(sigBuf, expBuf);
    } catch (err) {
      return false;
    }
  },

  async handleWebhook(event) {
    const eventId = event?.event_id || event?.id;
    if (!eventId) {
      return { success: false, message: "Missing webhook event ID" };
    }
    const existing = SAAS_WEBHOOK_EVENTS.find(e => e.event_id === eventId);
    if (existing) {
      return { success: true, duplicate: true, message: "Webhook event already processed (idempotent)" };
    }

    const eventRecord = {
      id: `wh-${Date.now()}`,
      provider: "razorpay",
      event_id: eventId,
      event_type: event.event || event.type || "payment.captured",
      payload: event,
      processed: true,
      processed_at: new Date().toISOString()
    };

    SAAS_WEBHOOK_EVENTS.push(eventRecord);

    if (supabase) {
      try {
        await supabase.from("saas_webhook_events").insert([eventRecord]);
      } catch (err) {
        console.warn("[Webhook DB] Failed to persist webhook event in Supabase:", err.message);
      }
    }

    // Process payment event to update subscription and invoice
    const eventType = event.event || event.type;
    if (eventType === "payment.captured" || eventType === "order.paid") {
      const paymentEntity = event.payload?.payment?.entity || {};
      const orderEntity = event.payload?.order?.entity || {};
      const notes = paymentEntity.notes || orderEntity.notes || {};
      const orgId = notes.organization_id;
      const planId = notes.plan_id;
      if (orgId) {
        const sub = EntitlementService.getSubscription(orgId);
        if (planId && SAAS_PLANS.some(p => p.id === planId)) {
          sub.plan_id = planId;
        }
        sub.status = "active";
        sub.updated_at = new Date().toISOString();
        if (supabase) {
          try {
            await supabase.from("saas_subscriptions").upsert([{
              id: sub.id,
              organization_id: sub.organization_id,
              plan_id: sub.plan_id,
              status: sub.status,
              billing_interval: sub.billing_interval || "month",
              amount: sub.amountINR || 3999,
              currency: "INR",
              current_period_start: sub.current_period_start,
              current_period_end: sub.current_period_end,
              cancel_at_period_end: false,
              canceled_at: null,
              updated_at: sub.updated_at
            }]);
          } catch (_) {}
        }
      }
    }

    return { success: true, duplicate: false, message: "Webhook event recorded, verified, and applied" };
  }
};

