// POST /api/erp/students - Enroll new student with validation, uniqueness & audit log
app.post("/api/erp/students", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const std = req.body;

  // Plan Quota Check: Max active students limit enforcement
  const studentQuota = EntitlementService.checkLimit(orgId, "max_students", 1);
  if (!studentQuota.allowed) {
    return res.status(403).json({
      success: false,
      code: "QUOTA_EXCEEDED",
      message: studentQuota.message,
      current: studentQuota.current,
      limit: studentQuota.limit
    });
  }

  if (!std || (!std.name && !std.firstName)) {
    return res.status(400).json({ success: false, message: "Student first name is required" });
  }
  if (!std.grade) {
    return res.status(400).json({ success: false, message: "Grade / Class is required" });
  }

  const firstName = (std.firstName || (std.name ? std.name.split(" ")[0] : "")).trim();
  if (!firstName) {
    return res.status(400).json({ success: false, message: "Student first name is required" });
  }
  const middleName = (std.middleName || "").trim();
  const lastName = (std.lastName || (std.name && std.name.split(" ").length > 1 ? std.name.split(" ").slice(1).join(" ") : "")).trim();
  const fullName = std.name || [firstName, middleName, lastName].filter(Boolean).join(" ");

  // Phase 8: Automatic Database-Backed Student ID / Admission Number Generation
  let admissionNo = (std.admissionNo || std.studentId || "").trim();
  if (!admissionNo) {
    admissionNo = await generateUniqueStudentId(supabase, orgId);
  } else {
    let isDuplicate = false;
    if (supabase) {
      try {
        const { data: dupCheck } = await supabase
          .from("students")
          .select("id")
          .eq("organization_id", orgId)
          .ilike("admission_no", admissionNo)
          .maybeSingle();
        if (dupCheck) isDuplicate = true;
      } catch (_) {}
    }
    if (!isDuplicate) {
      isDuplicate = ERP_STUDENTS.some(s => 
        s.organization_id === orgId && 
        s.admissionNo?.toLowerCase() === admissionNo.toLowerCase()
      );
    }
    if (isDuplicate) {
      return res.status(409).json({ 
        success: false, 
        message: `Admission No '${admissionNo}' already exists in this organization. Admission numbers must be unique.` 
      });
    }
  }

  // Validate PEN uniqueness if provided
  const penNo = (std.penNo || "").trim();
  if (penNo) {
    const existingPen = ERP_STUDENTS.find(s => 
      (s.organization_id === orgId) && 
      s.penNo === penNo
    );
    if (existingPen) {
      return res.status(409).json({
        success: false,
        message: `Permanent Education Number (PEN) '${penNo}' is already registered with student '${existingPen.name}'.`
      });
    }
  }

  const newStd = {
    id: std.id || `std-${Date.now()}`,
    admissionNo,
    penNo: penNo || `2026${Math.floor(1000000 + Math.random() * 9000000)}`,
    rollNo: std.rollNo || `DPS-2026-${Math.floor(100 + Math.random() * 900)}`,
    firstName: firstName || fullName.split(" ")[0] || "Student",
    middleName: middleName,
    lastName: lastName || fullName.split(" ").slice(1).join(" ") || "",
    name: fullName,
    grade: std.grade,
    section: std.section || "A",
    gender: std.gender || "Not specified",
    dob: std.dob || "2012-01-01",
    bloodGroup: std.bloodGroup || "B+",
    avatarUrl: std.avatarUrl || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80",
    admissionDate: std.admissionDate || new Date().toISOString().split("T")[0],
    academicSession: std.academicSession || "2026-27",
    status: std.status || "active",
    phone: std.phone || std.parentPhone || "",
    email: std.email || "",
    address: std.address || "",
    city: std.city || "Gurugram",
    state: std.state || "Haryana",
    pinCode: std.pinCode || "122001",
    parentName: std.parentName || "Parent",
    parentRelation: std.parentRelation || "Father",
    parentPhone: std.parentPhone || "",
    parentAltPhone: std.parentAltPhone || "",
    parentEmail: std.parentEmail || "",
    parentOccupation: std.parentOccupation || "",
    parentAddress: std.parentAddress || std.address || "",
    documents: Array.isArray(std.documents) ? std.documents : [
      { id: `doc-${Date.now()}-1`, name: "Aadhaar Card", type: "aadhaar", verified: true, uploadedAt: new Date().toISOString().split("T")[0] }
    ],
    attendancePercent: std.attendancePercent !== undefined ? Number(std.attendancePercent) : 100,
    duesINR: std.duesINR !== undefined ? Number(std.duesINR) : 0,
    organization_id: orgId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  ERP_STUDENTS.unshift(newStd);
  await recordAuditLog("erp.student_enrolled", req.user?.email || "admin", "student", newStd.id, req);

  // Persist to Supabase PostgreSQL students table
  if (supabase) {
    try {
      const dbGender = (newStd.gender || "").toLowerCase().includes("female")
        ? "female"
        : (newStd.gender || "").toLowerCase().includes("male")
        ? "male"
        : "other";

      const { data: dbStudent, error: dbErr } = await supabase
        .from("students")
        .insert([{
          organization_id: orgId,
          admission_no: newStd.admissionNo,
          pen_no: newStd.penNo,
          first_name: newStd.firstName || "Student",
          middle_name: newStd.middleName || null,
          last_name: newStd.lastName || null,
          gender: dbGender,
          date_of_birth: newStd.dob || "2012-01-01",
          blood_group: newStd.bloodGroup || "B+",
          phone: newStd.phone || null,
          email: newStd.email || null,
          address: newStd.address || null,
          city: newStd.city || null,
          state: newStd.state || null,
          pincode: newStd.pinCode || null,
          admission_date: newStd.admissionDate || new Date().toISOString().split("T")[0],
          admission_status: "admitted"
        }])
        .select()
        .maybeSingle();

      if (dbErr) {
        console.warn("[DB] Student persistence note:", dbErr.message);
      } else if (dbStudent) {
        newStd.db_id = dbStudent.id;
        newStd.id = dbStudent.id;

        // 1. Cascade enrollment with real foreign keys (class_id, section_id, academic_session_id)
        try {
          const classId = await resolveOrCreateClass(orgId, newStd.grade);
          const sectionId = classId ? await resolveOrCreateSection(orgId, classId, newStd.section || "A") : null;
          const sessionId = await resolveOrCreateSession(orgId, newStd.academicSession || "2026-27");

          if (classId && sectionId && sessionId) {
            await supabase
              .from("student_enrollments")
              .upsert([{
                organization_id: orgId,
                student_id: dbStudent.id,
                academic_session_id: sessionId,
                class_id: classId,
                section_id: sectionId,
                roll_no: newStd.rollNo || null,
                joined_on: newStd.admissionDate || new Date().toISOString().split("T")[0]
              }], { onConflict: "student_id, academic_session_id" });
          }
        } catch (enrErr) {
          console.warn("[Student Enrollment DB Cascade Error]:", enrErr.message);
        }

        // 2. Cascade parent record if parent details provided
        if (newStd.parentName || newStd.parentPhone || newStd.parentEmail) {
          try {
            await resolveOrCreateParentDb(orgId, {
              name: newStd.parentName || "Parent",
              phone: newStd.parentPhone || newStd.phone || "",
              email: newStd.parentEmail || "",
              relation: newStd.parentRelation || "Father",
              address: newStd.parentAddress || newStd.address || ""
            }, dbStudent.id);
          } catch (parErr) {
            console.warn("[Student Parent DB Cascade Error]:", parErr.message);
          }
        }

        // 3. Cascade automatic fee demand if active fee structures exist
        try {
          const { data: activeFeeStructures } = await supabase
            .from("fee_structures")
            .select("*")
            .eq("organization_id", orgId);

          if (activeFeeStructures && activeFeeStructures.length > 0) {
            for (const fs of activeFeeStructures) {
              await supabase
                .from("student_fees")
                .insert([{
                  organization_id: orgId,
                  student_id: dbStudent.id,
                  fee_structure_id: fs.id,
                  amount_due: fs.amount,
                  discount: 0,
                  amount_paid: 0,
                  status: "pending",
                  due_date: fs.due_date || new Date(Date.now() + 30 * 86400000).toISOString().split("T")[0]
                }]);
            }
          }
        } catch (feeErr) {
          console.warn("[Student Auto Fee Cascade Error]:", feeErr.message);
        }
      }
    } catch (e) {
      console.warn("[DB] Student insert exception:", e.message);
    }
  }

  res.status(201).json({
    success: true,
    message: `Student '${newStd.name}' registered successfully with Admission No ${newStd.admissionNo}`,
    student: {
      ...newStd,
      studentId: newStd.admissionNo,
      admissionNo: newStd.admissionNo
    }
  });
});

// PATCH /api/erp/students/:id - Update student record (DB Fallback)
app.patch("/api/erp/students/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const updates = req.body || {};

  let idx = ERP_STUDENTS.findIndex(s => 
    s.organization_id === orgId && 
    (s.id === id || s.admissionNo === id)
  );

  if (idx === -1 && supabase) {
    try {
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
      let q = supabase.from("students").select("*").eq("organization_id", orgId);
      if (isUuid) {
        q = q.or(`id.eq.${id},admission_no.eq.${id}`);
      } else {
        q = q.eq("admission_no", id);
      }
      const { data: dbStd } = await q.maybeSingle();
      if (dbStd) {
        const fullName = [dbStd.first_name, dbStd.middle_name, dbStd.last_name].filter(Boolean).join(" ") || dbStd.admission_no;
        const mappedStd = {
          id: dbStd.id,
          admissionNo: dbStd.admission_no || "ADM-001",
          penNo: dbStd.pen_no || "",
          rollNo: dbStd.roll_no || dbStd.admission_no?.slice(-3) || "01",
          firstName: dbStd.first_name || fullName.split(" ")[0],
          middleName: dbStd.middle_name || "",
          lastName: dbStd.last_name || fullName.split(" ").slice(1).join(" "),
          name: fullName,
          grade: dbStd.grade || "Class 10",
          section: dbStd.section || "A",
          gender: dbStd.gender || "Not specified",
          dob: dbStd.date_of_birth || "2012-01-01",
          bloodGroup: dbStd.blood_group || "B+",
          avatarUrl: dbStd.photo_url || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80",
          admissionDate: dbStd.admission_date || "2026-04-01",
          academicSession: "2026-27",
          status: dbStd.admission_status === "admitted" ? "active" : (dbStd.admission_status || "active"),
          phone: dbStd.phone || "",
          email: dbStd.email || "",
          parentName: `${dbStd.last_name ? dbStd.last_name + ' Parent' : 'Guardian'}`,
          parentPhone: dbStd.phone || "",
          duesINR: 0,
          attendancePercent: 94.5,
          organization_id: dbStd.organization_id
        };
        ERP_STUDENTS.unshift(mappedStd);
        idx = 0;
      }
    } catch (_) {}
  }

  if (idx === -1) {
    return res.status(404).json({ success: false, message: `Student '${id}' not found in this organization` });
  }

  // Check unique admissionNo if changed
  if (updates.admissionNo && updates.admissionNo !== ERP_STUDENTS[idx].admissionNo) {
    const dup = ERP_STUDENTS.find(s => 
      s.id !== ERP_STUDENTS[idx].id && 
      s.organization_id === orgId && 
      s.admissionNo?.toLowerCase() === updates.admissionNo.toLowerCase()
    );
    if (dup) {
      return res.status(409).json({
        success: false,
        message: `Admission No '${updates.admissionNo}' is already taken by '${dup.name}'`
      });
    }
  }

  // Check unique penNo if changed
  if (updates.penNo && updates.penNo !== ERP_STUDENTS[idx].penNo) {
    const dupPen = ERP_STUDENTS.find(s => 
      s.id !== ERP_STUDENTS[idx].id && 
      s.organization_id === orgId && 
      s.penNo === updates.penNo
    );
    if (dupPen) {
      return res.status(409).json({
        success: false,
        message: `PEN '${updates.penNo}' is already registered to '${dupPen.name}'`
      });
    }
  }

  const updatedStudent = {
    ...ERP_STUDENTS[idx],
    ...updates,
    updated_at: new Date().toISOString()
  };

  if (updates.firstName || updates.lastName) {
    const first = updates.firstName ?? updatedStudent.firstName;
    const last = updates.lastName ?? updatedStudent.lastName;
    updatedStudent.name = `${first} ${last}`.trim();
  }

  ERP_STUDENTS[idx] = updatedStudent;

  // Persist to Supabase PostgreSQL
  if (supabase) {
    try {
      const dbPayload = {};
      if (updates.firstName) dbPayload.first_name = updates.firstName;
      if (updates.lastName) dbPayload.last_name = updates.lastName;
      if (updates.grade) dbPayload.grade = updates.grade;
      if (updates.section) dbPayload.section = updates.section;
      if (updates.phone) dbPayload.phone = updates.phone;
      if (updates.email) dbPayload.email = updates.email;
      if (updates.status) dbPayload.admission_status = updates.status;
      dbPayload.updated_at = new Date().toISOString();

      await supabase
        .from("students")
        .update(dbPayload)
        .eq("organization_id", orgId)
        .or(`id.eq.${id},admission_no.eq.${id}`);
    } catch (dbErr) {
      console.warn("[DB] Student update note:", dbErr.message);
    }
  }

  await recordAuditLog("erp.student_updated", req.user?.email || "admin", "student", updatedStudent.id, req);

  res.json({
    success: true,
    message: `Student record '${updatedStudent.name}' updated successfully`,
    student: updatedStudent
  });
});

// DELETE /api/erp/students/:id - Soft deactivation or hard delete (DB Fallback)
app.delete("/api/erp/students/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const hard = req.query.hard === "true";

  let idx = ERP_STUDENTS.findIndex(s => 
    s.organization_id === orgId && 
    (s.id === id || s.admissionNo === id)
  );

  if (idx === -1 && supabase) {
    try {
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
      let q = supabase.from("students").select("*").eq("organization_id", orgId);
      if (isUuid) {
        q = q.or(`id.eq.${id},admission_no.eq.${id}`);
      } else {
        q = q.eq("admission_no", id);
      }
      const { data: dbStd } = await q.maybeSingle();
      if (dbStd) {
        const fullName = [dbStd.first_name, dbStd.middle_name, dbStd.last_name].filter(Boolean).join(" ") || dbStd.admission_no;
        const mappedStd = {
          id: dbStd.id,
          admissionNo: dbStd.admission_no || "ADM-001",
          name: fullName,
          grade: dbStd.grade || "Class 10",
          section: dbStd.section || "A",
          status: dbStd.admission_status || "active",
          organization_id: dbStd.organization_id
        };
        ERP_STUDENTS.unshift(mappedStd);
        idx = 0;
      }
    } catch (_) {}
  }

  if (idx === -1) {
    return res.status(404).json({ success: false, message: `Student '${id}' not found` });
  }

  const target = ERP_STUDENTS[idx];
  if (hard) {
    ERP_STUDENTS.splice(idx, 1);
  } else {
    target.status = "inactive";
    target.updated_at = new Date().toISOString();
  }

  // Persist to Supabase PostgreSQL
  if (supabase) {
    try {
      if (hard) {
        await supabase
          .from("students")
          .delete()
          .eq("organization_id", orgId)
          .or(`id.eq.${id},admission_no.eq.${id}`);
      } else {
        await supabase
          .from("students")
          .update({ admission_status: "inactive", updated_at: new Date().toISOString() })
          .eq("organization_id", orgId)
          .or(`id.eq.${id},admission_no.eq.${id}`);
      }
    } catch (dbErr) {
      console.warn("[DB] Student delete note:", dbErr.message);
    }
  }

  await recordAuditLog("erp.student_deactivated", req.user?.email || "admin", "student", target.id, req);

  res.json({
    success: true,
    message: hard ? `Student record permanently deleted` : `Student '${target.name}' marked as inactive`,
    student: target
  });
});

// POST /api/erp/students/:id/transfer-certificate - Generate Transfer Certificate (TC) & record withdrawal in public.student_transfers
app.post("/api/erp/students/:id/transfer-certificate", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const { reason = "Parent Relocation / Withdrawal", toSchool = "", conduct = "Good", remarks = "", transferDate: inputTransferDate } = req.body;

  let student = null;
  if (supabase) {
    try {
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
      let q = supabase.from("students").select("*, student_enrollments(*)").eq("organization_id", orgId);
      if (isUuid) {
        q = q.or(`id.eq.${id},admission_no.eq.${id}`);
      } else {
        q = q.eq("admission_no", id);
      }
      const { data: dbStd } = await q.maybeSingle();
      if (dbStd) student = dbStd;
    } catch (_) {}
  }

  if (!student) {
    const memStd = ERP_STUDENTS.find(s => s.organization_id === orgId && (s.id === id || s.admissionNo === id));
    if (memStd) {
      student = {
        id: memStd.id,
        first_name: memStd.name?.split(" ")[0] || memStd.name,
        last_name: memStd.name?.split(" ").slice(1).join(" ") || "",
        admission_no: memStd.admissionNo || "ADM-001",
        grade: memStd.grade || "Class 10",
        admission_status: memStd.status || "admitted"
      };
    }
  }

  if (!student) {
    return res.status(404).json({ success: false, message: `Student '${id}' not found` });
  }

  let school = null;
  if (supabase) {
    try {
      const { data: dbSchool } = await supabase
        .from("schools")
        .select("*")
        .eq("organization_id", orgId)
        .maybeSingle();
      school = dbSchool;
    } catch (_) {}
  }
  const schoolName = school?.name || "School";
  const schoolCode = school?.school_code || "SCH001";
  const affiliationNo = school?.affiliation_no || "CBSE/AFF/2026";
  const board = school?.board || "CBSE";

  const today = new Date();
  const curYear = today.getFullYear();
  const curMonth = today.getMonth() + 1;
  const fy = curMonth >= 4 ? `${curYear}-${String(curYear + 1).slice(-2)}` : `${curYear - 1}-${String(curYear).slice(-2)}`;

  let tcCount = 0;
  if (supabase) {
    try {
      const { count } = await supabase
        .from("student_transfers")
        .select("id", { count: "exact", head: true })
        .eq("organization_id", orgId);
      if (typeof count === "number") tcCount = count;
    } catch (_) {}
  }
  const tcSerial = String(tcCount + 1).padStart(4, "0");
  const tcNo = `TC/${fy}/${tcSerial}`;
  const transferDate = inputTransferDate || today.toISOString().split("T")[0];

  let dbTransfer = null;
  if (supabase && student.id && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(student.id)) {
    try {
      const { data: insTransfer, error: transErr } = await supabase
        .from("student_transfers")
        .insert([{
          organization_id: orgId,
          student_id: student.id,
          from_grade: student.grade || "Class 10",
          to_grade: req.body.toGrade || student.grade || "Class 10",
          transfer_date: transferDate,
          reason,
          status: "approved",
          transfer_certificate_no: tcNo
        }])
        .select()
        .maybeSingle();
      if (transErr) {
        console.warn("[TC DB Insert Warning]:", transErr.message);
      } else {
        dbTransfer = insTransfer;
      }

      await supabase
        .from("students")
        .update({
          admission_status: "withdrawn",
          updated_at: new Date().toISOString()
        })
        .eq("id", student.id);

      await supabase
        .from("student_enrollments")
        .update({
          left_on: transferDate
        })
        .eq("student_id", student.id)
        .is("left_on", null);
    } catch (e) {
      console.warn("[TC DB update error]:", e.message);
    }
  }

  const memTarget = ERP_STUDENTS.find(s => s.organization_id === orgId && (s.id === student.id || s.admissionNo === student.admission_no));
  if (memTarget) {
    memTarget.status = "withdrawn";
    memTarget.left_on = transferDate;
  }

  const studentFullName = [student.first_name, student.middle_name, student.last_name].filter(Boolean).join(" ") || student.name || "Student";

  const certificatePayload = {
    certificateType: "TRANSFER_CERTIFICATE",
    tcNumber: tcNo,
    schoolInfo: {
      name: schoolName,
      schoolCode,
      affiliationNo,
      board,
      address: school?.address || "",
      city: school?.city || "",
      state: school?.state || ""
    },
    studentInfo: {
      studentId: student.id,
      admissionNo: student.admission_no,
      penNo: student.pen_no || "N/A",
      fullName: studentFullName,
      gender: student.gender || "N/A",
      dateOfBirth: student.date_of_birth || "N/A",
      classLastStudied: student.grade || "Class 10",
      dateOfAdmission: student.admission_date || "N/A",
      transferDate,
      reason,
      toSchool: toSchool || "N/A",
      generalConduct: conduct,
      feeDuesCleared: true,
      remarks: remarks || "Eligible for admission to next class."
    },
    issuedAt: today.toISOString(),
    verificationUrl: `/api/public/verify-certificate/${encodeURIComponent(tcNo)}`,
    status: "ISSUED"
  };

  await recordAuditLog("erp.tc_issued", req.user?.email || "admin", "student_transfer", tcNo, req);

  return res.json({
    success: true,
    message: `Transfer Certificate ${tcNo} issued successfully. Student marked as withdrawn.`,
    tcNo,
    record: dbTransfer,
    certificate: certificatePayload
  });
});

// POST /api/erp/students/:id/bonafide-certificate - Generate Bonafide Certificate
app.post("/api/erp/students/:id/bonafide-certificate", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const { purpose = "Official / Administrative Reference", academicSession = "2026-27" } = req.body;

  let student = null;
  if (supabase) {
    try {
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
      let q = supabase.from("students").select("*").eq("organization_id", orgId);
      if (isUuid) {
        q = q.or(`id.eq.${id},admission_no.eq.${id}`);
      } else {
        q = q.eq("admission_no", id);
      }
      const { data: dbStd } = await q.maybeSingle();
      if (dbStd) student = dbStd;
    } catch (_) {}
  }
  if (!student) {
    const memStd = ERP_STUDENTS.find(s => s.organization_id === orgId && (s.id === id || s.admissionNo === id));
    if (memStd) {
      student = {
        id: memStd.id,
        first_name: memStd.name?.split(" ")[0] || memStd.name,
        last_name: memStd.name?.split(" ").slice(1).join(" ") || "",
        admission_no: memStd.admissionNo || "ADM-001",
        grade: memStd.grade || "Class 10",
        date_of_birth: memStd.dob || "2010-01-01"
      };
    }
  }
  if (!student) {
    return res.status(404).json({ success: false, message: `Student '${id}' not found` });
  }

  let school = null;
  if (supabase) {
    try {
      const { data: dbSchool } = await supabase.from("schools").select("*").eq("organization_id", orgId).maybeSingle();
      school = dbSchool;
    } catch (_) {}
  }

  const today = new Date();
  const curYear = today.getFullYear();
  const curMonth = today.getMonth() + 1;
  const fy = curMonth >= 4 ? `${curYear}-${String(curYear + 1).slice(-2)}` : `${curYear - 1}-${String(curYear).slice(-2)}`;
  const bonafideNo = `BON/${fy}/${Date.now().toString().slice(-4)}`;
  const studentFullName = [student.first_name, student.middle_name, student.last_name].filter(Boolean).join(" ") || student.name || "Student";

  const certificatePayload = {
    certificateType: "BONAFIDE_CERTIFICATE",
    certificateNo: bonafideNo,
    schoolInfo: {
      name: school?.name || "School",
      affiliationNo: school?.affiliation_no || "CBSE/AFF/2026",
      board: school?.board || "CBSE",
      address: school?.address || ""
    },
    studentInfo: {
      studentId: student.id,
      admissionNo: student.admission_no,
      fullName: studentFullName,
      dateOfBirth: student.date_of_birth,
      currentClass: student.grade || "Class 10",
      academicSession,
      purpose
    },
    statement: `This is to certify that ${studentFullName}, Admission No. ${student.admission_no}, is a bonafide student of this institution currently studying in ${student.grade || "Class 10"} for the academic year ${academicSession}. According to school records, his/her character and conduct are satisfactory.`,
    issuedAt: today.toISOString(),
    verificationUrl: `/api/public/verify-certificate/${encodeURIComponent(bonafideNo)}`,
    status: "ISSUED"
  };

  await recordAuditLog("erp.bonafide_issued", req.user?.email || "admin", "bonafide_certificate", bonafideNo, req);

  return res.json({
    success: true,
    message: `Bonafide Certificate ${bonafideNo} issued successfully.`,
    certificateNo: bonafideNo,
    certificate: certificatePayload
  });
});

// POST /api/erp/students/import & POST /api/erp/students/bulk-import - Batch CSV/JSON Import with preview & validation
const handleStudentBulkImport = async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { students = [], dryRun = false } = req.body;

  if (!Array.isArray(students) || students.length === 0) {
    return res.status(400).json({ success: false, message: "No student records provided for import" });
  }

  const validRecords = [];
  const errors = [];
  const seenAdmissionNos = new Set(
    ERP_STUDENTS.filter(s => s.organization_id === orgId).map(s => (s.admissionNo || "").toLowerCase())
  );
  const seenPens = new Set(
    ERP_STUDENTS.filter(s => s.organization_id === orgId).map(s => s.penNo).filter(Boolean)
  );

  students.forEach((row, index) => {
    const rowNum = index + 1;
    const name = (row.name || row.fullName || `${row.firstName || ""} ${row.lastName || ""}`).trim();
    const grade = (row.grade || row.class || "").trim();
    const admNo = (row.admissionNo || row.admNo || `DPS-ADM-2026-IMP-${1000 + index}`).trim();
    const penNo = (row.penNo || row.pen || "").trim();

    if (!name) {
      errors.push({ row: rowNum, error: "Missing required student name", data: row });
      return;
    }
    if (!grade) {
      errors.push({ row: rowNum, error: "Missing required Class/Grade", data: row });
      return;
    }
    if (seenAdmissionNos.has(admNo.toLowerCase())) {
      errors.push({ row: rowNum, error: `Duplicate Admission No '${admNo}'`, data: row });
      return;
    }
    if (penNo && seenPens.has(penNo)) {
      errors.push({ row: rowNum, error: `Duplicate PEN '${penNo}'`, data: row });
      return;
    }

    seenAdmissionNos.add(admNo.toLowerCase());
    if (penNo) seenPens.add(penNo);

    validRecords.push({
      id: `std-imp-${Date.now()}-${index}`,
      admissionNo: admNo,
      penNo: penNo || `2026${Math.floor(1000000 + Math.random() * 9000000)}`,
      rollNo: (row.rollNo || `DPS-2026-IMP-${index + 1}`).trim(),
      firstName: row.firstName || name.split(" ")[0] || "Student",
      lastName: row.lastName || name.split(" ").slice(1).join(" ") || "",
      name,
      grade,
      section: row.section || "A",
      gender: row.gender || "Not specified",
      dob: row.dob || "2012-01-01",
      bloodGroup: row.bloodGroup || "B+",
      parentName: row.parentName || "Parent",
      parentRelation: row.parentRelation || "Father",
      parentPhone: row.parentPhone || row.phone || "+91 98000 00000",
      parentEmail: row.parentEmail || row.email || "",
      address: row.address || "",
      city: row.city || "Gurugram",
      state: row.state || "Haryana",
      pinCode: row.pinCode || "122001",
      status: row.status || "active",
      admissionDate: row.admissionDate || new Date().toISOString().split("T")[0],
      academicSession: row.academicSession || "2026-27",
      attendancePercent: Number(row.attendancePercent) || 100,
      duesINR: Number(row.duesINR) || 0,
      documents: [],
      organization_id: orgId,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    });
  });

  if (dryRun) {
    return res.json({
      success: true,
      dryRun: true,
      totalRows: students.length,
      validCount: validRecords.length,
      invalidCount: errors.length,
      preview: validRecords.slice(0, 10),
      errors
    });
  }

  // Perform actual import with Supabase PostgreSQL batch persistence
  if (supabase && validRecords.length > 0) {
    try {
      const dbBatch = validRecords.map(rec => {
        let mappedGender = null;
        if (rec.gender) {
          const g = String(rec.gender).trim().toLowerCase();
          if (["male", "female", "other", "prefer_not_to_say"].includes(g)) {
            mappedGender = g;
          } else if (g === "m") {
            mappedGender = "male";
          } else if (g === "f") {
            mappedGender = "female";
          } else {
            mappedGender = "prefer_not_to_say";
          }
        }

        let mappedStatus = "admitted";
        if (rec.status || rec.admission_status) {
          const s = String(rec.status || rec.admission_status).trim().toLowerCase();
          if (["inquiry", "applied", "admitted", "rejected", "withdrawn"].includes(s)) {
            mappedStatus = s;
          } else if (s === "active" || s === "enrolled") {
            mappedStatus = "admitted";
          } else if (s === "inactive") {
            mappedStatus = "withdrawn";
          } else if (s === "pending") {
            mappedStatus = "applied";
          }
        }

        return {
          organization_id: rec.organization_id || orgId,
          admission_no: rec.admissionNo,
          pen_no: rec.penNo || null,
          first_name: rec.firstName || (rec.name ? rec.name.split(" ")[0] : "Student"),
          last_name: rec.lastName || (rec.name ? rec.name.split(" ").slice(1).join(" ") : ""),
          gender: mappedGender,
          date_of_birth: rec.dob || "2012-01-01",
          blood_group: rec.bloodGroup || "B+",
          phone: rec.parentPhone || rec.phone || null,
          email: rec.parentEmail || rec.email || null,
          address: rec.address || null,
          city: rec.city || "Gurugram",
          state: rec.state || "Haryana",
          pincode: rec.pinCode || "122001",
          admission_date: rec.admissionDate || new Date().toISOString().split("T")[0],
          admission_status: mappedStatus
        };
      });

      const { data: insertedDbStudents, error: batchErr } = await supabase
        .from("students")
        .insert(dbBatch)
        .select("id, admission_no");

      if (batchErr) {
        console.warn("[Bulk Import DB] Batch insert into public.students warning:", batchErr.message);
      } else if (insertedDbStudents && insertedDbStudents.length > 0) {
        const idMap = new Map();
        insertedDbStudents.forEach(s => idMap.set(s.admission_no, s.id));
        validRecords.forEach(rec => {
          if (idMap.has(rec.admissionNo)) {
            rec.db_id = idMap.get(rec.admissionNo);
          }
        });
      }
    } catch (dbEx) {
      console.warn("[Bulk Import DB] Unexpected exception during database persistence:", dbEx.message);
    }
  }

  // Update in-memory registry & audit log
  validRecords.forEach(rec => ERP_STUDENTS.unshift(rec));
  await recordAuditLog("erp.students_imported", req.user?.email || "admin", "student_batch", `${validRecords.length}_records`, req);

  res.json({
    success: true,
    message: `Successfully imported ${validRecords.length} student records (${errors.length} failed/skipped)`,
    importedCount: validRecords.length,
    failedCount: errors.length,
    errors
  });
};

app.post("/api/erp/students/import", handleStudentBulkImport);
app.post("/api/erp/students/bulk-import", handleStudentBulkImport);

// 2. Staff & Faculty Endpoints (Production SaaS Grade)
// GET /api/erp/staff - Multi-field search, filters, sorting, server-side pagination & live KPI summary
app.get("/api/erp/staff", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId && !req.user?.isSuperAdmin) {
    return res.status(403).json({ success: false, message: "Organization required" });
  }
  const {
    q,
    query,
    search,
    staffType,
    designation,
    department,
    status,
    gender,
    sortBy = "name",
    sortOrder = "asc",
    page = 1,
    limit = 25
  } = req.query;

  // Strict tenant organization isolation & live DB query
  let tenantStaff = [];

  if (supabase && orgId) {
    try {
      const { data: dbStaff, error: dbStaffErr } = await supabase.from("staff").select("*").eq("organization_id", orgId);
      if (dbStaff && dbStaff.length > 0) {
        tenantStaff = dbStaff.map(s => {
          const fullName = [s.first_name, s.last_name].filter(Boolean).join(" ") || s.employee_code || "Faculty";
          return {
            id: s.id,
            empId: s.employee_code || "FAC-01",
            firstName: s.first_name || fullName.split(" ")[0] || "Faculty",
            lastName: s.last_name || "",
            name: fullName,
            email: s.email || "",
            phone: s.phone || "",
            gender: s.gender || "Not specified",
            role: (s.designation || "teacher").toLowerCase().includes("principal") ? "principal" : "teacher",
            staffType: s.employment_type || "Teacher",
            department: s.department || "Academics",
            designation: s.designation || "Faculty",
            joiningDate: s.joining_date || "2026-04-01",
            salaryINR: 50000,
            status: s.is_active ? "active" : "inactive",
            isActive: s.is_active !== false,
            organization_id: s.organization_id
          };
        });
      }
    } catch (e) {
      console.warn("[Staff DB Fetch Error]:", e.message);
    }
  }

  // If DB returned nothing, only seed org b17780e5-3832-4ac6-9aeb-33fd80c5cb0e may use memory seed
  if (tenantStaff.length === 0 && orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e") {
    tenantStaff = ERP_STAFF.filter(s => s.organization_id === orgId);
  }

  // Calculate live KPI summary metrics from database
  const today = new Date().toISOString().split("T")[0];
  const totalStaff = tenantStaff.length;
  const activeStaff = tenantStaff.filter(s => s.status === "active" || s.isActive !== false).length;
  const teacherCount = tenantStaff.filter(s => 
    (s.staffType || "").toLowerCase() === "teacher" || 
    (s.role || "").toLowerCase() === "teacher"
  ).length;
  const nonTeachingCount = totalStaff - teacherCount;
  const onLeaveTodayCount = ERP_STAFF_ATTENDANCE.filter(a => 
    a.organization_id === orgId && 
    a.attendanceDate === today && 
    a.status === "on_leave"
  ).length;

  // Multi-field search
  const searchQuery = (search || query || q || "").trim().toLowerCase();
  let filtered = tenantStaff;
  if (searchQuery) {
    filtered = filtered.filter(s => {
      const name = (s.name || `${s.firstName || ""} ${s.lastName || ""}`).toLowerCase();
      const empId = (s.empId || "").toLowerCase();
      const phone = (s.phone || s.altPhone || "").toLowerCase();
      const email = (s.email || "").toLowerCase();
      const dept = (s.department || "").toLowerCase();
      const desig = (s.designation || "").toLowerCase();
      const spec = (s.subjectSpecialization || "").toLowerCase();
      return (
        name.includes(searchQuery) ||
        empId.includes(searchQuery) ||
        phone.includes(searchQuery) ||
        email.includes(searchQuery) ||
        dept.includes(searchQuery) ||
        desig.includes(searchQuery) ||
        spec.includes(searchQuery)
      );
    });
  }

  // Filters
  if (staffType && staffType !== "all") {
    filtered = filtered.filter(s => (s.staffType || s.role || "").toLowerCase() === staffType.toLowerCase());
  }
  if (designation && designation !== "all") {
    filtered = filtered.filter(s => (s.designation || "").toLowerCase().includes(designation.toLowerCase()));
  }
  if (department && department !== "all") {
    filtered = filtered.filter(s => (s.department || "").toLowerCase() === department.toLowerCase());
  }
  if (gender && gender !== "all") {
    filtered = filtered.filter(s => (s.gender || "").toLowerCase() === gender.toLowerCase());
  }
  if (status && status !== "all") {
    if (status === "active") {
      filtered = filtered.filter(s => s.status === "active" || s.isActive !== false);
    } else if (status === "inactive") {
      filtered = filtered.filter(s => s.status === "inactive" || s.isActive === false);
    } else if (status === "on_leave") {
      filtered = filtered.filter(s => s.status === "on_leave");
    } else {
      filtered = filtered.filter(s => (s.status || "").toLowerCase() === status.toLowerCase());
    }
  }

  // Sorting
  filtered.sort((a, b) => {
    let valA = a[sortBy] ?? "";
    let valB = b[sortBy] ?? "";
    if (typeof valA === "string") valA = valA.toLowerCase();
    if (typeof valB === "string") valB = valB.toLowerCase();
    if (valA < valB) return sortOrder === "asc" ? -1 : 1;
    if (valA > valB) return sortOrder === "asc" ? 1 : -1;
    return 0;
  });

  // Server-side pagination
  const pageNum = Math.max(1, parseInt(page, 10) || 1);
  const pageSize = Math.min(100, Math.max(1, parseInt(limit, 10) || 25));
  const totalMatching = filtered.length;
  const totalPages = Math.ceil(totalMatching / pageSize) || 1;
  const startIndex = (pageNum - 1) * pageSize;
  const paginated = filtered.slice(startIndex, startIndex + pageSize);

  res.json({
    success: true,
    staff: paginated,
    pagination: {
      page: pageNum,
      limit: pageSize,
      total: totalMatching,
      totalPages
    },
    summary: {
      total: totalStaff,
      active: activeStaff,
      teachers: teacherCount,
      nonTeaching: nonTeachingCount,
      onLeaveToday: onLeaveTodayCount
    }
  });
});

// GET /api/erp/staff/export - Export active filtered list as CSV or JSON
app.get("/api/erp/staff/export", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { q, query, search, staffType, designation, department, status, gender, format = "csv" } = req.query;

  let filtered = ERP_STAFF.filter(s => s.organization_id === orgId);

  const searchQuery = (search || query || q || "").trim().toLowerCase();
  if (searchQuery) {
    filtered = filtered.filter(s => {
      const name = (s.name || "").toLowerCase();
      const empId = (s.empId || "").toLowerCase();
      const phone = (s.phone || "").toLowerCase();
      const email = (s.email || "").toLowerCase();
      return name.includes(searchQuery) || empId.includes(searchQuery) || phone.includes(searchQuery) || email.includes(searchQuery);
    });
  }

  if (staffType && staffType !== "all") filtered = filtered.filter(s => (s.staffType || s.role || "").toLowerCase() === staffType.toLowerCase());
  if (designation && designation !== "all") filtered = filtered.filter(s => (s.designation || "").toLowerCase().includes(designation.toLowerCase()));
  if (department && department !== "all") filtered = filtered.filter(s => (s.department || "").toLowerCase() === department.toLowerCase());
  if (gender && gender !== "all") filtered = filtered.filter(s => (s.gender || "").toLowerCase() === gender.toLowerCase());
  if (status && status !== "all") {
    if (status === "active") filtered = filtered.filter(s => s.status === "active" || s.isActive !== false);
    else if (status === "inactive") filtered = filtered.filter(s => s.status === "inactive" || s.isActive === false);
    else filtered = filtered.filter(s => (s.status || "").toLowerCase() === status.toLowerCase());
  }

  if (format === "json") {
    return res.json({ success: true, count: filtered.length, staff: filtered });
  }

  const headers = [
    "Employee Code", "Full Name", "Gender", "Date of Birth", "Designation",
    "Department", "Staff Type", "Employment Type", "Joining Date", "Phone",
    "Email", "Qualification", "Experience (Yrs)", "Specialization", "Salary (INR)", "Status"
  ];
  const rows = filtered.map(s => [
    `"${s.empId || ""}"`,
    `"${s.name || `${s.firstName || ""} ${s.lastName || ""}`.trim()}"`,
    `"${s.gender || "Not specified"}"`,
    `"${s.dob || ""}"`,
    `"${s.designation || ""}"`,
    `"${s.department || ""}"`,
    `"${s.staffType || s.role || "Teacher"}"`,
    `"${s.employmentType || "Full-time"}"`,
    `"${s.joiningDate || ""}"`,
    `"${s.phone || ""}"`,
    `"${s.email || ""}"`,
    `"${(s.qualification || "").replace(/"/g, '""')}"`,
    `"${s.experienceYears || 0}"`,
    `"${(s.subjectSpecialization || "").replace(/"/g, '""')}"`,
    `"${s.salaryINR || 0}"`,
    `"${s.status || "active"}"`
  ]);

  const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\r\n");
  res.header("Content-Type", "text/csv; charset=utf-8");
  res.header("Content-Disposition", `attachment; filename="Dakshora_Staff_${Date.now()}.csv"`);
  res.send(csvContent);
});

// GET /api/erp/staff/:id/profile - 360-degree Staff & Teacher Profile Dossier
app.get("/api/erp/staff/:id/profile", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const staff = ERP_STAFF.find(s => 
    (s.organization_id === orgId) && 
    (s.id === id || s.empId === id)
  );

  if (!staff) {
    return res.status(404).json({ success: false, message: `Staff member '${id}' not found in this organization` });
  }

  // Teacher academic assignments
  const assignments = ERP_TEACHER_ASSIGNMENTS.filter(a => 
    (a.organization_id === orgId) && 
    a.staffId === staff.id
  );

  // Attendance statistics
  const today = new Date().toISOString().split("T")[0];
  const todayAtt = ERP_STAFF_ATTENDANCE.find(a => 
    (a.organization_id === orgId) && 
    a.staffId === staff.id && 
    a.attendanceDate === today
  );
  const statusToday = todayAtt ? todayAtt.status : (staff.status === "on_leave" ? "on_leave" : "present");

  const totalWorkingDays = 22;
  const leaveDays = staff.status === "on_leave" ? 2 : 0;
  const presentDays = totalWorkingDays - leaveDays;
  const monthlyRate = Math.round((presentDays / totalWorkingDays) * 100);

  // Staff audit & activity logs
  const activity = IN_MEMORY_AUDIT_LOGS.filter(l => 
    l.target_id === staff.id || 
    l.target_id === staff.empId ||
    (l.action && l.action.includes("staff") && (l.target_id === staff.id || l.target_id === staff.empId))
  );

  res.json({
    success: true,
    staff,
    assignments,
    attendance: {
      statusToday,
      monthlyRate,
      totalWorkingDays,
      presentDays,
      leaveDays
    },
    documents: staff.documents || [],
    activity
  });
});

