// POST /api/erp/staff - Enroll new staff with validation, duplicate employee code check & audit log
app.post("/api/erp/staff", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const stf = req.body;

  // Plan Quota Check: Max active staff limit enforcement
  const staffQuota = EntitlementService.checkLimit(orgId, "max_staff", 1);
  if (!staffQuota.allowed) {
    return res.status(403).json({
      success: false,
      code: "QUOTA_EXCEEDED",
      message: staffQuota.message,
      current: staffQuota.current,
      limit: staffQuota.limit
    });
  }

  if (!stf || (!stf.name && !stf.firstName)) {
    return res.status(400).json({ success: false, message: "Staff full name is required" });
  }
  if (!stf.designation) {
    return res.status(400).json({ success: false, message: "Designation is required" });
  }

  const empId = (stf.empId || stf.employeeCode || stf.employee_code || "").trim();
  if (!empId) {
    return res.status(400).json({ success: false, message: "Employee Code / ID is required" });
  }

  const phone = (stf.phone || stf.mobile || "").trim();
  if (!phone) {
    return res.status(400).json({ success: false, message: "Registered mobile number is required" });
  }

  const email = (stf.email || "").trim();
  if (!email || !email.includes("@")) {
    return res.status(400).json({ success: false, message: "Valid email address is required" });
  }

  const firstName = (stf.firstName || (stf.name ? stf.name.split(" ")[0] : "Faculty")).trim();
  const lastName = (stf.lastName || (stf.name && stf.name.split(" ").length > 1 ? stf.name.split(" ").slice(1).join(" ") : "")).trim();
  const fullName = stf.name || [firstName, lastName].filter(Boolean).join(" ");

  // Validate Employee Code and uniqueness within tenant in DB & memory
  let isDuplicateEmp = false;
  if (supabase) {
    try {
      const { data: dbDup } = await supabase
        .from("staff")
        .select("id")
        .eq("organization_id", orgId)
        .ilike("employee_code", empId)
        .maybeSingle();
      if (dbDup) isDuplicateEmp = true;
    } catch (_) {}
  }
  if (!isDuplicateEmp) {
    isDuplicateEmp = ERP_STAFF.some(s => 
      s.organization_id === orgId && 
      s.empId?.toLowerCase() === empId.toLowerCase()
    );
  }
  if (isDuplicateEmp) {
    return res.status(409).json({ 
      success: false, 
      message: `Employee Code '${empId}' is already registered in this school. Employee codes must be unique.` 
    });
  }

  const newStaff = {
    id: stf.id || `stf-${Date.now()}`,
    empId,
    firstName: firstName || fullName.split(" ")[0] || "Faculty",
    lastName: lastName || fullName.split(" ").slice(1).join(" ") || "",
    name: fullName,
    gender: stf.gender || "Not specified",
    dob: stf.dob || "1985-01-01",
    bloodGroup: stf.bloodGroup || "B+",
    photoUrl: stf.photoUrl || "https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=150&auto=format&fit=crop&q=80",
    role: stf.role || (stf.staffType ? stf.staffType.toLowerCase() : "teacher"),
    staffType: stf.staffType || "Teacher",
    designation: stf.designation,
    department: stf.department || "Academics",
    employmentType: stf.employmentType || "Full-time",
    qualification: stf.qualification || "Postgraduate",
    experienceYears: stf.experienceYears !== undefined ? Number(stf.experienceYears) : 5,
    subjectSpecialization: stf.subjectSpecialization || "",
    email: stf.email || `staff.${Date.now()}@dpsheritage.edu.in`,
    phone: stf.phone || "+91 98000 00000",
    altPhone: stf.altPhone || "",
    address: stf.address || "Campus Residence",
    city: stf.city || "Gurugram",
    state: stf.state || "Haryana",
    pinCode: stf.pinCode || "122001",
    salaryINR: stf.salaryINR !== undefined ? Number(stf.salaryINR) : 50000,
    joiningDate: stf.joiningDate || new Date().toISOString().split("T")[0],
    status: stf.status || "active",
    isActive: stf.isActive !== false,
    documents: Array.isArray(stf.documents) ? stf.documents : [],
    organization_id: orgId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  ERP_STAFF.unshift(newStaff);
  await recordAuditLog("erp.staff_enrolled", req.user?.email || "admin", "staff", newStaff.id, req);

  // Persist to Supabase PostgreSQL staff table
  if (supabase) {
    try {
      const dbGender = (newStaff.gender || "").toLowerCase().includes("female")
        ? "female"
        : (newStaff.gender || "").toLowerCase().includes("male")
        ? "male"
        : "other";

      const { data: dbStaff, error: dbErr } = await supabase
        .from("staff")
        .insert([{
          organization_id: orgId,
          employee_code: newStaff.empId,
          first_name: newStaff.firstName || "Faculty",
          last_name: newStaff.lastName || null,
          gender: dbGender,
          phone: newStaff.phone || null,
          email: newStaff.email || null,
          designation: newStaff.designation || "Teacher",
          department: newStaff.department || "Academics",
          joining_date: newStaff.joiningDate || new Date().toISOString().split("T")[0],
          is_active: newStaff.isActive !== false
        }])
        .select()
        .maybeSingle();

      if (dbErr) {
        console.warn("[DB] Staff persistence note:", dbErr.message);
      } else if (dbStaff) {
        newStaff.db_id = dbStaff.id;
      }
    } catch (e) {
      console.warn("[DB] Staff insert exception:", e.message);
    }
  }

  res.status(201).json({
    success: true,
    message: `Faculty member '${newStaff.name}' enrolled successfully with Employee Code ${newStaff.empId}`,
    staff: newStaff
  });
});

// PATCH /api/erp/staff/:id - Update staff member
app.patch("/api/erp/staff/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const updates = req.body || {};

  let idx = ERP_STAFF.findIndex(s => 
    s.organization_id === orgId && 
    (s.id === id || s.empId === id)
  );

  let targetStaff = idx !== -1 ? ERP_STAFF[idx] : null;
  if (!targetStaff && supabase && orgId) {
    try {
      const { data: dbS } = await supabase.from("staff").select("*").eq("organization_id", orgId).or(`id.eq.${id},employee_code.eq.${id}`).maybeSingle();
      if (dbS) {
        targetStaff = {
          id: dbS.id,
          empId: dbS.employee_code,
          name: [dbS.first_name, dbS.last_name].filter(Boolean).join(" "),
          firstName: dbS.first_name,
          lastName: dbS.last_name,
          designation: dbS.designation,
          department: dbS.department,
          phone: dbS.phone,
          email: dbS.email,
          status: dbS.is_active ? "active" : "inactive",
          organization_id: orgId
        };
      }
    } catch (_) {}
  }

  if (!targetStaff) {
    return res.status(404).json({ success: false, message: `Staff member '${id}' not found in this organization` });
  }

  // Check unique empId if changed
  if (updates.empId && updates.empId !== targetStaff.empId) {
    const dup = ERP_STAFF.find(s => 
      s.id !== targetStaff.id && 
      s.organization_id === orgId && 
      s.empId?.toLowerCase() === updates.empId.toLowerCase()
    );
    if (dup) {
      return res.status(409).json({
        success: false,
        message: `Employee Code '${updates.empId}' is already in use by '${dup.name}'`
      });
    }
  }

  const updatedStaff = {
    ...targetStaff,
    ...updates,
    updated_at: new Date().toISOString()
  };

  if (updates.firstName || updates.lastName) {
    const first = updates.firstName ?? updatedStaff.firstName;
    const last = updates.lastName ?? updatedStaff.lastName;
    updatedStaff.name = `${first} ${last}`.trim();
  }

  if (idx !== -1) {
    ERP_STAFF[idx] = updatedStaff;
  } else {
    ERP_STAFF.push(updatedStaff);
  }

  // Persist to Supabase PostgreSQL staff table
  if (supabase) {
    try {
      await supabase
        .from("staff")
        .update({
          first_name: updates.firstName,
          last_name: updates.lastName,
          designation: updates.designation,
          department: updates.department,
          phone: updates.phone,
          email: updates.email,
          updated_at: new Date().toISOString()
        })
        .eq("organization_id", orgId)
        .or(`id.eq.${id},employee_code.eq.${id}`);
    } catch (_) {}
  }

  await recordAuditLog("erp.staff_updated", req.user?.email || "admin", "staff", updatedStaff.id, req);

  res.json({
    success: true,
    message: `Staff record '${updatedStaff.name}' updated successfully`,
    staff: updatedStaff
  });
});

// POST /api/erp/staff/:id/deactivate - Soft deactivate preserving historical records
app.post("/api/erp/staff/:id/deactivate", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;

  const idx = ERP_STAFF.findIndex(s => 
    s.organization_id === orgId && 
    (s.id === id || s.empId === id)
  );

  if (idx === -1) {
    return res.status(404).json({ success: false, message: `Staff member '${id}' not found` });
  }

  const target = ERP_STAFF[idx];
  target.status = "inactive";
  target.isActive = false;
  target.updated_at = new Date().toISOString();

  if (supabase) {
    try {
      await supabase
        .from("staff")
        .update({ is_active: false, updated_at: new Date().toISOString() })
        .eq("organization_id", orgId)
        .or(`id.eq.${id},employee_code.eq.${id}`);
    } catch (_) {}
  }

  await recordAuditLog("erp.staff_deactivated", req.user?.email || "admin", "staff", target.id, req);

  res.json({
    success: true,
    message: `Staff member '${target.name}' has been deactivated. Historical records, assignments, and payroll preserved.`,
    staff: target
  });
});

// DELETE /api/erp/staff/:id - Soft deactivation by default or hard delete
app.delete("/api/erp/staff/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }
  const { id } = req.params;
  const hard = req.query.hard === "true";

  let idx = ERP_STAFF.findIndex(s => 
    s.organization_id === orgId && 
    (s.id === id || s.empId === id)
  );

  let target = idx !== -1 ? ERP_STAFF[idx] : null;
  if (!target && supabase && orgId) {
    try {
      const { data: dbS } = await supabase.from("staff").select("*").eq("organization_id", orgId).or(`id.eq.${id},employee_code.eq.${id}`).maybeSingle();
      if (dbS) {
        target = {
          id: dbS.id,
          empId: dbS.employee_code,
          name: [dbS.first_name, dbS.last_name].filter(Boolean).join(" "),
          organization_id: orgId
        };
      }
    } catch (_) {}
  }

  if (!target) {
    return res.status(404).json({ success: false, message: `Staff member '${id}' not found` });
  }
  if (hard) {
    ERP_STAFF.splice(idx, 1);
  } else {
    target.status = "inactive";
    target.isActive = false;
    target.updated_at = new Date().toISOString();
  }

  if (supabase) {
    try {
      if (hard) {
        await supabase
          .from("staff")
          .delete()
          .eq("organization_id", orgId)
          .or(`id.eq.${id},employee_code.eq.${id}`);
      } else {
        await supabase
          .from("staff")
          .update({ is_active: false, updated_at: new Date().toISOString() })
          .eq("organization_id", orgId)
          .or(`id.eq.${id},employee_code.eq.${id}`);
      }
    } catch (_) {}
  }

  await recordAuditLog("erp.staff_deactivated", req.user?.email || "admin", "staff", target.id, req);

  res.json({
    success: true,
    message: hard ? `Staff member permanently deleted` : `Staff member '${target.name}' marked as inactive`,
    staff: target
  });
});

// POST /api/erp/staff/import & POST /api/erp/staff/bulk-import - Batch CSV/JSON import with validation preview & PostgreSQL persistence
app.post(["/api/erp/staff/import", "/api/erp/staff/bulk-import"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) {
    return res.status(403).json({ success: false, code: "ORGANIZATION_REQUIRED", message: "Organization required" });
  }

  let { staff = [], csvData = "", csv = "", dryRun = false } = req.body || {};

  // Support CSV string parsing
  const rawCsv = csvData || csv;
  if (typeof rawCsv === "string" && rawCsv.trim().length > 0) {
    const lines = rawCsv.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (lines.length > 1) {
      const headerLine = lines[0].split(",").map(h => h.replace(/^["']|["']$/g, "").trim().toLowerCase());
      const parsedStaff = [];
      for (let i = 1; i < lines.length; i++) {
        const cols = lines[i].split(",").map(c => c.replace(/^["']|["']$/g, "").trim());
        const rowObj = {};
        headerLine.forEach((h, hIdx) => {
          rowObj[h] = cols[hIdx] || "";
        });
        parsedStaff.push(rowObj);
      }
      staff = parsedStaff;
    }
  }

  if (!Array.isArray(staff) || staff.length === 0) {
    return res.status(400).json({ success: false, message: "No staff records provided for import" });
  }

  const validRecords = [];
  const errors = [];
  const seenEmpIds = new Set();

  // Load existing employee codes from PostgreSQL to enforce scope uniqueness
  const existingDbEmpCodes = new Set();
  if (supabase) {
    try {
      const { data: dbStaff } = await supabase
        .from("staff")
        .select("employee_code")
        .eq("organization_id", orgId);
      if (dbStaff) {
        dbStaff.forEach(s => {
          if (s.employee_code) existingDbEmpCodes.add(s.employee_code.toLowerCase());
        });
      }
    } catch (_) {}
  }
  ERP_STAFF.filter(s => s.organization_id === orgId).forEach(s => {
    if (s.empId) existingDbEmpCodes.add(s.empId.toLowerCase());
  });

  staff.forEach((row, index) => {
    const rowNum = index + 1;
    // Flexible column mapping
    const name = (row.name || row.fullName || row["full name"] || row["faculty name"] || `${row.firstName || row.first_name || ""} ${row.lastName || row.last_name || ""}`).trim();
    const designation = (row.designation || row.Designation || row.role || row.Role || row.post || "").trim();
    const empId = (row.empId || row.employeeCode || row.employee_code || row["employee code"] || row["employee id"] || row.emp_id || "").trim();
    const phone = (row.phone || row.mobile || row["mobile number"] || row["phone number"] || "").trim().replace(/[^\d+]/g, "");
    const email = (row.email || row.emailAddress || row["email address"] || "").trim().toLowerCase();
    const department = (row.department || row.Department || "Academics").trim();
    const employmentType = (row.employmentType || row.employment_type || row["employment type"] || "Full-time").trim();
    const gender = (row.gender || row.Gender || "Not specified").trim();

    if (!name) {
      errors.push({ row: rowNum, error: "Missing required faculty full name", field: "name", data: row });
      return;
    }
    if (!designation) {
      errors.push({ row: rowNum, error: "Missing required designation", field: "designation", data: row });
      return;
    }
    if (!empId) {
      errors.push({ row: rowNum, error: "Missing required Employee Code / ID", field: "empId", data: row });
      return;
    }
    if (!phone || phone.replace(/\D/g, "").length < 10) {
      errors.push({ row: rowNum, error: `Invalid or missing mobile number '${phone}'`, field: "phone", data: row });
      return;
    }
    if (!email || !email.includes("@")) {
      errors.push({ row: rowNum, error: `Invalid or missing email address '${email}'`, field: "email", data: row });
      return;
    }

    if (seenEmpIds.has(empId.toLowerCase())) {
      errors.push({ row: rowNum, error: `Duplicate Employee Code '${empId}' within upload batch`, field: "empId", isDuplicate: true, data: row });
      return;
    }
    if (existingDbEmpCodes.has(empId.toLowerCase())) {
      errors.push({ row: rowNum, error: `Employee Code '${empId}' already exists in this school`, field: "empId", isDuplicate: true, data: row });
      return;
    }

    seenEmpIds.add(empId.toLowerCase());

    const mappedGender = gender.toLowerCase().includes("female") ? "female" : gender.toLowerCase().includes("male") ? "male" : "other";

    validRecords.push({
      id: crypto.randomUUID ? crypto.randomUUID() : `stf-imp-${Date.now()}-${index}`,
      empId,
      employee_code: empId,
      firstName: name.split(" ")[0] || "Faculty",
      lastName: name.split(" ").slice(1).join(" ") || "",
      name,
      gender: mappedGender,
      dob: row.dob || row.date_of_birth || "1988-01-01",
      designation,
      department,
      employmentType,
      email,
      phone,
      salaryINR: Number(row.salaryINR || row.salary) || 50000,
      joiningDate: row.joiningDate || row.joining_date || new Date().toISOString().split("T")[0],
      status: "active",
      isActive: true,
      organization_id: orgId,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    });
  });

  if (dryRun) {
    return res.json({
      success: true,
      dryRun: true,
      totalRows: staff.length,
      validCount: validRecords.length,
      invalidCount: errors.length,
      preview: validRecords.slice(0, 10),
      errors
    });
  }

  // Persist to PostgreSQL public.staff table
  let dbInsertedCount = 0;
  if (supabase && validRecords.length > 0) {
    try {
      const dbBatch = validRecords.map(rec => ({
        id: rec.id,
        organization_id: orgId,
        employee_code: rec.empId,
        first_name: rec.firstName,
        last_name: rec.lastName || null,
        gender: rec.gender,
        phone: rec.phone,
        email: rec.email,
        designation: rec.designation,
        department: rec.department,
        employment_type: rec.employmentType,
        joining_date: rec.joiningDate,
        is_active: true
      }));

      const { data: insertedDbStaff, error: insertErr } = await supabase
        .from("staff")
        .insert(dbBatch)
        .select("id, employee_code");

      if (!insertErr && insertedDbStaff) {
        dbInsertedCount = insertedDbStaff.length;
      } else if (insertErr) {
        console.warn("[Staff Bulk DB] Insert note:", insertErr.message);
      }
    } catch (dbEx) {
      console.warn("[Staff Bulk DB] Unexpected error:", dbEx.message);
    }
  }

  // Update in-memory registry & audit log
  validRecords.forEach(rec => ERP_STAFF.unshift(rec));
  await recordAuditLog("erp.staff_imported", req.user?.email || "admin", "staff_batch", `${validRecords.length}_records`, req);

  res.json({
    success: true,
    message: `Successfully imported ${validRecords.length} staff members into school database (${errors.length} failed/skipped)`,
    totalRows: staff.length,
    importedCount: validRecords.length,
    failedCount: errors.length,
    skippedCount: errors.filter(e => e.isDuplicate).length,
    errors
  });
});

