// 3a. GET /api/erp/attendance/dashboard - Live Student & Staff KPI Counts & Class Breakdown
app.get("/api/erp/attendance/dashboard", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const date = (req.query.date || new Date().toISOString().split("T")[0]).trim();

  // 1. Students in this org
  const orgStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);
  const totalStudents = orgStudents.length;

  const todayStudentAtt = ERP_ATTENDANCE.filter(a =>
    (a.organization_id === orgId) &&
    (a.attendanceDate === date || a.date === date)
  );

  const presentStudents = todayStudentAtt.filter(a => a.status === "present").length;
  const absentStudents = todayStudentAtt.filter(a => a.status === "absent").length;
  const lateStudents = todayStudentAtt.filter(a => a.status === "late").length;
  const halfDayStudents = todayStudentAtt.filter(a => a.status === "half_day").length;
  const leaveStudents = todayStudentAtt.filter(a => a.status === "leave").length;

  const studentRate = totalStudents > 0 ? Number(((presentStudents + lateStudents) / totalStudents * 100).toFixed(1)) : 100.0;

  // 2. Staff in this org
  const orgStaff = ERP_STAFF.filter(s => s.organization_id === orgId);
  const totalStaff = orgStaff.length;

  const todayStaffAtt = ERP_STAFF_ATTENDANCE.filter(a =>
    (a.organization_id === orgId) &&
    a.attendanceDate === date
  );

  const presentStaff = todayStaffAtt.filter(a => a.status === "present").length;
  const absentStaff = todayStaffAtt.filter(a => a.status === "absent").length;
  const lateStaff = todayStaffAtt.filter(a => a.status === "late").length;
  const onLeaveStaff = todayStaffAtt.filter(a => a.status === "on_leave" || a.status === "leave").length;
  const staffRate = totalStaff > 0 ? Number(((presentStaff + lateStaff) / totalStaff * 100).toFixed(1)) : 100.0;

  // 3. Class breakdown
  const classMap = {};
  orgStudents.forEach(s => {
    const key = `${s.grade}|||${s.section || 'A'}`;
    if (!classMap[key]) {
      classMap[key] = { grade: s.grade, section: s.section || 'A', total: 0, present: 0, absent: 0, late: 0, halfDay: 0, leave: 0 };
    }
    classMap[key].total++;
  });

  todayStudentAtt.forEach(a => {
    const key = `${a.grade}|||${a.section || 'A'}`;
    if (classMap[key]) {
      if (a.status === "present") classMap[key].present++;
      else if (a.status === "absent") classMap[key].absent++;
      else if (a.status === "late") classMap[key].late++;
      else if (a.status === "half_day") classMap[key].halfDay++;
      else if (a.status === "leave") classMap[key].leave++;
    }
  });

  const classStats = Object.values(classMap).map(c => ({
    ...c,
    attendancePercent: c.total > 0 ? Number(((c.present + c.late) / c.total * 100).toFixed(1)) : 100.0
  }));

  res.json({
    success: true,
    date,
    students: {
      total: totalStudents,
      present: presentStudents,
      absent: absentStudents,
      late: lateStudents,
      halfDay: halfDayStudents,
      leave: leaveStudents,
      attendancePercent: studentRate
    },
    staff: {
      total: totalStaff,
      present: presentStaff,
      absent: absentStaff,
      late: lateStaff,
      onLeave: onLeaveStaff,
      attendancePercent: staffRate
    },
    classStats
  });
});

// 3b. GET /api/erp/attendance/student - Section Roll-Call Register (PostgreSQL Backed)
app.get("/api/erp/attendance/student", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { date = new Date().toISOString().split("T")[0], grade = "Class 10", section = "A", session = "2026-27" } = req.query;

  let matchingStudents = ERP_STUDENTS.filter(s =>
    (s.organization_id === orgId) &&
    s.grade && s.grade.toLowerCase() === grade.toLowerCase() &&
    (s.section || "A").toLowerCase() === section.toLowerCase() &&
    s.status !== "inactive" && s.status !== "withdrawn"
  );

  const attMap = new Map();

  if (supabase && orgId) {
    try {
      const { data: dbStds } = await supabase
        .from("students")
        .select("*")
        .eq("organization_id", orgId);
      
      if (dbStds && dbStds.length > 0) {
        matchingStudents = dbStds.map(s => {
          const fullName = [s.first_name, s.middle_name, s.last_name].filter(Boolean).join(" ") || s.admission_no;
          return {
            id: s.id,
            admissionNo: s.admission_no,
            rollNo: s.pen_no || s.admission_no,
            name: fullName,
            grade: s.grade || grade,
            section: s.section || section,
            organization_id: s.organization_id
          };
        });
      }

      const { data: dbAtt } = await supabase
        .from("student_attendance")
        .select("*")
        .eq("organization_id", orgId)
        .eq("attendance_date", date);

      if (dbAtt && dbAtt.length > 0) {
        dbAtt.forEach(a => {
          attMap.set(a.student_id, {
            id: a.id,
            status: a.status,
            remarks: a.remarks || "",
            marked_by: a.marked_by,
            attendanceDate: a.attendance_date,
            date: a.attendance_date
          });
        });
      }
    } catch (e) {
      console.warn("[Attendance DB Read Error]:", e.message);
    }
  }

  const existingAtt = ERP_ATTENDANCE.filter(a =>
    (a.organization_id === orgId) &&
    (a.attendanceDate === date || a.date === date) &&
    a.grade && a.grade.toLowerCase() === grade.toLowerCase() &&
    (a.section || "A").toLowerCase() === section.toLowerCase()
  );

  existingAtt.forEach(a => {
    if (!attMap.has(a.studentId || a.student_id)) {
      attMap.set(a.studentId || a.student_id, a);
    }
  });

  const isAlreadyMarked = attMap.size > 0;
  const firstAtt = Array.from(attMap.values())[0];
  const markedBy = firstAtt?.marked_by || null;
  const markedAt = firstAtt?.updated_at || firstAtt?.created_at || null;

  const records = matchingStudents.map(std => {
    const existing = attMap.get(std.id);
    return {
      id: existing?.id || null,
      studentId: std.id,
      admissionNo: std.admissionNo,
      rollNo: std.rollNo,
      studentName: std.name,
      grade: std.grade,
      section: std.section,
      date,
      status: existing ? existing.status : ERP_ATTENDANCE_SETTINGS.defaultStatus || "present",
      remarks: existing ? existing.remarks || "" : "",
      marked_by: existing ? existing.marked_by : null
    };
  });

  res.json({
    success: true,
    date,
    grade,
    section,
    session,
    isAlreadyMarked,
    markedBy,
    markedAt,
    totalStudents: matchingStudents.length,
    students: records
  });
});

// 3c. POST /api/erp/attendance/student/bulk - High-Speed Bulk Attendance Submission with PostgreSQL Persistence
app.post("/api/erp/attendance/student/bulk", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { date, grade, section, session = "2026-27", records } = req.body || {};

  if (!date || !grade || !section) {
    return res.status(400).json({ success: false, message: "Date, Grade/Class, and Section are required" });
  }
  if (!Array.isArray(records) || records.length === 0) {
    return res.status(400).json({ success: false, message: "Records array must not be empty" });
  }

  // Future date check
  const today = new Date().toISOString().split("T")[0];
  if (!ERP_ATTENDANCE_SETTINGS.allowFutureDates && date > today) {
    return res.status(400).json({
      success: false,
      code: "FUTURE_DATE_DISALLOWED",
      message: `Attendance marking for future date (${date}) is not permitted.`
    });
  }

  // Teacher assignment authorization verification
  const callerRole = (req.user?.role || "").toLowerCase();
  const callerStaffId = req.user?.staffId || req.body.staffId;

  if (callerRole === "teacher" && callerStaffId) {
    const isAssigned = ERP_TEACHER_ASSIGNMENTS.some(a =>
      (a.organization_id === orgId) &&
      a.staffId === callerStaffId &&
      a.grade.toLowerCase() === grade.toLowerCase() &&
      a.section.toLowerCase() === section.toLowerCase()
    );
    if (!isAssigned) {
      return res.status(403).json({
        success: false,
        code: "FORBIDDEN_TEACHER_UNASSIGNED",
        message: `Unauthorized: You are not assigned to mark attendance for ${grade} Section ${section}.`
      });
    }
  }

  const markedBy = req.user?.name || req.user?.email || (callerRole === "teacher" ? "Teacher" : "Admin");
  let createdCount = 0;
  let updatedCount = 0;

  for (const item of records) {
    const studentId = item.studentId || item.student_id;
    if (!studentId) continue;

    const std = ERP_STUDENTS.find(s => s.id === studentId);
    const studentName = item.studentName || std?.name || "Student";
    const status = item.status || "present";
    const remarks = item.remarks || "";

    const existingIdx = ERP_ATTENDANCE.findIndex(a =>
      (a.organization_id === orgId) &&
      (a.studentId === studentId || a.student_id === studentId) &&
      (a.attendanceDate === date || a.date === date)
    );

    if (existingIdx !== -1) {
      const existing = ERP_ATTENDANCE[existingIdx];
      if (existing.status !== status) {
        await recordAuditLog(
          "erp.attendance_corrected",
          req.user?.email || markedBy,
          "student_attendance",
          existing.id,
          req
        );
      }
      existing.status = status;
      existing.remarks = remarks;
      existing.marked_by = markedBy;
      existing.updated_at = new Date().toISOString();
      updatedCount++;
    } else {
      const newRecord = {
        id: item.id || `att-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
        studentId,
        student_id: studentId,
        admissionNo: item.admissionNo || std?.admissionNo || "",
        rollNo: item.rollNo || std?.rollNo || "",
        studentName,
        grade,
        section,
        academicSession: session,
        attendanceDate: date,
        date,
        status,
        remarks,
        marked_by: markedBy,
        organization_id: orgId,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      };
      ERP_ATTENDANCE.push(newRecord);
      createdCount++;
    }
  }

  // DB Persistence to public.student_attendance
  if (supabase && orgId) {
    try {
      const sessId = await resolveOrCreateAcademicSession(orgId, session);
      const { data: dbStds } = await supabase.from("students").select("id, admission_no").eq("organization_id", orgId);
      const stdMap = new Map();
      (dbStds || []).forEach(s => {
        stdMap.set(s.id, s.id);
        if (s.admission_no) stdMap.set(s.admission_no.toLowerCase(), s.id);
      });

      const dbRows = [];
      for (const item of records) {
        const studentId = item.studentId || item.student_id;
        const matchedStd = ERP_STUDENTS.find(s => (s.organization_id === orgId) && (s.id === studentId || s.db_id === studentId));
        const effectiveAdmNo = item.admissionNo || matchedStd?.admissionNo;
        const dbStdId = (studentId ? stdMap.get(studentId) : null) || (effectiveAdmNo ? stdMap.get(effectiveAdmNo.toLowerCase()) : null) || (typeof studentId === "string" && studentId.length === 36 ? studentId : null) || matchedStd?.db_id;
        if (dbStdId && sessId) {
          let sVal = "present";
          const rawStatus = (item.status || "present").toLowerCase();
          if (rawStatus === "absent") sVal = "absent";
          else if (rawStatus === "late") sVal = "late";
          else if (rawStatus.includes("half")) sVal = "half_day";
          else if (rawStatus === "leave" || rawStatus === "excused") sVal = "excused";

          dbRows.push({
            organization_id: orgId,
            student_id: dbStdId,
            academic_session_id: sessId,
            attendance_date: date,
            status: sVal,
            remarks: item.remarks || null
          });
        }
      }

      if (dbRows.length > 0) {
        await supabase.from("student_attendance").upsert(dbRows, { onConflict: "student_id, attendance_date" });
      }
    } catch (dbErr) {
      console.warn("[Attendance DB Insert Error]:", dbErr.message);
    }
  }

  await recordAuditLog(
    "erp.attendance_saved",
    req.user?.email || markedBy,
    "section_attendance",
    `${grade}-${section}-${date}`,
    req
  );

  res.json({
    success: true,
    message: `Successfully saved attendance for ${grade}-${section} (${date})`,
    totalCount: records.length,
    createdCount,
    updatedCount
  });
});

// 3d. PATCH /api/erp/attendance/student/:id - Single Record Correction
app.patch("/api/erp/attendance/student/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const { status, remarks } = req.body || {};

  const rec = ERP_ATTENDANCE.find(a =>
    (a.organization_id === orgId) &&
    (a.id === id || a.studentId === id || a.student_id === id)
  );

  if (!rec) {
    return res.status(404).json({ success: false, message: "Attendance record not found" });
  }

  const oldStatus = rec.status;
  if (status && status !== oldStatus) {
    rec.status = status;
    await recordAuditLog(
      "erp.attendance_corrected",
      req.user?.email || "admin",
      "student_attendance",
      rec.id,
      req
    );
  }
  if (remarks !== undefined) rec.remarks = remarks;
  rec.updated_at = new Date().toISOString();

  res.json({
    success: true,
    message: "Attendance record updated",
    record: rec
  });
});

// 3e. GET /api/erp/attendance/student/monthly - 31-Day Attendance Matrix Grid
app.get("/api/erp/attendance/student/monthly", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { grade = "Class 10", section = "A", month, year, session = "2026-27" } = req.query;

  const currentYear = year ? parseInt(year) : 2026;
  const currentMonth = month ? parseInt(month) : 9; // 1-indexed (9 = September)

  const daysInMonth = new Date(currentYear, currentMonth, 0).getDate();
  const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  const monthName = monthNames[currentMonth - 1] || "September";

  const classStudents = ERP_STUDENTS.filter(s =>
    (s.organization_id === orgId) &&
    s.grade.toLowerCase() === grade.toLowerCase() &&
    (s.section || "A").toLowerCase() === section.toLowerCase() &&
    s.status !== "inactive" && s.status !== "withdrawn"
  );

  const monthPrefix = `${currentYear}-${String(currentMonth).padStart(2, "0")}`;
  const monthAtt = ERP_ATTENDANCE.filter(a =>
    (a.organization_id === orgId) &&
    a.grade.toLowerCase() === grade.toLowerCase() &&
    (a.section || "A").toLowerCase() === section.toLowerCase() &&
    (a.attendanceDate || a.date || "").startsWith(monthPrefix)
  );

  const resultStudents = classStudents.map(std => {
    const stdRecords = monthAtt.filter(a => a.studentId === std.id || a.student_id === std.id);
    const daysMap = {};
    let presentDays = 0;
    let absentDays = 0;
    let lateDays = 0;
    let leaveDays = 0;
    let halfDays = 0;

    stdRecords.forEach(r => {
      const dStr = (r.attendanceDate || r.date).split("-")[2];
      const dayNum = parseInt(dStr, 10);
      daysMap[dayNum] = r.status;

      if (r.status === "present") presentDays++;
      else if (r.status === "absent") absentDays++;
      else if (r.status === "late") lateDays++;
      else if (r.status === "leave") leaveDays++;
      else if (r.status === "half_day") halfDays++;
    });

    const totalRecorded = presentDays + absentDays + lateDays + leaveDays + halfDays;
    const attendancePercent = totalRecorded > 0
      ? Number(((presentDays + lateDays) / totalRecorded * 100).toFixed(1))
      : 100.0;

    return {
      studentId: std.id,
      admissionNo: std.admissionNo,
      rollNo: std.rollNo,
      name: std.name,
      records: daysMap,
      presentDays,
      absentDays,
      lateDays,
      leaveDays,
      halfDays,
      totalRecordedDays: totalRecorded,
      attendancePercent
    };
  });

  res.json({
    success: true,
    academicSession: session,
    grade,
    section,
    year: currentYear,
    month: currentMonth,
    monthName,
    daysInMonth,
    students: resultStudents
  });
});

// 3f. GET /api/erp/attendance/student/reports - Comprehensive Attendance Reports
app.get("/api/erp/attendance/student/reports", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { type = "daily", threshold = 75, grade, section, startDate, endDate } = req.query;
  const cutoff = parseFloat(threshold) || 75.0;

  const orgStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);
  const orgAttendance = ERP_ATTENDANCE.filter(a => a.organization_id === orgId);

  if (type === "low_attendance") {
    const lowStudents = [];
    orgStudents.forEach(std => {
      const stdRecords = orgAttendance.filter(a => a.studentId === std.id || a.student_id === std.id);
      if (stdRecords.length === 0) return;

      const presentCount = stdRecords.filter(a => a.status === "present" || a.status === "late").length;
      const absentCount = stdRecords.filter(a => a.status === "absent").length;
      const leaveCount = stdRecords.filter(a => a.status === "leave").length;
      const total = stdRecords.length;
      const pct = Number((presentCount / total * 100).toFixed(1));

      if (pct < cutoff) {
        lowStudents.push({
          studentId: std.id,
          admissionNo: std.admissionNo,
          rollNo: std.rollNo,
          studentName: std.name,
          grade: std.grade,
          section: std.section,
          totalWorkingDays: total,
          presentDays: presentCount,
          absentDays: absentCount,
          leaveDays: leaveCount,
          attendancePercent: pct,
          parentName: std.parentName,
          parentPhone: std.parentPhone,
          parentEmail: std.parentEmail
        });
      }
    });

    return res.json({
      success: true,
      type: "low_attendance",
      threshold: cutoff,
      count: lowStudents.length,
      students: lowStudents
    });
  }

  if (type === "daily") {
    const byDate = {};
    orgAttendance.forEach(a => {
      const d = a.attendanceDate || a.date;
      if (!byDate[d]) byDate[d] = { date: d, total: 0, present: 0, absent: 0, late: 0, leave: 0 };
      byDate[d].total++;
      if (a.status === "present") byDate[d].present++;
      else if (a.status === "absent") byDate[d].absent++;
      else if (a.status === "late") byDate[d].late++;
      else if (a.status === "leave") byDate[d].leave++;
    });
    const list = Object.values(byDate).sort((a, b) => b.date.localeCompare(a.date));
    return res.json({ success: true, type: "daily", reports: list });
  }

  res.json({ success: true, type, message: "Report generated", count: 0, data: [] });
});

// =========================================================================
// 3g. STAFF HR, ATTENDANCE & PAYROLL SUBSYSTEM (Supabase PostgreSQL Live Persistence)
// =========================================================================

let ERP_STAFF_LEAVES = [];

// Helper: Resolve or create staff in memory and public.staff PostgreSQL table
async function resolveOrCreateStaff(orgId, staffIdentifier) {
  if (!staffIdentifier) return { staff: null, db_id: null };

  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const targetId = typeof staffIdentifier === "string" ? staffIdentifier : (staffIdentifier.id || staffIdentifier.staffId || staffIdentifier.empId);
  
  let memoryStaff = ERP_STAFF.find(s => 
    (s.organization_id === orgId) && 
    (s.id === targetId || s.empId === targetId || s.db_id === targetId || (typeof staffIdentifier === "object" && s.email && s.email === staffIdentifier.email))
  );

  let dbStaffId = memoryStaff?.db_id || (isUuid.test(targetId) ? targetId : null);

  if (supabase) {
    try {
      if (!dbStaffId) {
        let q = supabase.from("staff").select("*").eq("organization_id", orgId);
        if (isUuid.test(targetId)) {
          q = q.eq("id", targetId);
        } else {
          const code = typeof staffIdentifier === "object" ? (staffIdentifier.empId || staffIdentifier.employee_code || targetId) : targetId;
          q = q.eq("employee_code", code);
        }
        const { data: dbExisting } = await q.maybeSingle();
        if (dbExisting) {
          dbStaffId = dbExisting.id;
          if (memoryStaff) memoryStaff.db_id = dbExisting.id;
          return { staff: memoryStaff || dbExisting, db_id: dbStaffId, dbStaff: dbExisting };
        }
      }

      if (!dbStaffId && typeof staffIdentifier === "object") {
        const empCode = staffIdentifier.empId || staffIdentifier.employee_code || `FAC-${Math.floor(100 + Math.random() * 900)}`;
        const fullName = staffIdentifier.name || `${staffIdentifier.firstName || "Faculty"} ${staffIdentifier.lastName || ""}`.trim();
        const firstName = staffIdentifier.firstName || fullName.split(" ")[0] || "Faculty";
        const lastName = staffIdentifier.lastName || fullName.split(" ").slice(1).join(" ") || null;
        const dbGender = (staffIdentifier.gender || "").toLowerCase().includes("female")
          ? "female"
          : (staffIdentifier.gender || "").toLowerCase().includes("male")
          ? "male"
          : "other";

        const { data: newDbStaff, error: insErr } = await supabase
          .from("staff")
          .insert([{
            organization_id: orgId,
            employee_code: empCode,
            first_name: firstName,
            last_name: lastName,
            gender: dbGender,
            phone: staffIdentifier.phone || null,
            email: staffIdentifier.email || null,
            designation: staffIdentifier.designation || "Teacher",
            department: staffIdentifier.department || "Academics",
            joining_date: staffIdentifier.joiningDate || new Date().toISOString().split("T")[0],
            is_active: staffIdentifier.isActive !== false
          }])
          .select()
          .maybeSingle();

        if (newDbStaff) {
          dbStaffId = newDbStaff.id;
          if (memoryStaff) memoryStaff.db_id = newDbStaff.id;
          return { staff: memoryStaff || newDbStaff, db_id: dbStaffId, dbStaff: newDbStaff };
        }
      }
    } catch (e) {
      console.warn("[DB] resolveOrCreateStaff exception:", e.message);
    }
  }

  return { staff: memoryStaff, db_id: dbStaffId || memoryStaff?.id };
}

// Helper: Upsert staff daily attendance into public.staff_attendance PostgreSQL table
async function recordStaffAttendanceDb(orgId, staffId, date, status, remarks, markedByUserId) {
  const statusMap = {
    present: "present",
    absent: "absent",
    late: "late",
    half_day: "half_day",
    "half-day": "half_day",
    leave: "leave",
    on_leave: "leave"
  };
  const enumStatus = statusMap[(status || "").toLowerCase()] || "present";

  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  let dbStaffId = null;

  let memoryStaff = ERP_STAFF.find(s => 
    (s.organization_id === orgId) && 
    (s.id === staffId || s.empId === staffId || s.db_id === staffId)
  );

  if (memoryStaff && memoryStaff.db_id) {
    dbStaffId = memoryStaff.db_id;
  } else if (isUuid.test(staffId)) {
    dbStaffId = staffId;
  }

  if (supabase) {
    try {
      if (!dbStaffId) {
        const resolved = await resolveOrCreateStaff(orgId, memoryStaff || { id: staffId, empId: staffId });
        dbStaffId = resolved.db_id;
      }
      if (dbStaffId) {
        const isUserIdUuid = markedByUserId && isUuid.test(markedByUserId);
        const { data, error } = await supabase
          .from("staff_attendance")
          .upsert([{
            organization_id: orgId,
            staff_id: dbStaffId,
            attendance_date: date,
            status: enumStatus,
            remarks: remarks || null,
            marked_by: isUserIdUuid ? markedByUserId : null
          }], { onConflict: "staff_id,attendance_date" })
          .select();
        if (error) {
          console.warn("[DB] Staff attendance upsert warning:", error.message);
        } else {
          return data;
        }
      }
    } catch (e) {
      console.warn("[DB] Staff attendance upsert exception:", e.message);
    }
  }
  return null;
}

// Helper: Persist staff leave request into public.leave_requests PostgreSQL table
async function recordStaffLeaveRequestDb(orgId, staffId, fromDate, toDate, reason, status = "pending", approvedByUserId = null) {
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  let dbStaffId = null;

  let memoryStaff = ERP_STAFF.find(s => 
    (s.organization_id === orgId) && 
    (s.id === staffId || s.empId === staffId || s.db_id === staffId)
  );

  if (memoryStaff && memoryStaff.db_id) {
    dbStaffId = memoryStaff.db_id;
  } else if (isUuid.test(staffId)) {
    dbStaffId = staffId;
  }

  if (supabase) {
    try {
      if (!dbStaffId) {
        const resolved = await resolveOrCreateStaff(orgId, memoryStaff || { id: staffId, empId: staffId });
        dbStaffId = resolved.db_id;
      }
      if (dbStaffId) {
        const isUserIdUuid = approvedByUserId && isUuid.test(approvedByUserId);
        const { data, error } = await supabase
          .from("leave_requests")
          .insert([{
            organization_id: orgId,
            staff_id: dbStaffId,
            from_date: fromDate,
            to_date: toDate,
            reason: reason || "Staff Leave Application",
            status: status || "pending",
            approved_by: isUserIdUuid ? approvedByUserId : null
          }])
          .select()
          .maybeSingle();
        if (error) {
          console.warn("[DB] Leave request insert warning:", error.message);
        } else if (data) {
          return data;
        }
      }
    } catch (e) {
      console.warn("[DB] Leave request insert exception:", e.message);
    }
  }
  return null;
}

// Helper: Calculate standard Indian School statutory payroll breakdown
function calculateStaffPayroll(staff, salaryMonth, workingDays = 30, absentDays = 0) {
  const baseSalary = Number(staff.salaryINR) || 50000;
  
  // Earnings Components
  const basicSalary = Math.round(baseSalary * 0.50);
  const da = Math.round(baseSalary * 0.20);
  const hra = Math.round(baseSalary * 0.20);
  const specialAllowance = Math.round(baseSalary * 0.10);
  const grossSalary = basicSalary + da + hra + specialAllowance;

  // Deductions Components
  const pf = Math.round(basicSalary * 0.12);
  const professionalTax = 200;
  const tds = grossSalary > 60000 ? Math.round((grossSalary - 60000) * 0.10) : 0;
  const lop = absentDays > 0 ? Math.round((grossSalary / workingDays) * absentDays) : 0;
  const totalDeductions = pf + professionalTax + tds + lop;
  const netSalary = Math.max(0, grossSalary - totalDeductions);

  return {
    baseSalary,
    earnings: {
      basicSalary,
      da,
      hra,
      specialAllowance,
      grossSalary
    },
    deductions: {
      pf,
      professionalTax,
      tds,
      lop,
      totalDeductions
    },
    netSalary,
    workingDays,
    absentDays,
    payableDays: Math.max(0, workingDays - absentDays)
  };
}

