// 1. GET /api/erp/responsibilities - List configurable templates (CBSE, Delhi Govt, State Boards, etc.)
app.get("/api/erp/responsibilities", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { category, active, search } = req.query;
  const types = ResponsibilityService.getResponsibilityTypes(orgId, { category, active, search });
  res.json({ success: true, count: types.length, responsibilities: types });
});

// 2. POST /api/erp/responsibilities - School Admin creates / customizes template
app.post("/api/erp/responsibilities", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { code, name, description, category, default_scope_type } = req.body;
  if (!code || !name) {
    return res.status(400).json({ success: false, message: "Code and Name are required" });
  }
  const created = ResponsibilityService.createResponsibilityType(orgId, req.body);
  res.status(201).json({ success: true, responsibility: created });
});

// 3. GET /api/erp/staff/:id/responsibilities - List incharge assignments for staff
app.get("/api/erp/staff/:id/responsibilities", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const staffId = req.params.id;
  const list = ResponsibilityService.getStaffResponsibilities(orgId, staffId, req.query.session);
  res.json({ success: true, staffId, responsibilities: list });
});

// 4. POST /api/erp/staff/:id/responsibilities - Assign incharge role with scope
app.post("/api/erp/staff/:id/responsibilities", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const staffId = req.params.id;
  const { responsibility_type_id, responsibility_code, scope_type, scope_id, academic_session_id } = req.body;
  if (!responsibility_type_id && !responsibility_code) {
    return res.status(400).json({ success: false, message: "Responsibility type or code is required" });
  }
  const assigned = ResponsibilityService.assignStaffResponsibility(orgId, staffId, req.body);
  res.status(201).json({ success: true, responsibility: assigned });
});

// 5. PATCH /api/erp/staff/:id/responsibilities/:respId - Update incharge assignment
app.patch("/api/erp/staff/:id/responsibilities/:respId", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id: staffId, respId } = req.params;
  const updated = ResponsibilityService.updateStaffResponsibility(orgId, staffId, respId, req.body);
  if (!updated) {
    return res.status(404).json({ success: false, message: "Staff responsibility record not found" });
  }
  res.json({ success: true, responsibility: updated });
});

// 6. DELETE /api/erp/staff/:id/responsibilities/:respId - Revoke responsibility
app.delete("/api/erp/staff/:id/responsibilities/:respId", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id: staffId, respId } = req.params;
  const deleted = ResponsibilityService.deleteStaffResponsibility(orgId, staffId, respId);
  if (!deleted) {
    return res.status(404).json({ success: false, message: "Staff responsibility record not found" });
  }
  res.json({ success: true, message: "Responsibility assignment revoked successfully" });
});

// 7. GET /api/erp/staff/:id/effective-access - Effective Access Preview for Admin
app.get("/api/erp/staff/:id/effective-access", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const staffId = req.params.id;
  const staffMember = ERP_STAFF.find(s => s.id === staffId || s.staffId === staffId);
  const effectiveAccess = ResponsibilityService.getEffectiveAccess(orgId, staffMember || { role: "teacher" }, staffId, req.query.session);
  res.json({ success: true, staffId, effectiveAccess });
});

// 4. Academics Endpoints (Production SaaS Grade)

// 4a. GET /api/erp/academics/overview - Aggregated live KPIs, active session, and section breakdown
app.get("/api/erp/academics/overview", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const tenantSessions = ERP_ACADEMIC_SESSIONS
    .filter(s => s.organization_id === orgId)
    .map(s => ({ ...s, name: s.name || s.sessionName, sessionName: s.sessionName || s.name }));
  const currentSession = tenantSessions.find(s => s.isCurrent) || tenantSessions.find(s => s.status === "active") || tenantSessions[0] || { name: "2026-27", sessionName: "2026-27" };
  const tenantClasses = ERP_CLASSES.filter(c => c.organization_id === orgId);
  const tenantSections = ERP_SECTIONS.filter(sec => sec.organization_id === orgId);
  const tenantSubjects = ERP_SUBJECTS.filter(sub => sub.organization_id === orgId);
  const tenantMappings = ERP_SECTION_SUBJECTS.filter(m => m.organization_id === orgId);
  const tenantHomework = ERP_HOMEWORK.filter(h => h.organization_id === orgId);
  const tenantStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);

  const sectionsWithCounts = tenantSections.map(sec => {
    const studentCount = tenantStudents.filter(s => 
      s.grade.toLowerCase() === sec.grade.toLowerCase() && 
      s.section.toLowerCase() === sec.section.toLowerCase() && 
      s.status === "active"
    ).length;
    const subjectsCount = tenantMappings.filter(m => 
      m.grade.toLowerCase() === sec.grade.toLowerCase() && 
      m.section.toLowerCase() === sec.section.toLowerCase()
    ).length;
    return {
      ...sec,
      studentCount,
      subjectsCount
    };
  });

  const totalActiveStudents = tenantStudents.filter(s => s.status === "active").length;
  const assignedClassTeachers = tenantSections.filter(s => s.classTeacherId).length;
  const unassignedClassTeachers = tenantSections.filter(s => !s.classTeacherId).length;

  res.json({
    success: true,
    overview: {
      activeSession: currentSession.name || currentSession.sessionName,
      currentSession,
      totalSessions: tenantSessions.length,
      totalClasses: tenantClasses.length,
      totalSections: tenantSections.length,
      totalSubjects: tenantSubjects.length,
      totalStudentsEnrolled: totalActiveStudents,
      assignedClassTeachers,
      unassignedClassTeachers,
      totalSectionSubjectMappings: tenantMappings.length,
      totalHomeworkAssigned: tenantHomework.length
    },
    sections: sectionsWithCounts,
    sessions: tenantSessions
  });
});

// Helper: Resolve or create academic session in Supabase public.academic_sessions
async function resolveOrCreateSession(orgId, sessionName = "2026-27") {
  if (!supabase || !orgId) return null;
  const name = (sessionName || "2026-27").trim();
  try {
    let { data: ses } = await supabase
      .from("academic_sessions")
      .select("id")
      .eq("organization_id", orgId)
      .eq("name", name)
      .maybeSingle();

    if (!ses) {
      const { data: newSes, error } = await supabase
        .from("academic_sessions")
        .insert([{
          organization_id: orgId,
          name,
          start_date: "2026-04-01",
          end_date: "2027-03-31",
          is_current: true
        }])
        .select()
        .maybeSingle();
      if (!error && newSes) ses = newSes;
    }
    return ses?.id || null;
  } catch (e) {
    console.warn("[Academic Session Resolve Error]:", e.message);
    return null;
  }
}

// 4b. Academic Sessions Endpoints (PostgreSQL Backed)
app.get(["/api/erp/academics/sessions", "/api/erp/academic-sessions"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });

  let sessions = [];
  if (supabase && orgId) {
    try {
      const { data: dbSessions, error } = await supabase
        .from("academic_sessions")
        .select("*")
        .eq("organization_id", orgId)
        .order("start_date", { ascending: false });

      if (dbSessions && dbSessions.length > 0) {
        sessions = dbSessions.map(s => ({
          id: s.id,
          name: s.name,
          sessionName: s.name,
          startDate: s.start_date,
          endDate: s.end_date,
          isCurrent: !!s.is_current,
          status: s.is_current ? "active" : "upcoming",
          organization_id: s.organization_id,
          createdAt: s.created_at
        }));
      }
    } catch (e) {
      console.warn("[Academic Sessions DB Fetch Error]:", e.message);
    }
  }

  if (sessions.length === 0 && orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e") {
    sessions = ERP_ACADEMIC_SESSIONS
      .filter(s => s.organization_id === orgId)
      .map(s => ({ ...s, name: s.name || s.sessionName, sessionName: s.sessionName || s.name }));
  }

  res.json({ success: true, sessions });
});

app.post(["/api/erp/academics/sessions", "/api/erp/academic-sessions"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  const { name, sessionName, startDate, endDate, isCurrent = false, status = "upcoming" } = req.body;
  const effectiveName = (name || sessionName || "").trim();

  if (!effectiveName || !startDate || !endDate) {
    return res.status(400).json({ success: false, message: "Session name, start date, and end date are required" });
  }

  if (new Date(startDate) >= new Date(endDate)) {
    return res.status(400).json({ success: false, message: "Start date must be before end date" });
  }

  let newSession = null;
  if (supabase && orgId) {
    try {
      // Check duplicate in DB
      const { data: dup } = await supabase
        .from("academic_sessions")
        .select("id")
        .eq("organization_id", orgId)
        .eq("name", effectiveName)
        .maybeSingle();

      if (dup) {
        return res.status(400).json({ success: false, message: `Academic session '${effectiveName}' already exists` });
      }

      if (isCurrent) {
        await supabase
          .from("academic_sessions")
          .update({ is_current: false })
          .eq("organization_id", orgId);
      }

      const { data: dbSes, error: insertErr } = await supabase
        .from("academic_sessions")
        .insert([{
          organization_id: orgId,
          name: effectiveName,
          start_date: startDate,
          end_date: endDate,
          is_current: !!isCurrent
        }])
        .select()
        .maybeSingle();

      if (dbSes) {
        newSession = {
          id: dbSes.id,
          name: dbSes.name,
          sessionName: dbSes.name,
          startDate: dbSes.start_date,
          endDate: dbSes.end_date,
          status: dbSes.is_current ? "active" : status,
          isCurrent: !!dbSes.is_current,
          organization_id: orgId,
          createdAt: dbSes.created_at
        };
      }
    } catch (e) {
      console.warn("[Academic Session DB Insert Error]:", e.message);
    }
  }

  if (!newSession) {
    const duplicate = ERP_ACADEMIC_SESSIONS.find(s => 
      (s.organization_id === orgId) && 
      (s.name || s.sessionName || "").toLowerCase() === effectiveName.toLowerCase()
    );
    if (duplicate) {
      return res.status(400).json({ success: false, message: `Academic session '${effectiveName}' already exists` });
    }

    if (isCurrent) {
      ERP_ACADEMIC_SESSIONS.forEach(s => {
        if (s.organization_id === orgId) {
          s.isCurrent = false;
          if (s.status === "active") s.status = "closed";
        }
      });
    }

    newSession = {
      id: `ses-${Date.now()}`,
      name: effectiveName,
      sessionName: effectiveName,
      startDate,
      endDate,
      status: isCurrent ? "active" : status,
      isCurrent: !!isCurrent,
      organization_id: orgId,
      createdAt: new Date().toISOString()
    };
    ERP_ACADEMIC_SESSIONS.push(newSession);
  }

  await recordAuditLog("erp.session_created", req.user?.email || "admin", "academic_session", newSession.id, req);
  res.json({ success: true, message: "Academic session created successfully", session: newSession });
});

app.patch("/api/erp/academics/sessions/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  const { id } = req.params;
  const { name, sessionName, startDate, endDate, status, isCurrent } = req.body;

  if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
    return res.status(400).json({ success: false, message: "Start date must be before end date" });
  }

  const updateData = {};
  const effName = name || sessionName;
  if (effName !== undefined) updateData.name = effName.trim();
  if (startDate !== undefined) updateData.start_date = startDate;
  if (endDate !== undefined) updateData.end_date = endDate;
  if (isCurrent !== undefined) updateData.is_current = !!isCurrent;

  if (supabase && orgId) {
    try {
      if (isCurrent === true) {
        await supabase
          .from("academic_sessions")
          .update({ is_current: false })
          .eq("organization_id", orgId);
      }

      const { data: updated, error } = await supabase
        .from("academic_sessions")
        .update(updateData)
        .eq("organization_id", orgId)
        .or(`id.eq.${id},name.eq.${id}`)
        .select()
        .maybeSingle();

      if (updated) {
        await recordAuditLog("erp.session_updated", req.user?.email || "admin", "academic_session", updated.id, req);
        return res.json({
          success: true,
          message: "Academic session updated successfully",
          session: {
            id: updated.id,
            name: updated.name,
            sessionName: updated.name,
            startDate: updated.start_date,
            endDate: updated.end_date,
            isCurrent: !!updated.is_current,
            status: updated.is_current ? "active" : "upcoming",
            organization_id: orgId
          }
        });
      }
    } catch (e) {
      console.warn("[Academic Session DB Update Error]:", e.message);
    }
  }

  const session = ERP_ACADEMIC_SESSIONS.find(s => 
    (s.organization_id === orgId) && s.id === id
  );
  if (!session) {
    return res.status(404).json({ success: false, message: "Academic session not found" });
  }

  if (isCurrent === true) {
    ERP_ACADEMIC_SESSIONS.forEach(s => {
      if (s.organization_id === orgId) {
        s.isCurrent = false;
      }
    });
    session.isCurrent = true;
    session.status = "active";
  }

  if (effName !== undefined) {
    session.name = effName.trim();
    session.sessionName = effName.trim();
  }
  if (startDate !== undefined) session.startDate = startDate;
  if (endDate !== undefined) session.endDate = endDate;
  if (status !== undefined && isCurrent !== true) session.status = status;
  session.updatedAt = new Date().toISOString();

  await recordAuditLog("erp.session_updated", req.user?.email || "admin", "academic_session", session.id, req);
  res.json({ success: true, message: "Academic session updated successfully", session: { ...session, name: session.name || session.sessionName, sessionName: session.sessionName || session.name } });
});

app.post("/api/erp/academics/sessions/:id/activate", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  const { id } = req.params;

  if (supabase && orgId) {
    try {
      await supabase
        .from("academic_sessions")
        .update({ is_current: false })
        .eq("organization_id", orgId);

      const { data: activated, error } = await supabase
        .from("academic_sessions")
        .update({ is_current: true })
        .eq("organization_id", orgId)
        .or(`id.eq.${id},name.eq.${id}`)
        .select()
        .maybeSingle();

      if (activated) {
        await recordAuditLog("erp.session_activated", req.user?.email || "admin", "academic_session", activated.id, req);
        return res.json({
          success: true,
          message: `Academic session '${activated.name}' is now active`,
          session: {
            id: activated.id,
            name: activated.name,
            sessionName: activated.name,
            startDate: activated.start_date,
            endDate: activated.end_date,
            isCurrent: true,
            status: "active",
            organization_id: orgId
          }
        });
      }
    } catch (e) {
      console.warn("[Academic Session DB Activate Error]:", e.message);
    }
  }

  const session = ERP_ACADEMIC_SESSIONS.find(s => 
    (s.organization_id === orgId) && s.id === id
  );
  if (!session) {
    return res.status(404).json({ success: false, message: "Academic session not found" });
  }

  ERP_ACADEMIC_SESSIONS.forEach(s => {
    if (s.organization_id === orgId) {
      s.isCurrent = false;
      if (s.id !== id && s.status === "active") {
        s.status = "closed";
      }
    }
  });

  session.isCurrent = true;
  session.status = "active";
  session.updatedAt = new Date().toISOString();

  await recordAuditLog("erp.session_activated", req.user?.email || "admin", "academic_session", session.id, req);
  res.json({ success: true, message: `Academic session '${session.name || session.sessionName}' is now active`, session: { ...session, name: session.name || session.sessionName, sessionName: session.sessionName || session.name } });
});

// 4b-2. POST /api/erp/academics/promote - Batch Session Transition & Class Promotion Engine
app.post("/api/erp/academics/promote", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });

  let {
    sourceSessionId,
    targetSessionId,
    targetAcademicSessionId,
    studentIds,
    targetClassId,
    targetSectionId,
    promotions = [] // [ { studentId, toClassId, toSectionId, rollNo, status: "promoted" | "detained" | "graduated" } ]
  } = req.body || {};

  if (!targetSessionId && targetAcademicSessionId) targetSessionId = targetAcademicSessionId;

  // If studentIds is passed as a flat list:
  if ((!promotions || promotions.length === 0) && Array.isArray(studentIds) && studentIds.length > 0) {
    promotions = studentIds.map(stId => ({
      studentId: stId,
      toClassId: targetClassId,
      toSectionId: targetSectionId,
      status: "promoted"
    }));
  }

  // If sourceSessionId is missing, resolve the current session for the org
  if (!sourceSessionId && supabase) {
    try {
      const { data: curSess } = await supabase
        .from("academic_sessions")
        .select("id")
        .eq("organization_id", orgId)
        .eq("is_current", true)
        .maybeSingle();
      if (curSess) sourceSessionId = curSess.id;
    } catch (_) {}
  }

  if (!sourceSessionId && typeof ERP_ACADEMIC_SESSIONS !== "undefined") {
    const cur = ERP_ACADEMIC_SESSIONS.find(s => s.organization_id === orgId && s.isCurrent);
    if (cur) sourceSessionId = cur.id || cur.db_id;
  }

  if (!sourceSessionId) {
    sourceSessionId = "current-session";
  }

  if (!targetSessionId || !Array.isArray(promotions) || promotions.length === 0) {
    return res.status(400).json({
      success: false,
      message: "targetSessionId and promotions array (or studentIds) are required."
    });
  }

  const results = {
    promoted: 0,
    detained: 0,
    graduated: 0,
    errors: []
  };

  const now = new Date().toISOString();

  for (const item of promotions) {
    try {
      const { studentId, toClassId, toSectionId, rollNo, status = "promoted" } = item;
      if (!studentId) continue;

      let resolvedStudentId = studentId;
      if (supabase && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(resolvedStudentId)) {
        const memStd = ERP_STUDENTS.find(s => (s.organization_id === orgId) && (s.id === studentId || s.admissionNo === studentId));
        if (memStd?.db_id) {
          resolvedStudentId = memStd.db_id;
        } else {
          try {
            const { data: dbStd } = await supabase.from("students").select("id").eq("organization_id", orgId).or(`admission_no.eq.${studentId},id.eq.${studentId}`).maybeSingle();
            if (dbStd) resolvedStudentId = dbStd.id;
          } catch (_) {}
        }
      }

      let resolvedClassId = toClassId;
      if (toClassId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(toClassId)) {
        const c = ERP_CLASSES.find(cl => cl.id === toClassId || cl.db_id === toClassId);
        if (c?.db_id) resolvedClassId = c.db_id;
      }

      let resolvedSectionId = toSectionId;
      if (toSectionId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(toSectionId)) {
        const s = ERP_SECTIONS.find(sec => sec.id === toSectionId || sec.db_id === toSectionId);
        if (s?.db_id) resolvedSectionId = s.db_id;
      }
      if (!resolvedSectionId && resolvedClassId && supabase) {
        try {
          const { data: dbSec } = await supabase.from("sections").select("id").eq("class_id", resolvedClassId).limit(1).maybeSingle();
          if (dbSec) resolvedSectionId = dbSec.id;
        } catch (_) {}
      }

      const todayDate = now.split("T")[0];

      if (status === "graduated") {
        if (supabase && resolvedStudentId) {
          await supabase
            .from("student_enrollments")
            .update({ left_on: todayDate })
            .eq("organization_id", orgId)
            .eq("student_id", resolvedStudentId)
            .is("left_on", null);

          await supabase
            .from("students")
            .update({ admission_status: "withdrawn", updated_at: now })
            .eq("id", resolvedStudentId)
            .eq("organization_id", orgId);
        }
        results.graduated++;
        continue;
      }

      if (supabase && resolvedStudentId) {
        await supabase
          .from("student_enrollments")
          .update({ left_on: todayDate })
          .eq("organization_id", orgId)
          .eq("student_id", resolvedStudentId)
          .is("left_on", null);

        if (resolvedClassId && resolvedSectionId) {
          const { error: insErr } = await supabase
            .from("student_enrollments")
            .insert([{
              id: crypto.randomUUID(),
              organization_id: orgId,
              student_id: resolvedStudentId,
              academic_session_id: targetSessionId,
              class_id: resolvedClassId,
              section_id: resolvedSectionId,
              roll_no: rollNo || null,
              joined_on: todayDate
            }]);

          if (insErr) {
            console.warn("[Promote Enrollment Insert Warning]:", insErr.message);
          }

          // Auto-generate fee demands for target session if fee structures exist for the new class
          try {
            const { data: structures } = await supabase
              .from("fee_structures")
              .select("*")
              .eq("organization_id", orgId)
              .eq("academic_session_id", targetSessionId);

            if (structures && structures.length > 0) {
              for (const fs of structures) {
                await supabase
                  .from("student_fees")
                  .insert([{
                    id: crypto.randomUUID(),
                    organization_id: orgId,
                    student_id: resolvedStudentId,
                    fee_structure_id: fs.id,
                    amount_due: fs.amount,
                    amount_paid: 0,
                    status: "pending",
                    due_date: fs.due_date || null
                  }]);
              }
            }
          } catch (_) {}
        }
      }

      if (status === "detained") {
        results.detained++;
      } else {
        results.promoted++;
      }
    } catch (err) {
      results.errors.push({ studentId: item.studentId, error: err.message });
    }
  }

  await recordAuditLog("academics.promotion_batch", req.user?.email || "admin", "academics", `${results.promoted} students`, req);

  res.json({
    success: true,
    message: `Academic Session Rollover Complete: ${results.promoted} promoted, ${results.detained} detained, ${results.graduated} graduated ✅`,
    results,
    summary: {
      promotedCount: results.promoted,
      detainedCount: results.detained,
      graduatedCount: results.graduated,
      totalProcessed: results.promoted + results.detained + results.graduated
    }
  });
});

// 4c. Academic Classes Endpoints (PostgreSQL Backed)
app.get(["/api/erp/academics/classes", "/api/erp/classes"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });

  let classes = [];
  if (supabase && orgId) {
    try {
      const { data: dbClasses } = await supabase
        .from("classes")
        .select("*")
        .eq("organization_id", orgId)
        .order("display_order", { ascending: true });

      if (dbClasses && dbClasses.length > 0) {
        const { data: dbSecs } = await supabase
          .from("sections")
          .select("*")
          .eq("organization_id", orgId);
        
        const tenantSecs = dbSecs || [];
        const { data: dbStudents } = await supabase
          .from("students")
          .select("id, grade, student_enrollments(class_id)")
          .eq("organization_id", orgId);
        const tenantDbStudents = dbStudents || [];

        classes = dbClasses.map(c => {
          const classSections = tenantSecs.filter(sec => sec.class_id === c.id || (sec.name && c.name && sec.grade?.toLowerCase() === c.name.toLowerCase()));
          const totalStudents = tenantDbStudents.filter(s => {
            const matchEnr = s.student_enrollments && s.student_enrollments.some(e => e.class_id === c.id);
            const matchGrade = s.grade && s.grade.toLowerCase() === c.name.toLowerCase();
            return matchEnr || matchGrade;
          }).length;
          return {
            id: c.id,
            grade: c.name,
            name: c.name,
            code: c.code || `CLS-${c.display_order || 1}`,
            order: c.display_order,
            wing: c.code || "Secondary Wing",
            status: "active",
            organization_id: c.organization_id,
            sectionsCount: classSections.length,
            studentCount: totalStudents
          };
        });
      }
    } catch (e) {
      console.warn("[Classes DB Fetch Error]:", e.message);
    }
  }

  // If DB returned nothing, only seed org b17780e5-3832-4ac6-9aeb-33fd80c5cb0e may use memory seed
  if (classes.length === 0 && orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e") {
    const memClasses = ERP_CLASSES.filter(c => c.organization_id === orgId);
    const tenantStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);
    const tenantSections = ERP_SECTIONS.filter(s => s.organization_id === orgId);
    classes = memClasses.map(c => {
      const classSections = tenantSections.filter(sec => sec.grade.toLowerCase() === c.grade.toLowerCase());
      const totalStudents = tenantStudents.filter(s => s.grade.toLowerCase() === c.grade.toLowerCase() && s.status === "active").length;
      return {
        ...c,
        sectionsCount: classSections.length,
        studentCount: totalStudents
      };
    }).sort((a, b) => (a.order || 0) - (b.order || 0));
  }

  res.json({ success: true, classes });
});

app.post(["/api/erp/academics/classes", "/api/erp/classes"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  const { grade, name, section, roomNumber, wing, order, status = "active" } = req.body;
  const effectiveGrade = (grade || name || "").trim();

  if (!effectiveGrade) {
    return res.status(400).json({ success: false, message: "Grade / Class name is required" });
  }

  const numOrder = order !== undefined ? parseInt(order, 10) : parseInt(effectiveGrade.replace(/\D/g, "") || "1", 10);
  let newClass = null;

  if (supabase && orgId) {
    try {
      const { data: dbCls, error: clsErr } = await supabase
        .from("classes")
        .upsert([{
          organization_id: orgId,
          name: effectiveGrade,
          code: wing || `CLS-${numOrder}`,
          display_order: numOrder
        }], { onConflict: "organization_id, name" })
        .select()
        .maybeSingle();

      if (dbCls) {
        newClass = {
          id: dbCls.id,
          grade: dbCls.name,
          name: dbCls.name,
          order: dbCls.display_order,
          wing: dbCls.code || wing || "Secondary Wing",
          status,
          organization_id: orgId
        };
      }
    } catch (e) {
      console.warn("[Classes DB Insert Error]:", e.message);
    }
  }

  if (!newClass) {
    newClass = {
      id: `cls-${Date.now()}`,
      grade: effectiveGrade,
      name: effectiveGrade,
      order: numOrder,
      wing: wing || "Secondary Wing",
      status,
      organization_id: orgId
    };
  }

  const exIdx = ERP_CLASSES.findIndex(c => (c.organization_id === orgId) && c.grade.toLowerCase() === effectiveGrade.toLowerCase());
  if (exIdx !== -1) ERP_CLASSES[exIdx] = newClass;
  else ERP_CLASSES.push(newClass);

  if (section) {
    const secName = section.trim().toUpperCase();
    if (supabase && orgId && newClass.id) {
      try {
        await supabase.from("sections").upsert([{
          organization_id: orgId,
          class_id: newClass.id,
          name: secName,
          room_no: roomNumber || "R101"
        }], { onConflict: "class_id, name" });
      } catch (_) {}
    }
    const existingSec = ERP_SECTIONS.find(s => 
      (s.organization_id === orgId) && 
      s.grade.toLowerCase() === effectiveGrade.toLowerCase() && 
      s.section.toUpperCase() === secName
    );
    if (!existingSec) {
      ERP_SECTIONS.push({
        id: `sec-${Date.now()}`,
        grade: effectiveGrade,
        section: secName,
        roomNumber: roomNumber || "R101",
        organization_id: orgId
      });
    }
  }

  await recordAuditLog("erp.class_created", req.user?.email || "admin", "academic_class", newClass.id, req);
  res.json({ success: true, message: "Class created successfully", class: newClass });
});

app.patch(["/api/erp/academics/classes/:id", "/api/erp/classes/:id"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const { grade, wing, order, status } = req.body;

  if (supabase && orgId) {
    try {
      const updateData = {};
      if (grade !== undefined) updateData.name = grade.trim();
      if (wing !== undefined) updateData.code = wing.trim();
      if (order !== undefined) updateData.display_order = parseInt(order, 10);
      await supabase.from("classes").update(updateData).eq("organization_id", orgId).or(`id.eq.${id},name.eq.${id}`);
    } catch (_) {}
  }

  let cls = ERP_CLASSES.find(c => (c.organization_id === orgId) && (c.id === id || c.grade === id));
  if (cls) {
    if (grade !== undefined) cls.grade = grade.trim();
    if (wing !== undefined) cls.wing = wing.trim();
    if (order !== undefined) cls.order = parseInt(order, 10);
    if (status !== undefined) cls.status = status;
  } else {
    cls = { id, grade: grade || "Class", order: parseInt(order, 10) || 1, wing: wing || "Main Wing", status: status || "active", organization_id: orgId };
  }

  await recordAuditLog("erp.class_updated", req.user?.email || "admin", "academic_class", cls.id, req);
  res.json({ success: true, message: "Class updated successfully", class: cls });
});

app.delete(["/api/erp/academics/classes/:id", "/api/erp/classes/:id"], async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  if (supabase && orgId) {
    try {
      await supabase.from("classes").delete().eq("organization_id", orgId).or(`id.eq.${id},name.eq.${id}`);
    } catch (_) {}
  }
  const idx = ERP_CLASSES.findIndex(c => (c.organization_id === orgId) && (c.id === id || c.grade === id));
  if (idx !== -1) ERP_CLASSES.splice(idx, 1);
  res.json({ success: true, message: "Class deleted successfully" });
});

// 4d. Academic Sections Endpoints (PostgreSQL Backed)
app.get("/api/erp/academics/sections", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  const { grade } = req.query;

  let sections = [];
  if (supabase && orgId) {
    try {
      const { data: dbSecs } = await supabase
        .from("sections")
        .select("*, classes(name)")
        .eq("organization_id", orgId);

      if (dbSecs && dbSecs.length > 0) {
        sections = dbSecs.map(s => ({
          id: s.id,
          class_id: s.class_id,
          grade: s.classes?.name || s.name,
          section: s.name,
          name: s.name,
          roomNumber: s.room_no || "R101",
          capacity: s.capacity || 40,
          classTeacherId: s.class_teacher_member_id || null,
          status: "active",
          organization_id: s.organization_id
        }));
      }
    } catch (e) {
      console.warn("[Sections DB Fetch Error]:", e.message);
    }
  }

  if (sections.length === 0 && orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e") {
    sections = ERP_SECTIONS.filter(s => s.organization_id === orgId);
  }

  if (grade && grade !== "all") {
    sections = sections.filter(s => s.grade.toLowerCase() === grade.toLowerCase());
  }

  const tenantStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);
  const tenantMappings = ERP_SECTION_SUBJECTS.filter(m => m.organization_id === orgId);

  const enrichedSections = sections.map(sec => {
    const studentCount = tenantStudents.filter(s => 
      s.grade && sec.grade && s.grade.toLowerCase() === sec.grade.toLowerCase() && 
      s.section && sec.section && s.section.toLowerCase() === sec.section.toLowerCase() && 
      s.status === "active"
    ).length;
    const subjects = tenantMappings.filter(m => 
      m.grade && sec.grade && m.grade.toLowerCase() === sec.grade.toLowerCase() && 
      m.section && sec.section && m.section.toLowerCase() === sec.section.toLowerCase()
    );
    return {
      ...sec,
      studentCount,
      subjectsCount: subjects.length,
      subjects
    };
  });

  res.json({ success: true, sections: enrichedSections });
});

app.post("/api/erp/academics/sections", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (!orgId) return res.status(403).json({ success: false, message: "Organization required" });
  let { grade, section, classId, name, roomNumber, capacity = 40, classTeacherId, status = "active" } = req.body || {};
  if (!section && name) section = name;
  if (!grade && classId) {
    if (supabase) {
      try {
        const { data: dbC } = await supabase.from("classes").select("name").eq("id", classId).maybeSingle();
        if (dbC) grade = dbC.name;
      } catch (_) {}
    }
    if (!grade && typeof ERP_CLASSES !== "undefined") {
      const c = ERP_CLASSES.find(cl => cl.id === classId || cl.db_id === classId);
      if (c) grade = c.grade || c.name;
    }
  }

  if (!grade || !section) {
    return res.status(400).json({ success: false, message: "Grade and Section name are required" });
  }

  let teacherName = null;
  if (classTeacherId) {
    const staff = ERP_STAFF.find(st => (st.organization_id === orgId) && st.id === classTeacherId);
    if (staff) {
      teacherName = staff.name || `${staff.firstName || ""} ${staff.lastName || ""}`.trim();
    }
  }

  let newSection = null;
  if (supabase && orgId) {
    try {
      const classId = await resolveOrCreateClass(orgId, grade.trim());
      if (classId) {
        const { data: dbSec, error: secErr } = await supabase
          .from("sections")
          .upsert([{
            organization_id: orgId,
            class_id: classId,
            name: section.trim().toUpperCase(),
            room_no: roomNumber ? roomNumber.trim() : null,
            capacity: parseInt(capacity, 10) || 40
          }], { onConflict: "class_id, name" })
          .select("*, classes(name)")
          .maybeSingle();

        if (dbSec) {
          newSection = {
            id: dbSec.id,
            grade: dbSec.classes?.name || grade.trim(),
            section: dbSec.name,
            roomNumber: dbSec.room_no,
            capacity: dbSec.capacity,
            classTeacherId: classTeacherId || null,
            classTeacherName: teacherName,
            status,
            organization_id: orgId
          };
        }
      }
    } catch (e) {
      console.warn("[Section DB Insert Error]:", e.message);
    }
  }

  if (!newSection) {
    newSection = {
      id: `sec-${Date.now()}`,
      grade: grade.trim(),
      section: section.trim().toUpperCase(),
      roomNumber: roomNumber ? roomNumber.trim() : null,
      capacity: parseInt(capacity, 10) || 40,
      classTeacherId: classTeacherId || null,
      classTeacherName: teacherName,
      status,
      organization_id: orgId
    };
  }

  const exIdx = ERP_SECTIONS.findIndex(s => (s.organization_id === orgId) && s.grade.toLowerCase() === grade.trim().toLowerCase() && s.section.toLowerCase() === section.trim().toLowerCase());
  if (exIdx !== -1) ERP_SECTIONS[exIdx] = newSection;
  else ERP_SECTIONS.push(newSection);

  await recordAuditLog("erp.section_created", req.user?.email || "admin", "academic_section", newSection.id, req);
  res.json({ success: true, message: "Section created successfully", section: newSection });
});

