// Database resolution helpers for examination suite
async function resolveOrCreateAcademicSession(orgId, sessionName = "2026-2027") {
  if (!supabase) return null;
  let { data: session } = await supabase
    .from("academic_sessions")
    .select("id")
    .eq("organization_id", orgId)
    .limit(1)
    .maybeSingle();

  if (!session) {
    const { data: newSess, error } = await supabase
      .from("academic_sessions")
      .insert([{
        organization_id: orgId,
        name: sessionName || "2026-2027",
        start_date: "2026-04-01",
        end_date: "2027-03-31",
        is_current: true
      }])
      .select()
      .maybeSingle();
    if (!error && newSess) session = newSess;
  }
  return session?.id || null;
}

async function resolveOrCreateClass(orgId, className = "Class 10") {
  if (!supabase) return null;
  const name = className.trim();
  let { data: cls } = await supabase
    .from("classes")
    .select("id")
    .eq("organization_id", orgId)
    .eq("name", name)
    .maybeSingle();

  if (!cls) {
    const code = name.replace(/\D/g, "") || "10";
    const { data: newCls, error } = await supabase
      .from("classes")
      .insert([{
        organization_id: orgId,
        name,
        code
      }])
      .select()
      .maybeSingle();
    if (!error && newCls) cls = newCls;
  }
  return cls?.id || null;
}

async function resolveOrCreateSection(orgId, classId, sectionName = "A") {
  if (!supabase || !classId) return null;
  const name = (sectionName && sectionName !== "all" ? sectionName : "A").trim().toUpperCase();
  let { data: sec } = await supabase
    .from("sections")
    .select("id")
    .eq("organization_id", orgId)
    .eq("class_id", classId)
    .eq("name", name)
    .maybeSingle();

  if (!sec) {
    const { data: newSec, error } = await supabase
      .from("sections")
      .insert([{
        organization_id: orgId,
        class_id: classId,
        name
      }])
      .select()
      .maybeSingle();
    if (!error && newSec) sec = newSec;
  }
  return sec?.id || null;
}

async function resolveOrCreateSubject(orgId, subjectName, subjectCode) {
  if (!supabase) return null;
  const name = (subjectName || "Subject").trim();
  let { data: sub } = await supabase
    .from("subjects")
    .select("id")
    .eq("organization_id", orgId)
    .eq("name", name)
    .maybeSingle();

  if (!sub) {
    const code = (subjectCode || name.slice(0, 4).toUpperCase()).trim();
    const { data: newSub, error } = await supabase
      .from("subjects")
      .insert([{
        organization_id: orgId,
        name,
        code
      }])
      .select()
      .maybeSingle();
    if (!error && newSub) sub = newSub;
  }
  return sub?.id || null;
}

async function resolveDbStudent(orgId, studentIdentifier) {
  if (!supabase || !studentIdentifier) return null;
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(studentIdentifier);
  if (isUuid) {
    const { data: std } = await supabase
      .from("students")
      .select("id")
      .eq("organization_id", orgId)
      .eq("id", studentIdentifier)
      .maybeSingle();
    if (std) return std.id;
  }

  const { data: stdByAdm } = await supabase
    .from("students")
    .select("id")
    .eq("organization_id", orgId)
    .eq("admission_no", studentIdentifier)
    .maybeSingle();
  if (stdByAdm) return stdByAdm.id;

  return null;
}

// Helper: Authoritative CBSE Result Calculation Engine
function calculateStudentExamResult(examId, studentId, orgId) {
  const exam = ERP_EXAMS.find(e => (e.organization_id === orgId) && (e.id === examId || e.db_id === examId));
  const student = ERP_STUDENTS.find(s => (s.organization_id === orgId) && (s.id === studentId || s.db_id === studentId));
  if (!exam || !student) return null;

  const targetExamId = exam.id;
  const targetDbExamId = exam.db_id;
  const targetStudentId = student.id;
  const targetDbStudentId = student.db_id;

  const examSubjects = ERP_EXAM_SUBJECTS.filter(es =>
    (es.organization_id === orgId) &&
    (es.examId === targetExamId || (targetDbExamId && es.examId === targetDbExamId))
  );
  const studentMarks = ERP_EXAM_MARKS.filter(m =>
    (m.organization_id === orgId) &&
    (m.examId === targetExamId || (targetDbExamId && m.examId === targetDbExamId)) &&
    (m.studentId === targetStudentId || (targetDbStudentId && m.studentId === targetDbStudentId))
  );

  if (studentMarks.length === 0) return null;

  let totalObtained = 0;
  let totalMax = 0;
  let failedSubjectsCount = 0;

  for (const es of examSubjects) {
    const markRec = studentMarks.find(m =>
      m.examSubjectId === es.id ||
      (es.db_id && m.examSubjectId === es.db_id) ||
      m.subjectId === es.subjectId
    );
    totalMax += (Number(es.maxMarks) || 100);

    if (!markRec || markRec.status === "absent" || markRec.status === "not_appeared") {
      failedSubjectsCount++;
    } else if (markRec.status === "exempted") {
      // Exempted: Do not penalize in pass/fail
    } else {
      const score = Number(markRec.marksObtained) || 0;
      totalObtained += score;
      if (score < (Number(es.passMarks) || 33)) {
        failedSubjectsCount++;
      }
    }
  }

  const percentage = totalMax > 0 ? Math.round((totalObtained / totalMax) * 1000) / 10 : 0;

  // CBSE 9-Point Grading
  let overallGrade = "F";
  if (percentage >= 91) overallGrade = "A1";
  else if (percentage >= 81) overallGrade = "A2";
  else if (percentage >= 71) overallGrade = "B1";
  else if (percentage >= 61) overallGrade = "B2";
  else if (percentage >= 51) overallGrade = "C1";
  else if (percentage >= 41) overallGrade = "C2";
  else if (percentage >= 33) overallGrade = "D";
  else overallGrade = "E";

  // Passing logic
  let resultStatus = "PASS";
  if (failedSubjectsCount === 1) resultStatus = "COMPARTMENT";
  else if (failedSubjectsCount >= 2) resultStatus = "FAIL";

  const sessStr = exam.academicSession || "2026-27";
  const grCode = (student.grade || "10").replace(/\D/g, "");
  const secCode = student.section || "A";
  const rollCode = (student.rollNo || "001").replace(/\D/g, "").slice(-3).padStart(3, "0");
  const reportCardNo = `DPHS/${sessStr}/${grCode}${secCode}/${rollCode}`;

  let teacherRemarks = "Good academic progress and regular participation in class.";
  let principalRemarks = "Promoted to next term with regular performance.";
  if (percentage >= 90) {
    teacherRemarks = "Outstanding academic performance and exemplary conduct throughout the term.";
    principalRemarks = "Distinction with honors. Commendable scholastic leadership.";
  } else if (percentage >= 80) {
    teacherRemarks = "Very good conceptual clarity and consistent efforts.";
    principalRemarks = "Good academic trajectory. Keep working for A1 grade.";
  } else if (resultStatus === "FAIL" || resultStatus === "COMPARTMENT") {
    teacherRemarks = "Needs focused revision and remediation in weak subject areas.";
    principalRemarks = "Special tutorial support recommended before re-assessment.";
  }

  const existingResultIndex = ERP_EXAM_RESULTS.findIndex(r =>
    (r.organization_id === orgId) &&
    (r.examId === targetExamId || (targetDbExamId && r.examId === targetDbExamId)) &&
    (r.studentId === targetStudentId || (targetDbStudentId && r.studentId === targetDbStudentId))
  );

  const resultPayload = {
    id: existingResultIndex !== -1 ? ERP_EXAM_RESULTS[existingResultIndex].id : `res-${targetExamId}-${targetStudentId}`,
    examId: targetExamId,
    studentId: targetStudentId,
    studentName: student.name,
    rollNo: student.rollNo || "ROLL",
    admissionNo: student.admissionNo || "ADM",
    grade: student.grade,
    section: student.section,
    academicSession: sessStr,
    totalObtained,
    totalMarksObtained: totalObtained,
    totalMax,
    maxTotalMarks: totalMax,
    percentage,
    overallGrade,
    resultStatus,
    rank: existingResultIndex !== -1 ? (ERP_EXAM_RESULTS[existingResultIndex].classRank || ERP_EXAM_RESULTS[existingResultIndex].rank || 1) : 1,
    classRank: existingResultIndex !== -1 ? (ERP_EXAM_RESULTS[existingResultIndex].classRank || ERP_EXAM_RESULTS[existingResultIndex].rank || 1) : 1,
    sectionRank: existingResultIndex !== -1 ? (ERP_EXAM_RESULTS[existingResultIndex].sectionRank || ERP_EXAM_RESULTS[existingResultIndex].rank || 1) : 1,
    rollNumber: student.rollNo || "ROLL",
    reportCardNo,
    teacherRemarks,
    principalRemarks,
    isPublished: exam.status === "published",
    isLocked: exam.isLocked || exam.status === "locked",
    organization_id: orgId,
    updatedAt: new Date().toISOString()
  };

  if (existingResultIndex !== -1) {
    ERP_EXAM_RESULTS[existingResultIndex] = {
      ...ERP_EXAM_RESULTS[existingResultIndex],
      ...resultPayload
    };
    return ERP_EXAM_RESULTS[existingResultIndex];
  } else {
    ERP_EXAM_RESULTS.push(resultPayload);
    return resultPayload;
  }
}

// Helper: Recalculate 1-based Ranks within Class / Section
function recalculateClassRanks(examId, grade, section, orgId) {
  const exam = ERP_EXAMS.find(e => (e.organization_id === orgId) && (e.id === examId || e.db_id === examId));
  const targetExamId = exam ? exam.id : examId;
  const targetDbExamId = exam ? exam.db_id : null;

  let sectionResults = ERP_EXAM_RESULTS.filter(r =>
    (r.organization_id === orgId) &&
    (r.examId === targetExamId || (targetDbExamId && r.examId === targetDbExamId)) &&
    (!grade || grade === "all" || r.grade.toLowerCase() === grade.toLowerCase()) &&
    (!section || section === "all" || r.section.toLowerCase() === section.toLowerCase())
  );

  sectionResults.sort((a, b) => (Number(b.percentage) || Number(b.totalObtained) || 0) - (Number(a.percentage) || Number(a.totalObtained) || 0));
  sectionResults.forEach((r, idx) => {
    r.rank = idx + 1;
    r.classRank = idx + 1;
    r.sectionRank = idx + 1;
  });
}

// 5a. GET /api/erp/exams/overview - Live Aggregate KPI Summary & Performance Pulse
app.get("/api/erp/exams/overview", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const tenantExams = ERP_EXAMS.filter(e => e.organization_id === orgId);
  const tenantResults = ERP_EXAM_RESULTS.filter(r => r.organization_id === orgId);
  const tenantMarks = ERP_EXAM_MARKS.filter(m => m.organization_id === orgId);

  const totalExams = tenantExams.length;
  const activeExams = tenantExams.filter(e => e.status === "marks_entry" || e.status === "scheduled").length;
  const publishedExams = tenantExams.filter(e => e.status === "published" || e.isPublished).length;
  const lockedExams = tenantExams.filter(e => e.status === "locked" || e.isLocked).length;

  const totalResultsCalculated = tenantResults.length;
  const passedResults = tenantResults.filter(r => r.resultStatus === "PASS").length;
  const overallPassRate = totalResultsCalculated > 0 ? Math.round((passedResults / totalResultsCalculated) * 1000) / 10 : 100;

  const totalPctSum = tenantResults.reduce((acc, r) => acc + (Number(r.percentage) || 0), 0);
  const schoolAveragePct = totalResultsCalculated > 0 ? Math.round((totalPctSum / totalResultsCalculated) * 10) / 10 : 0;

  res.json({
    success: true,
    overview: {
      totalExams,
      activeExams,
      publishedExams,
      lockedExams,
      totalMarksEntries: tenantMarks.length,
      totalResultsCalculated,
      overallPassRate,
      schoolAveragePct,
      activeSession: "2026-27"
    },
    recentExams: tenantExams.map(ex => {
      const subjectsCount = ERP_EXAM_SUBJECTS.filter(s => (s.organization_id === orgId) && s.examId === ex.id).length;
      const marksCount = ERP_EXAM_MARKS.filter(m => (m.organization_id === orgId) && m.examId === ex.id).length;
      return {
        ...ex,
        subjectsCount,
        marksCount
      };
    })
  });
});

// 5b. GET /api/erp/exams - Filterable Exam Directory (PostgreSQL Backed)
app.get("/api/erp/exams", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { session, grade, status, term, search } = req.query;

  let exams = [];
  if (supabase && orgId) {
    try {
      const { data: dbExams } = await supabase
        .from("exams")
        .select("*")
        .eq("organization_id", orgId)
        .order("created_at", { ascending: false });

      if (dbExams && dbExams.length > 0) {
        exams = dbExams.map(e => ({
          id: e.id,
          title: e.name,
          name: e.name,
          examType: e.exam_type || "Periodic Test",
          academicSession: "2026-27",
          grade: "all",
          section: "all",
          startDate: e.start_date || new Date().toISOString().split("T")[0],
          endDate: e.end_date || new Date().toISOString().split("T")[0],
          status: "scheduled",
          isLocked: false,
          organization_id: e.organization_id
        }));
      }
    } catch (e) {
      console.warn("[Exams DB Fetch Error]:", e.message);
    }
  }

  if (exams.length === 0 && orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e") {
    exams = ERP_EXAMS.filter(e => e.organization_id === orgId);
  } else if (exams.length === 0) {
    exams = ERP_EXAMS.filter(e => e.organization_id === orgId);
  }

  if (session && session !== "all") {
    exams = exams.filter(e => !e.academicSession || e.academicSession === session);
  }
  if (grade && grade !== "all") {
    exams = exams.filter(e => (e.grade || "").toLowerCase() === grade.toLowerCase());
  }
  if (status && status !== "all") {
    exams = exams.filter(e => (e.status || "").toLowerCase() === status.toLowerCase());
  }
  if (term && term !== "all") {
    exams = exams.filter(e => (e.examType || e.term || "").toLowerCase().includes(term.toLowerCase()));
  }
  if (search) {
    const q = search.trim().toLowerCase();
    exams = exams.filter(e => (e.title || "").toLowerCase().includes(q) || (e.examType && e.examType.toLowerCase().includes(q)));
  }

  const enriched = exams.map(ex => {
    const subjects = ERP_EXAM_SUBJECTS.filter(s => (s.organization_id === orgId) && s.examId === ex.id);
    const marks = ERP_EXAM_MARKS.filter(m => (m.organization_id === orgId) && m.examId === ex.id);
    const results = ERP_EXAM_RESULTS.filter(r => (r.organization_id === orgId) && r.examId === ex.id);
    return {
      ...ex,
      subjectsCount: subjects.length,
      marksEnteredCount: marks.length,
      resultsCount: results.length
    };
  });

  res.json({ success: true, exams: enriched });
});

// 5c. POST /api/erp/exams - Create Examination
app.post("/api/erp/exams", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const {
    title,
    name,
    examType = "Periodic Test",
    academicSession = "2026-27",
    grade = "all",
    section = "all",
    startDate,
    endDate,
    status = "scheduled"
  } = req.body;
  const effectiveTitle = (title || name || "").trim();
  const effectiveGrade = (grade || "all").trim();

  if (!effectiveTitle || !startDate || !endDate) {
    return res.status(400).json({ success: false, message: "Exam title, start date, and end date are required" });
  }

  if (startDate > endDate) {
    return res.status(400).json({
      success: false,
      code: "INVALID_EXAM_DATES",
      message: `Start date (${startDate}) cannot be after end date (${endDate})`
    });
  }

  const isSeed = orgId === "b17780e5-3832-4ac6-9aeb-33fd80c5cb0e";
  const duplicate = ERP_EXAMS.find(e =>
    (e.organization_id ? e.organization_id === orgId : isSeed) &&
    e.title.toLowerCase() === effectiveTitle.toLowerCase() &&
    e.grade.toLowerCase() === effectiveGrade.toLowerCase() &&
    (!e.academicSession || e.academicSession === academicSession)
  );
  if (duplicate) {
    return res.status(400).json({ success: false, message: `Exam '${effectiveTitle}' for ${effectiveGrade} already exists in this session` });
  }

  const newExam = {
    id: `ex-${Date.now()}`,
    title: effectiveTitle,
    examType,
    academicSession,
    grade: effectiveGrade,
    section: section || "all",
    startDate,
    endDate,
    status,
    isLocked: false,
    publishedAt: null,
    lockedAt: null,
    organization_id: orgId,
    createdAt: new Date().toISOString()
  };

  ERP_EXAMS.unshift(newExam);
  await recordAuditLog("erp.exam_created", req.user?.email || "admin", "exam", newExam.id, req);

  // Persist to Supabase PostgreSQL exams table
  if (supabase) {
    try {
      const sessId = await resolveOrCreateAcademicSession(orgId, academicSession);
      if (sessId) {
        const { data: dbExam, error: dbErr } = await supabase.from("exams").insert([{
          organization_id: orgId,
          academic_session_id: sessId,
          name: newExam.title,
          exam_type: newExam.examType,
          start_date: newExam.startDate,
          end_date: newExam.endDate
        }]).select().maybeSingle();

        if (dbExam) {
          newExam.db_id = dbExam.id;
          console.log(`[DB] Exam '${newExam.title}' persisted to Supabase (UUID: ${dbExam.id}) ✅`);
        } else if (dbErr) {
          console.warn("[DB] Exam insert error:", dbErr.message);
        }
      }
    } catch (dbEx) {
      console.warn("[DB] Exam persistence exception:", dbEx.message);
    }
  }

  res.json({ success: true, message: "Exam created successfully", exam: newExam });
});

