// Database resolution helpers for fees & finance suite
async function resolveOrCreateFeeStructure(orgId, structData) {
  if (!supabase) return null;
  const name = (structData.name || structData.feeHead || "Tuition Fee").trim();
  const amount = Number(structData.amount ?? structData.amountINR ?? 0);
  
  let frequency = (structData.frequency || "quarterly").toLowerCase().replace(/-/g, "_");
  if (frequency === "annual" || frequency === "yearly") frequency = "annually";
  if (!["one_time", "monthly", "quarterly", "annually"].includes(frequency)) {
    frequency = "quarterly";
  }

  let { data: existing } = await supabase
    .from("fee_structures")
    .select("*")
    .eq("organization_id", orgId)
    .eq("name", name)
    .eq("amount", amount)
    .maybeSingle();

  if (existing) return existing;

  const academicSessionId = await resolveOrCreateAcademicSession(orgId, structData.academicSession || structData.session || "2026-2027");

  const { data: newStruct, error } = await supabase
    .from("fee_structures")
    .insert([{
      organization_id: orgId,
      academic_session_id: academicSessionId,
      name,
      amount,
      frequency,
      due_date: structData.dueDate || new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10)
    }])
    .select()
    .maybeSingle();

  if (error) {
    console.error("[Fees DB] Failed to create fee structure:", error.message);
    return null;
  }
  return newStruct;
}

async function resolveOrCreateStudentFee(orgId, demandData) {
  if (!supabase) return null;
  let studentId = await resolveDbStudent(orgId, demandData.studentId) || null;

  if (!studentId && demandData.admissionNo) {
    const { data: stdByAdm } = await supabase
      .from("students")
      .select("id")
      .eq("organization_id", orgId)
      .eq("admission_no", demandData.admissionNo)
      .maybeSingle();
    if (stdByAdm) studentId = stdByAdm.id;
  }

  if (!studentId && demandData.studentName) {
    const parts = demandData.studentName.trim().split(/\s+/);
    const firstName = parts[0];
    const lastName = parts.slice(1).join(" ") || "";
    let q = supabase.from("students").select("id").eq("organization_id", orgId).ilike("first_name", firstName);
    if (lastName) q = q.ilike("last_name", lastName);
    const { data: stdByName } = await q.maybeSingle();
    if (stdByName) studentId = stdByName.id;
  }

  if (!studentId) {
    const parts = (demandData.studentName || "Student").trim().split(/\s+/);
    const firstName = parts[0] || "Student";
    const lastName = parts.slice(1).join(" ") || "Student";
    const { data: newStd, error: stdErr } = await supabase
      .from("students")
      .insert([{
        organization_id: orgId,
        first_name: firstName,
        last_name: lastName,
        admission_no: demandData.admissionNo || `ADM-${Date.now().toString().slice(-6)}`,
        admission_status: "admitted"
      }])
      .select()
      .maybeSingle();
    if (!stdErr && newStd) studentId = newStd.id;
  }

  if (!studentId) return null;

  let feeStructureId = demandData.feeStructureDbId || demandData.feeStructureId;
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(feeStructureId);
  if (!isUuid) {
    const fs = ERP_FEE_STRUCTURES.find(s => s.id === feeStructureId);
    if (fs && fs.db_id) {
      feeStructureId = fs.db_id;
    } else {
      const dbFs = await resolveOrCreateFeeStructure(orgId, {
        name: demandData.feeHead || "Tuition Fee",
        amount: demandData.baseAmount || demandData.netAmount || 5000,
        academicSession: demandData.academicSession
      });
      if (dbFs) feeStructureId = dbFs.id;
    }
  }

  let status = (demandData.status || "pending").toLowerCase();
  if (status === "partially_paid") status = "partial";
  if (status === "overdue") status = "pending";
  if (!["pending", "partial", "paid", "cancelled", "refunded"].includes(status)) {
    status = "pending";
  }

  let query = supabase.from("student_fees").select("*").eq("organization_id", orgId);
  if (demandData.db_id) {
    query = query.eq("id", demandData.db_id);
  } else if (studentId && feeStructureId) {
    query = query.eq("student_id", studentId).eq("fee_structure_id", feeStructureId);
  }

  const { data: existing } = await query.maybeSingle();
  if (existing) {
    const { data: updated } = await supabase
      .from("student_fees")
      .update({
        amount_due: Number(demandData.netAmount ?? demandData.amount_due ?? existing.amount_due),
        discount: Number(demandData.discountAmount ?? demandData.discount ?? existing.discount),
        amount_paid: Number(demandData.paidAmount ?? demandData.amount_paid ?? existing.amount_paid),
        status,
        due_date: demandData.dueDate || existing.due_date,
        updated_at: new Date().toISOString()
      })
      .eq("id", existing.id)
      .select()
      .maybeSingle();
    return updated || existing;
  }

  const { data: newFee, error } = await supabase
    .from("student_fees")
    .insert([{
      organization_id: orgId,
      student_id: studentId,
      fee_structure_id: feeStructureId,
      amount_due: Number(demandData.netAmount || demandData.amount_due || 0),
      discount: Number(demandData.discountAmount || demandData.discount || 0),
      amount_paid: Number(demandData.paidAmount || demandData.amount_paid || 0),
      status,
      due_date: demandData.dueDate || new Date(Date.now() + 15 * 86400000).toISOString().slice(0, 10)
    }])
    .select()
    .maybeSingle();

  if (error) {
    console.error("[Fees DB] Failed to create student fee:", error.message);
    return null;
  }
  return newFee;
}

// Generate sequential FY receipt numbering: REC/2026-27/0001 (immutable & strictly sequential)
async function generateNextReceiptNo(orgId) {
  const today = new Date();
  const curYear = today.getFullYear();
  const curMonth = today.getMonth() + 1;
  const fy = curMonth >= 4 ? `${curYear}-${String(curYear + 1).slice(-2)}` : `${curYear - 1}-${String(curYear).slice(-2)}`;
  let count = 0;
  if (supabase) {
    try {
      const { count: dbCount } = await supabase
        .from("fee_payments")
        .select("id", { count: "exact", head: true })
        .eq("organization_id", orgId);
      if (typeof dbCount === "number") count = dbCount;
    } catch (_) {}
  }
  if (!count && typeof ERP_FEE_PAYMENTS !== "undefined") {
    count = ERP_FEE_PAYMENTS.filter(p => p.organization_id === orgId).length;
  }
  const seq = String(count + 1).padStart(4, "0");
  return `REC/${fy}/${seq}`;
}

async function recordDbFeePayment(orgId, paymentData) {
  if (!supabase) return null;
  let paymentMethod = (paymentData.paymentMode || paymentData.paymentMethod || "cash").toLowerCase();
  if (paymentMethod === "netbanking" || paymentMethod === "neft" || paymentMethod === "rtgs") paymentMethod = "bank_transfer";
  if (paymentMethod === "online_gateway") paymentMethod = "upi";
  if (!["cash", "upi", "bank_transfer", "card", "cheque"].includes(paymentMethod)) {
    paymentMethod = "cash";
  }

  let studentFeeId = paymentData.studentFeeId || paymentData.student_fee_id;
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(studentFeeId);
  if (!isUuid && paymentData.demand) {
    const dbFee = await resolveOrCreateStudentFee(orgId, paymentData.demand);
    if (dbFee) studentFeeId = dbFee.id;
  }

  if (!studentFeeId) {
    console.error("[Fees DB] No valid student_fee_id for payment recording");
    return null;
  }

  let receiptNo = paymentData.receiptNo || paymentData.receipt_no;
  if (!receiptNo) {
    receiptNo = await generateNextReceiptNo(orgId);
  }

  const isCollectedByUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(paymentData.collectedBy);

  const { data: newPayment, error } = await supabase
    .from("fee_payments")
    .insert([{
      organization_id: orgId,
      student_fee_id: studentFeeId,
      receipt_no: receiptNo,
      amount: Number(paymentData.amountPaid ?? paymentData.amount ?? 0),
      payment_method: paymentMethod,
      transaction_ref: paymentData.referenceNumber || paymentData.transaction_ref || null,
      collected_by: isCollectedByUuid ? paymentData.collectedBy : null,
      paid_at: paymentData.paid_at || new Date().toISOString()
    }])
    .select()
    .maybeSingle();

  if (error) {
    console.error("[Fees DB] Failed to record fee payment:", error.message);
    return null;
  }

  const { data: sf } = await supabase
    .from("student_fees")
    .select("amount_due, amount_paid")
    .eq("id", studentFeeId)
    .maybeSingle();

  if (sf) {
    const newPaid = Number(sf.amount_paid || 0) + Number(paymentData.amountPaid ?? paymentData.amount ?? 0);
    const newStatus = newPaid >= Number(sf.amount_due) ? "paid" : (newPaid > 0 ? "partial" : "pending");
    await supabase
      .from("student_fees")
      .update({
        amount_paid: newPaid,
        status: newStatus,
        updated_at: new Date().toISOString()
      })
      .eq("id", studentFeeId);
  }

  return newPayment;
}

async function reverseDbFeePayment(orgId, receiptNoOrId) {
  if (!supabase) return null;
  const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(receiptNoOrId);
  let query = supabase.from("fee_payments").select("*").eq("organization_id", orgId);
  if (isUuid) {
    query = query.eq("id", receiptNoOrId);
  } else {
    query = query.eq("receipt_no", receiptNoOrId);
  }
  const { data: payment } = await query.maybeSingle();
  if (!payment) return null;

  if (payment.student_fee_id) {
    const { data: sf } = await supabase
      .from("student_fees")
      .select("amount_due, amount_paid")
      .eq("id", payment.student_fee_id)
      .maybeSingle();

    if (sf) {
      const restoredPaid = Math.max(0, Number(sf.amount_paid || 0) - Number(payment.amount || 0));
      const restoredStatus = restoredPaid >= Number(sf.amount_due) ? "paid" : (restoredPaid > 0 ? "partial" : "pending");
      await supabase
        .from("student_fees")
        .update({
          amount_paid: restoredPaid,
          status: restoredStatus,
          updated_at: new Date().toISOString()
        })
        .eq("id", payment.student_fee_id);
    }
  }

  await supabase
    .from("fee_payments")
    .delete()
    .eq("id", payment.id);

  return payment;
}

function numberToWordsINR(num) {
  const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  
  function inWords(n) {
    if ((n = n.toString()).length > 9) return 'Overflow';
    const n_arr = ('000000000' + n).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
    if (!n_arr) return '';
    let str = '';
    str += (Number(n_arr[1]) !== 0) ? (a[Number(n_arr[1])] || b[n_arr[1][0]] + ' ' + a[n_arr[1][1]]) + 'Crore ' : '';
    str += (Number(n_arr[2]) !== 0) ? (a[Number(n_arr[2])] || b[n_arr[2][0]] + ' ' + a[n_arr[2][1]]) + 'Lakh ' : '';
    str += (Number(n_arr[3]) !== 0) ? (a[Number(n_arr[3])] || b[n_arr[3][0]] + ' ' + a[n_arr[3][1]]) + 'Thousand ' : '';
    str += (Number(n_arr[4]) !== 0) ? (a[Number(n_arr[4])] || b[n_arr[4][0]] + ' ' + a[n_arr[4][1]]) + 'Hundred ' : '';
    str += (Number(n_arr[5]) !== 0) ? ((str !== '') ? 'and ' : '') + (a[Number(n_arr[5])] || b[n_arr[5][0]] + ' ' + a[n_arr[5][1]]) : '';
    return str.trim();
  }
  const integerPart = Math.floor(Number(num) || 0);
  const words = inWords(integerPart);
  return words ? words + ' Rupees Only' : 'Zero Rupees';
}

// 6a. GET /api/erp/fees/overview - Real database financial metrics
app.get("/api/erp/fees/overview", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const orgDemands = ERP_FEE_DEMANDS.filter(d => d.organization_id === orgId);
  const orgPayments = ERP_FEE_PAYMENTS.filter(p => p.organization_id === orgId);
  const today = new Date().toISOString().slice(0, 10);

  const totalInvoiced = orgDemands.reduce((sum, d) => sum + (Number(d.netAmount) || 0), 0);
  const totalCollected = orgPayments
    .filter(p => p.status === "completed")
    .reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0);
  const totalOutstanding = orgDemands.reduce((sum, d) => sum + (Number(d.balanceAmount) || 0), 0);
  const totalOverdue = orgDemands
    .filter(d => d.status === "overdue" || (Number(d.balanceAmount) > 0 && d.dueDate < today))
    .reduce((sum, d) => sum + (Number(d.balanceAmount) || 0), 0);
  const todayCollected = orgPayments
    .filter(p => p.status === "completed" && p.paymentDate === today)
    .reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0);

  const paidCount = orgDemands.filter(d => d.status === "paid" || Number(d.balanceAmount) <= 0).length;
  const partiallyPaidCount = orgDemands.filter(d => d.status === "partially_paid" || d.status === "partial" || (Number(d.paidAmount) > 0 && Number(d.balanceAmount) > 0)).length;
  const pendingCount = orgDemands.filter(d => d.status === "pending" && Number(d.paidAmount) === 0 && d.dueDate >= today).length;
  const overdueCount = orgDemands.filter(d => d.status === "overdue" || (Number(d.balanceAmount) > 0 && d.dueDate < today)).length;
  const collectionRatePercentage = totalInvoiced > 0 ? Math.round((totalCollected / totalInvoiced) * 1000) / 10 : 0;

  const modeBreakdown = {
    cash: orgPayments.filter(p => p.status === "completed" && p.paymentMode === "cash").reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0),
    upi: orgPayments.filter(p => p.status === "completed" && p.paymentMode === "upi").reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0),
    bank_transfer: orgPayments.filter(p => p.status === "completed" && (p.paymentMode === "bank_transfer" || p.paymentMode === "netbanking")).reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0),
    cheque: orgPayments.filter(p => p.status === "completed" && p.paymentMode === "cheque").reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0),
    card: orgPayments.filter(p => p.status === "completed" && p.paymentMode === "card").reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0)
  };

  const recentPayments = orgPayments
    .filter(p => p.status === "completed")
    .slice(0, 5);

  res.json({
    success: true,
    overview: {
      totalInvoiced,
      totalCollected,
      totalOutstanding,
      totalOverdue,
      todayCollected,
      totalDemandsCount: orgDemands.length,
      paidCount,
      partiallyPaidCount,
      pendingCount,
      overdueCount,
      collectionRatePercentage,
      modeBreakdown,
      recentPayments
    }
  });
});

// 6b. GET /api/erp/fees/structures - List Fee Heads & Structure
app.get("/api/erp/fees/structures", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { session, grade, status } = req.query;

  let structures = [];
  if (supabase && orgId) {
    try {
      const { data, error } = await supabase
        .from("fee_structures")
        .select("*")
        .eq("organization_id", orgId);
      if (!error && Array.isArray(data) && data.length > 0) {
        structures = data.map(fs => ({
          id: fs.id,
          db_id: fs.id,
          academicSession: "2026-27",
          grade: "all",
          feeHead: fs.name,
          amountINR: Number(fs.amount) || 0,
          frequency: fs.frequency || "quarterly",
          dueDay: 10,
          isMandatory: true,
          status: "active",
          organization_id: fs.organization_id,
          created_at: fs.created_at
        }));
      }
    } catch (_) {}
  }

  if (structures.length === 0) {
    structures = ERP_FEE_STRUCTURES.filter(s => s.organization_id === orgId);
  }

  if (session) structures = structures.filter(s => s.academicSession === session);
  if (grade && grade !== "all") structures = structures.filter(s => (s.grade || "all").toLowerCase() === grade.toLowerCase() || s.grade === "all");
  if (status) structures = structures.filter(s => s.status === status);

  res.json({ success: true, structures, count: structures.length });
});

// 6c. POST /api/erp/fees/structures - Create Fee Head / Structure with DB Persistence
app.post("/api/erp/fees/structures", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { academicSession, grade, feeHead, amountINR, frequency, dueDay, isMandatory } = req.body;

  if (!grade || !feeHead || amountINR === undefined || amountINR === null) {
    return res.status(400).json({ success: false, message: "grade, feeHead, and amountINR are required" });
  }

  const numAmount = Number(amountINR);
  if (isNaN(numAmount) || numAmount <= 0) {
    return res.status(400).json({ success: false, message: "amountINR must be a positive number" });
  }

  const newStructure = {
    id: `struct-${Date.now()}`,
    academicSession: academicSession || "2026-27",
    grade,
    feeHead,
    amountINR: numAmount,
    frequency: frequency || "quarterly",
    dueDay: Number(dueDay) || 10,
    isMandatory: isMandatory !== undefined ? Boolean(isMandatory) : true,
    status: "active",
    organization_id: orgId,
    created_at: new Date().toISOString()
  };

  // Persist to PostgreSQL fee_structures
  const dbStruct = await resolveOrCreateFeeStructure(orgId, {
    name: feeHead,
    amount: numAmount,
    frequency: newStructure.frequency,
    academicSession: newStructure.academicSession
  });
  if (dbStruct) {
    newStructure.db_id = dbStruct.id;
  }

  ERP_FEE_STRUCTURES.unshift(newStructure);
  await recordAuditLog("erp.fee_structure_created", req.user?.email || "admin", "fee_structure", newStructure.id, req);

  res.json({ success: true, message: "Fee structure created successfully", structure: newStructure });
});

// 6d. PATCH /api/erp/fees/structures/:id - Update Fee Head
app.patch("/api/erp/fees/structures/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const struct = ERP_FEE_STRUCTURES.find(s => (s.organization_id === orgId) && (s.id === id || s.db_id === id));

  if (!struct) {
    return res.status(404).json({ success: false, message: "Fee structure not found" });
  }

  const { feeHead, amountINR, frequency, dueDay, isMandatory, status } = req.body;
  if (feeHead !== undefined) struct.feeHead = feeHead;
  if (amountINR !== undefined) struct.amountINR = Number(amountINR);
  if (frequency !== undefined) struct.frequency = frequency;
  if (dueDay !== undefined) struct.dueDay = Number(dueDay);
  if (isMandatory !== undefined) struct.isMandatory = Boolean(isMandatory);
  if (status !== undefined) struct.status = status;

  if (supabase && struct.db_id) {
    let freq = (struct.frequency || "quarterly").toLowerCase().replace(/-/g, "_");
    if (freq === "annual" || freq === "yearly") freq = "annually";
    if (!["one_time", "monthly", "quarterly", "annually"].includes(freq)) freq = "quarterly";

    await supabase
      .from("fee_structures")
      .update({
        name: struct.feeHead,
        amount: struct.amountINR,
        frequency: freq,
        updated_at: new Date().toISOString()
      })
      .eq("id", struct.db_id);
  }

  await recordAuditLog("erp.fee_structure_updated", req.user?.email || "admin", "fee_structure", struct.id, req);

  res.json({ success: true, message: "Fee structure updated successfully", structure: struct });
});

// 6e. DELETE /api/erp/fees/structures/:id - Deactivate Fee Head
app.delete("/api/erp/fees/structures/:id", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const struct = ERP_FEE_STRUCTURES.find(s => (s.organization_id === orgId) && (s.id === id || s.db_id === id));

  if (!struct) {
    return res.status(404).json({ success: false, message: "Fee structure not found" });
  }

  struct.status = "inactive";

  if (supabase && struct.db_id) {
    await supabase
      .from("fee_structures")
      .delete()
      .eq("id", struct.db_id);
  }

  await recordAuditLog("erp.fee_structure_deactivated", req.user?.email || "admin", "fee_structure", struct.id, req);

  res.json({ success: true, message: "Fee structure deactivated successfully" });
});

// 6f. GET /api/erp/fees/demands - List Demands / Invoices
app.get("/api/erp/fees/demands", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { session, grade, section, status, search } = req.query;
  const today = new Date().toISOString().slice(0, 10);

  let demands = ERP_FEE_DEMANDS.filter(d => d.organization_id === orgId);

  if (session) demands = demands.filter(d => d.academicSession === session);
  if (grade && grade !== "all") demands = demands.filter(d => d.grade.toLowerCase() === grade.toLowerCase());
  if (section && section !== "all") demands = demands.filter(d => d.section.toLowerCase() === section.toLowerCase());
  if (status && status !== "all") {
    if (status === "overdue") {
      demands = demands.filter(d => d.status === "overdue" || (Number(d.balanceAmount) > 0 && d.dueDate < today));
    } else {
      demands = demands.filter(d => d.status === status);
    }
  }
  if (search) {
    const q = search.toLowerCase();
    demands = demands.filter(d =>
      (d.studentName && d.studentName.toLowerCase().includes(q)) ||
      (d.invoiceNo && d.invoiceNo.toLowerCase().includes(q)) ||
      (d.admissionNo && d.admissionNo.toLowerCase().includes(q))
    );
  }

  res.json({ success: true, demands, count: demands.length });
});

// 6g. POST /api/erp/fees/demands/generate - Batch Generate Demands with DB Persistence
app.post("/api/erp/fees/demands/generate", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { session, grade, section, feeStructureId, dueDate } = req.body;

  if (!grade || !feeStructureId) {
    return res.status(400).json({ success: false, message: "grade and feeStructureId are required" });
  }

  const struct = ERP_FEE_STRUCTURES.find(s => (s.organization_id === orgId) && (s.id === feeStructureId || s.db_id === feeStructureId));
  if (!struct) {
    return res.status(404).json({ success: false, message: "Fee structure not found" });
  }

  let students = ERP_STUDENTS.filter(s => (s.organization_id === orgId) && s.grade.toLowerCase() === grade.toLowerCase());
  if (section && section !== "all") {
    students = students.filter(s => s.section.toLowerCase() === section.toLowerCase());
  }

  if (students.length === 0) {
    return res.status(404).json({ success: false, message: `No students found in ${grade} ${section || ''}` });
  }

  const currentSession = session || struct.academicSession || "2026-27";
  const demandDueDate = dueDate || new Date(Date.now() + 15 * 86400000).toISOString().slice(0, 10);
  const generatedDemands = [];

  for (const st of students) {
    const existing = ERP_FEE_DEMANDS.find(d =>
      d.studentId === st.id &&
      (d.feeStructureId === struct.id || (struct.db_id && d.feeStructureId === struct.db_id)) &&
      d.academicSession === currentSession
    );
    if (existing) continue;

    const concession = ERP_FEE_CONCESSIONS.find(c => c.studentId === st.id && c.academicSession === currentSession);
    let discountAmount = 0;
    let concessionReason = null;
    if (concession) {
      concessionReason = concession.reason || concession.concessionType;
      if (concession.discountPercentage > 0) {
        discountAmount = Math.round((struct.amountINR * (concession.discountPercentage / 100)) * 100) / 100;
      } else if (concession.discountAmountINR > 0) {
        discountAmount = Math.min(struct.amountINR, concession.discountAmountINR);
      }
    } else {
      // Automatic Indian Sibling Discount check (15% concession for sibling)
      const allStudentsList = typeof ERP_STUDENTS !== "undefined" ? ERP_STUDENTS : students;
      const hasSibling = allStudentsList.some(other =>
        other.id !== st.id && other.organization_id === orgId &&
        ((other.parentPhone && other.parentPhone === st.parentPhone) ||
         (other.parentEmail && other.parentEmail === st.parentEmail) ||
         (other.fatherPhone && other.fatherPhone === st.fatherPhone) ||
         (other.fatherName && other.fatherName === st.fatherName && other.fatherName.length > 2))
      );
      if (hasSibling) {
        concessionReason = "Sibling Concession (15%)";
        discountAmount = Math.round((struct.amountINR * 0.15) * 100) / 100;
      }
    }

    const netAmount = Math.max(0, struct.amountINR - discountAmount);
    const invoiceNo = `FEES-${currentSession.replace(/[^0-9]/g, '').slice(0, 4)}-Q${Math.floor(Math.random() * 4) + 1}-${Math.floor(1000 + Math.random() * 9000)}`;

    const newDemand = {
      id: `inv-${Date.now()}-${Math.floor(100 + Math.random() * 900)}`,
      invoiceNo,
      studentId: st.id,
      studentName: st.name,
      admissionNo: st.admissionNo || "DPS-2026-0000",
      grade: st.grade,
      section: st.section || "A",
      academicSession: currentSession,
      feeStructureId: struct.id,
      feeStructureDbId: struct.db_id,
      feeHead: struct.feeHead,
      feeType: struct.feeHead,
      baseAmount: struct.amountINR,
      discountAmount,
      fineAmount: 0,
      netAmount,
      paidAmount: 0,
      balanceAmount: netAmount,
      dueDate: demandDueDate,
      status: "pending",
      amountINR: netAmount,
      organization_id: orgId,
      created_at: new Date().toISOString()
    };

    // DB Persistence
    const dbFee = await resolveOrCreateStudentFee(orgId, newDemand);
    if (dbFee) {
      newDemand.db_id = dbFee.id;
    }

    ERP_FEE_DEMANDS.unshift(newDemand);
    generatedDemands.push(newDemand);
  }

  await recordAuditLog("erp.fee_demands_generated", req.user?.email || "admin", "fee_batch", `${generatedDemands.length}_demands`, req);

  res.json({
    success: true,
    message: `Generated ${generatedDemands.length} fee demands for ${grade}`,
    count: generatedDemands.length,
    demands: generatedDemands
  });
});

// 6h. GET /api/erp/fees/students/:studentId/account - Student Fee Ledger & Balance
app.get("/api/erp/fees/students/:studentId/account", (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { studentId } = req.params;

  const student = ERP_STUDENTS.find(s => (s.organization_id === orgId) && (s.id === studentId || s.db_id === studentId || s.admissionNo === studentId));
  if (!student) {
    return res.status(404).json({ success: false, message: "Student record not found" });
  }

  const demands = ERP_FEE_DEMANDS.filter(d => (d.organization_id === orgId) && (d.studentId === student.id || (student.db_id && d.studentId === student.db_id) || d.studentName === student.name));
  const payments = ERP_FEE_PAYMENTS.filter(p => (p.organization_id === orgId) && (p.studentId === student.id || (student.db_id && p.studentId === student.db_id) || p.studentName === student.name));
  const concessions = ERP_FEE_CONCESSIONS.filter(c => (c.organization_id === orgId) && (c.studentId === student.id || (student.db_id && c.studentId === student.db_id) || c.studentName === student.name));

  const totalInvoiced = demands.reduce((sum, d) => sum + (Number(d.netAmount) || 0), 0);
  const totalPaid = payments.filter(p => p.status === "completed").reduce((sum, p) => sum + (Number(p.amountPaid) || 0), 0);
  const currentBalance = demands.reduce((sum, d) => sum + (Number(d.balanceAmount) || 0), 0);
  const today = new Date().toISOString().slice(0, 10);
  const overdueBalance = demands
    .filter(d => d.status === "overdue" || (Number(d.balanceAmount) > 0 && d.dueDate < today))
    .reduce((sum, d) => sum + (Number(d.balanceAmount) || 0), 0);

  res.json({
    success: true,
    student,
    demands,
    payments,
    concessions,
    summary: {
      totalInvoiced,
      totalPaid,
      currentBalance,
      overdueBalance
    }
  });
});

// 6i. POST /api/erp/fees/collect - Cashier Payment Terminal with DB Persistence
app.post("/api/erp/fees/collect", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  let { demandId, studentId, amountPaid, paymentMode, referenceNumber, collectedBy, remarks } = req.body || {};

  if (!demandId && studentId) {
    const foundDemand = ERP_FEE_DEMANDS.find(d => (d.organization_id === orgId) && (d.studentId === studentId || d.admissionNo === studentId));
    if (foundDemand) demandId = foundDemand.id;
  }

  let demand = ERP_FEE_DEMANDS.find(d => (d.organization_id === orgId) && (d.id === demandId || d.db_id === demandId));
  if (!demand && supabase && (demandId || studentId)) {
    try {
      let q = supabase.from("student_fees").select("*, fee_structures(*), students(*)").eq("organization_id", orgId);
      if (demandId) q = q.eq("id", demandId);
      else if (studentId) q = q.eq("student_id", studentId);
      const { data: dbFee } = await q.limit(1).maybeSingle();
      if (dbFee) {
        demand = {
          id: dbFee.id,
          db_id: dbFee.id,
          organization_id: orgId,
          studentId: dbFee.student_id,
          studentName: [dbFee.students?.first_name, dbFee.students?.last_name].filter(Boolean).join(" ") || "Student",
          admissionNo: dbFee.students?.admission_no || "ADM-001",
          grade: dbFee.students?.grade || "Class 9",
          section: dbFee.students?.section || "A",
          feeHead: dbFee.fee_structures?.name || "Tuition Fee",
          netAmount: Number(dbFee.amount_due || 0),
          paidAmount: Number(dbFee.amount_paid || 0),
          balanceAmount: Math.max(0, Number(dbFee.amount_due || 0) - Number(dbFee.amount_paid || 0)),
          invoiceNo: `INV-${dbFee.id.slice(0, 8)}`
        };
        demandId = demand.id;
        ERP_FEE_DEMANDS.unshift(demand);
      }
    } catch (_) {}
  }

  if (!demand || amountPaid === undefined || amountPaid === null) {
    return res.status(400).json({ success: false, message: "Valid demandId (or studentId) and amountPaid are required" });
  }

  const numPaid = Number(amountPaid);
  if (isNaN(numPaid) || numPaid <= 0) {
    return res.status(400).json({ success: false, message: "amountPaid must be a positive number" });
  }

  if (numPaid > Number(demand.balanceAmount) + 0.01) {
    return res.status(400).json({
      success: false,
      message: `amountPaid (₹${numPaid}) exceeds outstanding balance (₹${demand.balanceAmount})`
    });
  }

  const validModes = ["cash", "upi", "bank_transfer", "cheque", "card"];
  const mode = (paymentMode || "cash").toLowerCase();
  if (!validModes.includes(mode)) {
    return res.status(400).json({ success: false, message: `Invalid paymentMode. Expected one of: ${validModes.join(", ")}` });
  }

  const cleanGrade = (demand.grade || "10").replace(/\D/g, "") || "10";
  const cleanSec = demand.section || "A";
  const receiptNo = req.body.receiptNo || await generateNextReceiptNo(orgId);

  demand.paidAmount = Math.round((Number(demand.paidAmount) + numPaid) * 100) / 100;
  demand.balanceAmount = Math.max(0, Math.round((Number(demand.netAmount) - demand.paidAmount) * 100) / 100);
  demand.status = demand.balanceAmount <= 0 ? "paid" : "partially_paid";
  demand.paidAt = new Date().toISOString().slice(0, 10);
  demand.paymentMethod = mode.toUpperCase();
  demand.receiptNo = receiptNo;
  demand.amountINR = demand.netAmount;

  const newPayment = {
    id: `pay-${Date.now()}`,
    receiptNo,
    demandId: demand.id,
    invoiceNo: demand.invoiceNo,
    studentId: demand.studentId,
    studentName: demand.studentName,
    admissionNo: demand.admissionNo || "DPS-2026-0000",
    grade: demand.grade,
    section: demand.section,
    feeHead: demand.feeHead,
    amountPaid: numPaid,
    paymentDate: new Date().toISOString().slice(0, 10),
    paymentMode: mode,
    referenceNumber: referenceNumber || (mode === "cash" ? `CSH-${Date.now().toString().slice(-6)}` : `TXN-${Date.now().toString().slice(-8)}`),
    collectedBy: collectedBy || "Front Desk Cashier",
    remarks: remarks || "",
    status: "completed",
    organization_id: orgId,
    created_at: new Date().toISOString()
  };

  // DB Persistence
  const dbPayment = await recordDbFeePayment(orgId, {
    ...newPayment,
    studentFeeId: demand.db_id,
    demand
  });
  if (dbPayment) {
    newPayment.db_id = dbPayment.id;
  }

  ERP_FEE_PAYMENTS.unshift(newPayment);
  await recordAuditLog("erp.fee_payment_collected", req.user?.email || "cashier", "fee_payment", newPayment.id, req);

  res.json({
    success: true,
    message: "Payment successfully recorded and receipt generated",
    receiptNo,
    payment: newPayment,
    demand
  });
});

// 6j. POST /api/erp/fees/payments/:id/reverse - Audited Payment Reversal
app.post("/api/erp/fees/payments/:id/reverse", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const { reason, reversedBy } = req.body;

  if (!reason || reason.trim().length < 5) {
    return res.status(400).json({ success: false, message: "A valid administrative reason (min 5 characters) is required for payment reversal" });
  }

  const payment = ERP_FEE_PAYMENTS.find(p => (p.organization_id === orgId) && (p.id === id || p.db_id === id || p.receiptNo === id));
  if (!payment) {
    return res.status(404).json({ success: false, message: "Payment record not found" });
  }

  if (payment.status === "reversed") {
    return res.status(400).json({ success: false, message: "Payment is already reversed" });
  }

  payment.status = "reversed";

  const demand = ERP_FEE_DEMANDS.find(d => d.id === payment.demandId || (d.db_id && d.db_id === payment.demandId));
  if (demand) {
    demand.paidAmount = Math.max(0, Math.round((Number(demand.paidAmount) - Number(payment.amountPaid)) * 100) / 100);
    demand.balanceAmount = Math.round((Number(demand.netAmount) - demand.paidAmount) * 100) / 100;
    const today = new Date().toISOString().slice(0, 10);
    demand.status = demand.balanceAmount <= 0 ? "paid" : demand.paidAmount > 0 ? "partially_paid" : (demand.dueDate < today ? "overdue" : "pending");
  }

  // DB Reversal
  await reverseDbFeePayment(orgId, payment.db_id || payment.receiptNo);

  const reversal = {
    id: `rev-${Date.now()}`,
    paymentId: payment.id,
    receiptNo: payment.receiptNo,
    studentId: payment.studentId,
    studentName: payment.studentName,
    reversalAmount: payment.amountPaid,
    reason: reason.trim(),
    reversedBy: reversedBy || "Principal / Senior Administrator",
    reversedAt: new Date().toISOString(),
    organization_id: orgId
  };

  ERP_FEE_REVERSALS.unshift(reversal);
  await recordAuditLog("erp.fee_payment_reversed", req.user?.email || "admin", "fee_payment", payment.id, req);

  res.json({
    success: true,
    message: `Payment ${payment.receiptNo} of ₹${payment.amountPaid} reversed successfully`,
    reversal,
    payment,
    demand
  });
});

