// 7k. POST /api/erp/admissions/check-duplicate & POST /api/erp/admissions/duplicate-check - Pre-Admission Duplicate Detection
const handleDuplicateCheck = (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { studentName, dob, parentPhone, admissionNo } = req.body;

  const tenantStudents = ERP_STUDENTS.filter(s => s.organization_id === orgId);
  const matches = [];

  for (const std of tenantStudents) {
    let matchType = null;
    let confidence = "low";

    if (admissionNo && std.admissionNo && std.admissionNo.toLowerCase() === admissionNo.toLowerCase()) {
      matchType = "admission_number_exact";
      confidence = "high";
    } else if (studentName && std.name && std.name.toLowerCase() === studentName.toLowerCase() && dob && std.dob === dob) {
      matchType = "name_and_dob_exact";
      confidence = "high";
    } else if (parentPhone && std.parentPhone && std.parentPhone === parentPhone) {
      matchType = "parent_phone_match";
      confidence = "medium";
    } else if (studentName && std.name && std.name.toLowerCase() === studentName.toLowerCase()) {
      matchType = "name_similarity";
      confidence = "low";
    }

    if (matchType) {
      matches.push({
        studentId: std.id,
        name: std.name,
        admissionNo: std.admissionNo,
        grade: std.grade,
        section: std.section,
        parentName: std.parentName,
        parentPhone: std.parentPhone,
        dob: std.dob,
        matchType,
        confidence
      });
    }
  }

  res.json({
    success: true,
    hasDuplicate: matches.length > 0,
    matchesCount: matches.length,
    matches
  });
};

app.post("/api/erp/admissions/check-duplicate", handleDuplicateCheck);
app.post("/api/erp/admissions/duplicate-check", handleDuplicateCheck);

// 7l. POST /api/erp/leads/:leadId/convert-to-admission & POST /api/erp/admissions/leads/:leadId/convert - Convert CRM Lead to Admission Application
const handleLeadConversion = async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const leadId = req.params.leadId || req.params.id;

  let lead = IN_MEMORY_LEADS.find(l => (l.organization_id === orgId) && l.id === leadId);
  if (!lead && supabase) {
    const { data: dbLead } = await supabase.from("leads").select("*").eq("organization_id", orgId).eq("id", leadId).maybeSingle();
    if (dbLead) lead = dbLead;
  }

  if (!lead) {
    return res.status(404).json({ success: false, message: "CRM Lead not found" });
  }

  // Parse student name and grade from lead notes if available
  let studentName = lead.name;
  let appliedGrade = lead.metadata?.grade || "Class 9";
  const notesText = lead.notes || lead.message || "";
  if (notesText && notesText.includes("Grade")) {
    const match = notesText.match(/Grade\s*([0-9A-Za-z]+)/i);
    if (match) appliedGrade = `Class ${match[1]}`;
  } else if (notesText && notesText.includes("Class")) {
    const match = notesText.match(/Class\s*([0-9A-Za-z]+)/i);
    if (match) appliedGrade = `Class ${match[1]}`;
  }

  const session = req.body.academicSession || lead.metadata?.session || "2026-27";
  const appNo = generateUniqueApplicationNo(session);
  const newAdmId = `adm-${Date.now()}`;

  const newAdm = {
    id: newAdmId,
    applicationNo: appNo,
    inquiryNo: `INQ-2026-${Math.floor(100 + Math.random() * 900)}`,
    academicSession: session,
    studentName,
    dob: req.body.dob || null,
    gender: req.body.gender || "Not Specified",
    parentName: lead.name || "Parent",
    parentRelation: "Father",
    parentEmail: lead.email || "",
    phone: lead.phone || "+91 98000 00000",
    altPhone: "",
    address: req.body.address || "",
    city: "Gurugram",
    state: "Haryana",
    pinCode: "122001",
    appliedGrade: req.body.appliedGrade || appliedGrade,
    previousSchool: req.body.previousSchool || "",
    source: lead.source || "website",
    status: "new",
    interviewScore: null,
    interviewNotes: "",
    rejectionReason: null,
    leadId: lead.id,
    studentId: null,
    applicationDate: new Date().toISOString().slice(0, 10),
    notes: `Converted from CRM Lead: ${lead.notes || lead.message || 'Website lead'}`,
    organization_id: orgId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  // Seed default docs
  const defaultDocTypes = [
    { type: "birth_certificate", name: "Birth Certificate" },
    { type: "previous_marksheet", name: "Previous Marksheet" },
    { type: "transfer_certificate", name: "Transfer Certificate" },
    { type: "photograph", name: "Passport Photograph" }
  ];

  defaultDocTypes.forEach((dt, idx) => {
    ERP_ADMISSION_DOCUMENTS.push({
      id: `doc-${newAdm.id}-${idx + 1}`,
      admissionId: newAdm.id,
      documentType: dt.type,
      documentName: dt.name,
      fileUrl: `/uploads/admissions/${newAdm.id}/${dt.type}.pdf`,
      status: "pending",
      rejectionReason: null,
      uploadedBy: "applicant",
      uploadedAt: new Date().toISOString(),
      verifiedBy: null,
      verifiedAt: null,
      organization_id: orgId
    });
  });

  ERP_ADMISSION_TIMELINE.push({
    id: `time-${Date.now()}`,
    admissionId: newAdm.id,
    eventType: "inquiry_captured",
    title: "Converted from CRM Lead",
    description: `Lead #${lead.id} successfully converted into formal admission application ${appNo}.`,
    actorName: req.user?.name || "Admissions Officer",
    createdAt: new Date().toISOString(),
    organization_id: orgId
  });

  lead.status = "converted";
  lead.notes = (lead.notes ? lead.notes + " | " : "") + `Converted to Application ${appNo}`;

  // Update in Supabase PostgreSQL
  if (supabase) {
    try {
      await supabase.from("leads").update({
        status: "converted",
        message: (lead.message ? lead.message + " | " : "") + `Converted to Application ${appNo}`,
        updated_at: new Date().toISOString()
      }).eq("id", lead.id);
    } catch (err) {
      console.warn("[Leads DB] Supabase lead update warning:", err.message);
    }
  }

  await recordAuditLog("erp.lead_converted", req.user?.email || "admissions@dpsheritage.edu.in", "lead", lead.id, req);

  ERP_ADMISSIONS.unshift(newAdm);
  res.json({
    success: true,
    message: "CRM Lead successfully converted to Admission Application ✅",
    admission: newAdm
  });
};

app.post("/api/erp/leads/:leadId/convert-to-admission", handleLeadConversion);
app.post("/api/erp/admissions/leads/:leadId/convert", handleLeadConversion);
app.post("/api/erp/admissions/leads/:id/convert", handleLeadConversion);

// 7m. POST /api/erp/admissions/:id/confirm & POST /api/erp/admissions/:id/convert-to-student
// Authoritative Transactional Conversion: Application -> Student -> Parent -> Enrollment -> Fee Demand
const handleConfirmAdmission = async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  const { id } = req.params;
  const callerRole = req.user?.role || req.query.role || "school-admin";

  // RBAC check: Student and Teacher cannot confirm admissions
  if (callerRole === "student" || callerRole === "parent") {
    return res.status(403).json({ success: false, message: "Forbidden: Only School Administrators or Admissions Officers can confirm admissions" });
  }

  const adm = ERP_ADMISSIONS.find(a => (a.organization_id === orgId) && (a.id === id || a.applicationNo === id));
  if (!adm) {
    return res.status(404).json({ success: false, message: "Admission application not found" });
  }

  if (adm.status === "admitted" && adm.studentId) {
    return res.status(400).json({ success: false, message: "Application has already been admitted as an enrolled student" });
  }

  const assignedGrade = req.body.grade || (adm.appliedGrade ? adm.appliedGrade.split("(")[0].trim() : "Class 10");
  const assignedSection = req.body.section || "A";
  const academicSession = adm.academicSession || "2026-27";

  // 1. Check or Reuse Parent Record
  let parentRecord = ERP_PARENTS.find(p => (p.organization_id === orgId) && (
    (adm.phone && p.phone === adm.phone) ||
    (adm.parentEmail && p.email && p.email.toLowerCase() === adm.parentEmail.toLowerCase())
  ));

  if (!parentRecord && supabase) {
    try {
      let q = supabase.from("parents").select("*").eq("organization_id", orgId);
      if (adm.phone) {
        q = q.eq("phone", adm.phone);
      }
      const { data: dbP } = await q.maybeSingle();
      if (dbP) {
        parentRecord = {
          id: dbP.id,
          db_id: dbP.id,
          name: dbP.name,
          relation: dbP.relation,
          phone: dbP.phone,
          email: dbP.email,
          occupation: dbP.occupation,
          address: dbP.address,
          organization_id: orgId
        };
        ERP_PARENTS.unshift(parentRecord);
      }
    } catch (_) {}
  }

  if (!parentRecord) {
    parentRecord = {
      id: `par-${Date.now()}`,
      name: adm.parentName || "Guardian",
      relation: adm.parentRelation || "Father",
      phone: adm.phone || "+91 98000 00000",
      email: adm.parentEmail || "",
      occupation: req.body.parentOccupation || "Professional",
      address: adm.address || "Main Campus Sector",
      organization_id: orgId,
      created_at: new Date().toISOString()
    };
    if (supabase) {
      try {
        const { data: insP } = await supabase
          .from("parents")
          .insert([{
            organization_id: orgId,
            name: parentRecord.name,
            relation: parentRecord.relation,
            phone: parentRecord.phone,
            email: parentRecord.email || null,
            occupation: parentRecord.occupation,
            address: parentRecord.address
          }])
          .select()
          .maybeSingle();
        if (insP) {
          parentRecord.db_id = insP.id;
          parentRecord.id = insP.id;
        }
      } catch (_) {}
    }
    ERP_PARENTS.unshift(parentRecord);
  }

  // 2. Create Student Record
  let nextStdSeq = ERP_STUDENTS.length + 101;
  while (ERP_STUDENTS.some(s => s.rollNo === `DPS-2026-${String(nextStdSeq).padStart(3, "0")}`)) {
    nextStdSeq++;
  }
  const uniqueSuffix = Math.floor(1000 + Math.random() * 9000);
  const newAdmissionNo = `DPS-ADM-2026-${String(nextStdSeq).padStart(3, "0")}-${uniqueSuffix}`;
  const newRollNo = `DPS-2026-${String(nextStdSeq).padStart(3, "0")}`;
  const nameParts = adm.studentName.trim().split(" ");
  const firstName = nameParts[0] || adm.studentName;
  const lastName = nameParts.slice(1).join(" ") || "";

  // Transfer verified documents to student
  const verifiedDocs = ERP_ADMISSION_DOCUMENTS
    .filter(d => d.admissionId === adm.id && d.status === "verified")
    .map((d, i) => ({
      id: `doc-${nextStdSeq}-${i + 1}`,
      name: d.documentName,
      type: d.documentType,
      verified: true,
      uploadedAt: d.uploadedAt
    }));

  const newStudent = {
    id: `std-${nextStdSeq}`,
    admissionNo: newAdmissionNo,
    penNo: `202689${String(nextStdSeq).padStart(3, "0")}${uniqueSuffix}`,
    rollNo: newRollNo,
    firstName,
    middleName: "",
    lastName,
    name: adm.studentName,
    grade: assignedGrade,
    section: assignedSection,
    gender: adm.gender || "Male",
    dob: adm.dob || "2011-01-01",
    bloodGroup: req.body.bloodGroup || "B+",
    avatarUrl: adm.gender === "Female" 
      ? "https://images.unsplash.com/photo-1517841905240-472988babdf9?w=150&auto=format&fit=crop&q=80"
      : "https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=150&auto=format&fit=crop&q=80",
    admissionDate: new Date().toISOString().slice(0, 10),
    academicSession,
    status: "active",
    phone: adm.phone,
    email: adm.parentEmail || `${firstName.toLowerCase()}.${newAdmissionNo.toLowerCase()}@student.dpsheritage.edu.in`,
    address: adm.address,
    city: adm.city || "Gurugram",
    state: adm.state || "Haryana",
    pinCode: adm.pinCode || "122001",
    parentName: parentRecord.name,
    parentRelation: parentRecord.relation,
    parentPhone: parentRecord.phone,
    parentAltPhone: adm.altPhone || "",
    parentEmail: parentRecord.email,
    parentOccupation: parentRecord.occupation,
    parentAddress: parentRecord.address,
    documents: verifiedDocs,
    attendancePercent: 100.0,
    duesINR: 0,
    organization_id: orgId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  // Persist to PostgreSQL public.students
  let dbStudentId = null;
  if (supabase) {
    try {
      const { data: dbStd, error: stdErr } = await supabase
        .from("students")
        .insert([{
          organization_id: orgId,
          first_name: firstName,
          last_name: lastName,
          admission_no: newStudent.admissionNo,
          pen_no: newStudent.penNo,
          gender: ["male", "female", "other"].includes((newStudent.gender || "").toLowerCase()) ? newStudent.gender.toLowerCase() : "other",
          date_of_birth: newStudent.dob || "2011-01-01",
          blood_group: newStudent.bloodGroup || "B+",
          phone: newStudent.phone,
          email: newStudent.email,
          address: newStudent.address,
          city: newStudent.city,
          state: newStudent.state,
          pincode: newStudent.pinCode,
          admission_date: newStudent.admissionDate,
          admission_status: "admitted"
        }])
        .select()
        .maybeSingle();

      if (stdErr) {
        console.error("[Admissions DB] Failed to insert student into public.students:", stdErr.message);
      } else if (dbStd) {
        dbStudentId = dbStd.id;
        newStudent.db_id = dbStudentId;
      }
    } catch (e) {
      console.error("[Admissions DB] Student insert exception:", e.message);
    }
  }

  ERP_STUDENTS.unshift(newStudent);

  // 3. Create Student Enrollment Record
  const newEnrollment = {
    id: `enr-${Date.now()}`,
    studentId: newStudent.id,
    studentName: newStudent.name,
    academicSession,
    grade: assignedGrade,
    section: assignedSection,
    rollNo: newStudent.rollNo,
    status: "active",
    enrollmentDate: newStudent.admissionDate,
    organization_id: orgId
  };
  ERP_STUDENT_ENROLLMENTS.unshift(newEnrollment);

  // 4. Generate Admission Fee Demand via Fees & Finance Module
  let targetFeeStruct = ERP_FEE_STRUCTURES.find(fs => 
    (fs.organization_id === orgId) &&
    fs.status === "active" &&
    (fs.grade === assignedGrade || fs.grade.toLowerCase().includes(assignedGrade.toLowerCase())) &&
    fs.feeHead.toLowerCase().includes("admission")
  ) || ERP_FEE_STRUCTURES.find(fs =>
    (fs.organization_id === orgId) &&
    fs.status === "active" &&
    (fs.grade === assignedGrade || fs.grade.toLowerCase().includes(assignedGrade.toLowerCase()))
  );

  let feeDemand = null;
  if (targetFeeStruct) {
    const invSeq = String(ERP_FEE_DEMANDS.length + 1).padStart(2, "0");
    const feeAmount = targetFeeStruct.amountINR || 10000;
    feeDemand = {
      id: `inv-${Date.now()}`,
      invoiceNo: `FEES-2026-ADM-${invSeq}`,
      studentId: newStudent.id,
      studentName: newStudent.name,
      admissionNo: newStudent.admissionNo,
      grade: assignedGrade,
      section: assignedSection,
      academicSession,
      feeStructureId: targetFeeStruct.id,
      feeStructureDbId: targetFeeStruct.db_id,
      feeHead: targetFeeStruct.feeHead,
      feeType: targetFeeStruct.feeHead,
      baseAmount: feeAmount,
      discountAmount: 0,
      fineAmount: 0,
      netAmount: feeAmount,
      paidAmount: 0,
      balanceAmount: feeAmount,
      dueDate: new Date(Date.now() + 15 * 86400000).toISOString().slice(0, 10),
      status: "pending",
      amountINR: feeAmount,
      organization_id: orgId,
      created_at: new Date().toISOString()
    };
    ERP_FEE_DEMANDS.unshift(feeDemand);
    newStudent.duesINR = feeAmount;

    // Persist fee demand to public.student_fees
    if (supabase) {
      try {
        const dbFee = await resolveOrCreateStudentFee(orgId, {
          ...feeDemand,
          dbStudentId,
          studentId: dbStudentId || newStudent.id
        });
        if (dbFee) {
          feeDemand.db_id = dbFee.id;
        }
      } catch (err) {
        console.error("[Admissions DB] Fee demand persistence error:", err.message);
      }
    }
  }

  // 5. Update Admission Status & Link Student
  adm.status = "admitted";
  adm.studentId = newStudent.id;
  adm.admittedAt = new Date().toISOString();
  adm.updated_at = new Date().toISOString();

  // 6. Update Associated CRM Lead
  if (adm.leadId) {
    const linkedLead = IN_MEMORY_LEADS.find(l => l.id === adm.leadId);
    if (linkedLead) {
      linkedLead.status = "converted";
      linkedLead.notes = (linkedLead.notes ? linkedLead.notes + " | " : "") + `Enrolled as Student ${newStudent.admissionNo} in ${assignedGrade}-${assignedSection}`;
    }
    if (supabase) {
      try {
        await supabase.from("leads").update({
          status: "converted",
          message: `Enrolled as Student ${newStudent.admissionNo} in ${assignedGrade}-${assignedSection}`,
          updated_at: new Date().toISOString()
        }).eq("id", adm.leadId);
      } catch (err) {
        console.warn("[Admissions DB] Lead status update warning:", err.message);
      }
    }
  }

  // 7. Timeline & System Audit Logging
  ERP_ADMISSION_TIMELINE.push({
    id: `time-${Date.now()}`,
    admissionId: adm.id,
    eventType: "admitted",
    title: "Admission Confirmed & Student Enrolled",
    description: `Formally enrolled into ${assignedGrade}-${assignedSection} with Admission No ${newStudent.admissionNo}. Fee Demand ${feeDemand ? feeDemand.invoiceNo : 'N/A'} generated.`,
    actorName: req.user?.name || "Principal Office",
    createdAt: new Date().toISOString(),
    organization_id: orgId
  });

  await recordAuditLog("erp.admission_confirmed", req.user?.email || "principal@dpsheritage.edu.in", "admission", adm.id, req);
  await recordAuditLog("erp.student_enrolled", req.user?.email || "principal@dpsheritage.edu.in", "student", newStudent.id, req);
  if (feeDemand) {
    await recordAuditLog("erp.fee_demand_created", req.user?.email || "principal@dpsheritage.edu.in", "fee_demand", feeDemand.id, req);
  }

  res.json({
    success: true,
    message: `Admission confirmed! ${newStudent.name} enrolled with Admission No ${newStudent.admissionNo} 🎉`,
    student: newStudent,
    parent: parentRecord,
    enrollment: newEnrollment,
    feeDemand,
    application: adm
  });
};

app.post("/api/erp/admissions/:id/confirm", handleConfirmAdmission);
app.post("/api/erp/admissions/:id/convert-to-student", handleConfirmAdmission);

// 7m. GET /api/erp/parents - List Tenant Parents with DB Persistence
app.get("/api/erp/parents", async (req, res) => {
  const orgId = resolveTenantOrgId(req);
  if (supabase) {
    try {
      const { data: dbParents, error } = await supabase
        .from("parents")
        .select("*")
        .eq("organization_id", orgId);
      if (!error && Array.isArray(dbParents) && dbParents.length > 0) {
        return res.json({ success: true, parents: dbParents, count: dbParents.length });
      }
    } catch (_) {}
  }
  const tenantParents = ERP_PARENTS.filter(p => p.organization_id === orgId);
  res.json({ success: true, parents: tenantParents, count: tenantParents.length });
});

