app.post("/api/erp/communication/messages/:id/send", (req, res) => {
  if (!checkCommunicationAdminPrivilege(req, res)) return;
  const orgId = resolveTenantOrgId(req);
  const message = ERP_COMMUNICATION_MESSAGES.find(m => (m.organization_id === orgId) && m.id === req.params.id);
  if (!message) {
    return res.status(404).json({ success: false, message: "Message not found" });
  }

  message.status = 'sent';
  message.sentAt = new Date().toISOString();
  message.updatedAt = new Date().toISOString();

  // Process deliveries if none existed
  const existingDeliveries = ERP_MESSAGE_DELIVERIES.filter(d => d.messageId === message.id);
  if (existingDeliveries.length === 0) {
    const audience = resolveAudienceRecipients(message.audienceType, message.audienceFilter, orgId);
    audience.recipients.forEach((rec, idx) => {
      ERP_MESSAGE_DELIVERIES.unshift({
        id: `del-${Date.now().toString().slice(-4)}-${idx + 1}`,
        messageId: message.id,
        recipientId: rec.id,
        recipientType: rec.type,
        recipientName: rec.name,
        recipientContact: rec.contact,
        channel: message.channel === 'all' ? 'in_app' : message.channel,
        status: 'delivered',
        providerMessageId: `manual_send_${Date.now()}_${idx}`,
        failureReason: null,
        sentAt: new Date().toISOString(),
        deliveredAt: new Date().toISOString(),
        readAt: null,
        createdAt: new Date().toISOString(),
        organization_id: orgId
      });
    });
  }

  recordAuditLog("erp.message_sent", req.user?.email || "principal@dpsheritage.edu.in", "message", message.id, req);

  res.json({ success: true, message: "Message dispatched immediately!", messageRecord: message });
});

app.post("/api/erp/communication/messages/:id/cancel", (req, res) => {
  if (!checkCommunicationAdminPrivilege(req, res)) return;
  const orgId = resolveTenantOrgId(req);
  const message = ERP_COMMUNICATION_MESSAGES.find(m => (m.organization_id === orgId) && m.id === req.params.id);
  if (!message) {
    return res.status(404).json({ success: false, message: "Message not found" });
  }

  message.status = 'cancelled';
  message.updatedAt = new Date().toISOString();
  recordAuditLog("erp.message_cancelled", req.user?.email || "principal@dpsheritage.edu.in", "message", message.id, req);

  res.json({ success: true, message: "Scheduled message cancelled", messageRecord: message });
});

// DELETE /api/erp/communication/messages/:id - Teardown message & deliveries
app.delete("/api/erp/communication/messages/:id", (req, res) => {
  if (!checkCommunicationAdminPrivilege(req, res)) return;
  const orgId = resolveTenantOrgId(req);
  const mIdx = ERP_COMMUNICATION_MESSAGES.findIndex(m => (m.organization_id === orgId) && m.id === req.params.id);
  if (mIdx !== -1) {
    ERP_COMMUNICATION_MESSAGES.splice(mIdx, 1);
  }
  for (let i = ERP_MESSAGE_DELIVERIES.length - 1; i >= 0; i--) {
    if (ERP_MESSAGE_DELIVERIES[i].messageId === req.params.id) {
      ERP_MESSAGE_DELIVERIES.splice(i, 1);
    }
  }
  res.json({ success: true, message: "Message deleted" });
});

