// 4. PATCH /api/admin/organizations/:id/status - Update Organization Status (Activate/Deactivate/Suspend/Archive)
app.patch(["/api/admin/organizations/:id/status", "/api/organizations/:id/status"], async (req, res) => {
  if (!checkPlatformAdminRole(req, res)) return;

  let { status } = req.body || {};
  if (status === "deactivated") status = "suspended";
  const allowed = ["active", "trial", "suspended", "cancelled", "archived"];
  if (!status || !allowed.includes(status.toLowerCase())) {
    return res.status(400).json({ success: false, message: `Status must be one of: ${allowed.join(', ')}` });
  }

  const org = await findOrganization(req.params.id);
  if (!org) {
    return res.status(404).json({ success: false, message: "Organization not found" });
  }

  const oldStatus = org.status;
  org.status = status.toLowerCase();
  org.updated_at = new Date().toISOString();

  // Sync status to Supabase PostgreSQL
  if (supabase) {
    try {
      await supabase.from("organizations").update({ status: org.status, updated_at: org.updated_at }).eq("id", org.id);
      await supabase.from("schools").update({ status: org.status, updated_at: org.updated_at }).eq("organization_id", org.id).catch(() => {});
    } catch (e) {
      console.warn("Supabase organization status sync note:", e.message);
    }
  }

  // CRITICAL: Synchronize Subscription Status with Organization Status!
  const targetSubStatus = (org.status === "suspended" || org.status === "archived" || org.status === "cancelled") ? "suspended" : "active";

  // 1. Update in-memory SAAS_SUBSCRIPTIONS
  SAAS_SUBSCRIPTIONS.forEach(sub => {
    if (sub.organization_id === org.id) {
      sub.status = targetSubStatus;
      sub.updated_at = new Date().toISOString();
    }
  });

  // 2. Update Supabase saas_subscriptions
  if (supabase) {
    try {
      const dbSubStatus = (org.status === "suspended" || org.status === "archived") ? "paused" : org.status === "cancelled" ? "cancelled" : "active";
      await supabase.from("saas_subscriptions").update({
        status: dbSubStatus,
        updated_at: new Date().toISOString()
      }).eq("organization_id", org.id);
    } catch (subErr) {
      console.warn("Supabase saas_subscriptions status sync note:", subErr.message);
    }
  }

  await recordAuditLog(
    "ORGANIZATION_STATUS_CHANGED",
    req.user?.email || "superadmin@dakshora.ai",
    "organization",
    `Changed '${org.name}' status from ${oldStatus} to ${org.status} (Subscription status: ${targetSubStatus})`,
    req
  );

  res.json({
    success: true,
    message: `School '${org.name}' is now ${org.status.toUpperCase()} ✅ (Subscription: ${targetSubStatus.toUpperCase()})`,
    organization: org,
    subscriptionStatus: targetSubStatus
  });
});

// 4b. PUT /api/admin/organizations/:id - Update Organization Details
app.put(["/api/admin/organizations/:id", "/api/organizations/:id"], async (req, res) => {
  if (!checkPlatformAdminRole(req, res)) return;

  const org = await findOrganization(req.params.id);
  if (!org) {
    return res.status(404).json({ success: false, message: "Organization not found" });
  }

  const { name, plan, board, contact_email, contact_phone, city, state, mrr_inr, status } = req.body || {};

  if (name) org.name = name;
  if (plan) org.plan = plan;
  if (board) org.board = board;
  if (contact_email) org.contact_email = contact_email;
  if (contact_phone) org.contact_phone = contact_phone;
  if (city) org.city = city;
  if (state) org.state = state;
  if (mrr_inr !== undefined) org.mrr_inr = Number(mrr_inr);
  if (status) org.status = status === "deactivated" ? "suspended" : status;
  org.updated_at = new Date().toISOString();

  if (supabase) {
    try {
      // organizations table only has name, status, updated_at
      await supabase.from("organizations").update({
        name: org.name,
        status: org.status,
        updated_at: org.updated_at
      }).eq("id", org.id);

      // sync school table
      await supabase.from("schools").update({
        name: org.name,
        board: org.board,
        contact_email: org.contact_email,
        contact_phone: org.contact_phone,
        city: org.city,
        state: org.state,
        status: org.status,
        updated_at: org.updated_at
      }).eq("organization_id", org.id).catch(() => {});

      // sync subscription if status changed
      const dbSubStatus = (org.status === "suspended" || org.status === "archived") ? "paused" : org.status === "cancelled" ? "cancelled" : "active";
      await supabase.from("saas_subscriptions").update({
        status: dbSubStatus,
        updated_at: new Date().toISOString()
      }).eq("organization_id", org.id).catch(() => {});
    } catch (e) {
      console.warn("Supabase organization details sync note:", e.message);
    }
  }

  await recordAuditLog(
    "ORGANIZATION_DETAILS_UPDATED",
    req.user?.email || "superadmin@dakshora.ai",
    "organization",
    `Updated details for '${org.name}'`,
    req
  );

  res.json({
    success: true,
    message: `School tenant '${org.name}' updated successfully ✅`,
    organization: org
  });
});

// 4c. DELETE /api/admin/organizations/:id - Deactivate / Archive Organization
app.delete(["/api/admin/organizations/:id", "/api/organizations/:id"], async (req, res) => {
  if (!checkPlatformAdminRole(req, res)) return;

  const org = await findOrganization(req.params.id);
  if (!org) {
    return res.status(404).json({ success: false, message: "Organization not found" });
  }

  org.status = "archived";
  org.updated_at = new Date().toISOString();

  if (supabase) {
    try {
      await supabase.from("organizations").update({ status: "archived", updated_at: org.updated_at }).eq("id", org.id);
      await supabase.from("schools").update({ status: "archived", updated_at: org.updated_at }).eq("organization_id", org.id).catch(() => {});
      await supabase.from("saas_subscriptions").update({ status: "paused", updated_at: org.updated_at }).eq("organization_id", org.id).catch(() => {});
    } catch (e) {
      console.warn("Supabase organization archive note:", e.message);
    }
  }

  await recordAuditLog(
    "ORGANIZATION_ARCHIVED",
    req.user?.email || "superadmin@dakshora.ai",
    "organization",
    `Archived / Deactivated organization '${org.name}'`,
    req
  );

  res.json({
    success: true,
    message: `School tenant '${org.name}' has been archived and access deactivated 🔒`,
    organization: org
  });
});

