// 8. GET /api/admin/subscriptions - Platform-wide Subscriptions
app.get("/api/admin/subscriptions", async (req, res) => {
  if (!checkPlatformAdminRole(req, res)) return;

  if (supabase) {
    try {
      const { data: dbSubs, error: subsErr } = await supabase.from("saas_subscriptions").select("*, organization:organizations(id, name, slug, status)");
      if (!subsErr && dbSubs && dbSubs.length > 0) {
        const subscriptions = dbSubs.map(s => {
          const plan = SAAS_PLANS.find(p => p.id === s.plan_id) || { name: s.plan_id };
          const orgStatus = s.organization?.status || "active";
          const effectiveStatus = (orgStatus === "suspended" || orgStatus === "deactivated" || orgStatus === "archived" || s.status === "paused" || s.status === "suspended" || s.status === "cancelled") ? "suspended" : s.status;
          return {
            id: s.id,
            organization_id: s.organization_id,
            organizationName: s.organization?.name || "Unknown Organization",
            organizationSlug: s.organization?.slug || "unknown",
            organizationStatus: orgStatus,
            plan_id: s.plan_id,
            planName: plan.name,
            status: effectiveStatus,
            billing_interval: s.billing_interval,
            amountINR: Number(s.amount),
            currency: s.currency,
            current_period_start: s.current_period_start,
            current_period_end: s.current_period_end,
            cancel_at_period_end: s.cancel_at_period_end,
            created_at: s.created_at,
            updated_at: s.updated_at
          };
        });
        return res.json({
          success: true,
          total: subscriptions.length,
          subscriptions
        });
      }
    } catch (dbErr) {
      console.warn("[Admin Subs DB] Error:", dbErr.message);
    }
  }

  const subs = SAAS_SUBSCRIPTIONS.map(sub => {
    const org = IN_MEMORY_ORGANIZATIONS.find(o => o.id === sub.organization_id) || { name: "Unknown Organization", slug: "unknown", status: "active" };
    const plan = SAAS_PLANS.find(p => p.id === sub.plan_id) || { name: sub.plan_id };
    const orgStatus = org.status || "active";
    const effectiveStatus = (orgStatus === "suspended" || orgStatus === "deactivated" || orgStatus === "archived" || sub.status === "paused" || sub.status === "suspended" || sub.status === "cancelled") ? "suspended" : sub.status;

    return {
      ...sub,
      organizationName: org.name,
      organizationSlug: org.slug,
      organizationStatus: orgStatus,
      status: effectiveStatus,
      planName: plan.name
    };
  });

  res.json({
    success: true,
    total: subs.length,
    subscriptions: subs
  });
});

// 9. PATCH /api/admin/subscriptions/:id - Manage Customer Subscription
app.patch("/api/admin/subscriptions/:id", async (req, res) => {
  if (!checkPlatformAdminRole(req, res)) return;

  const sub = SAAS_SUBSCRIPTIONS.find(s => s.id === req.params.id);
  if (!sub) {
    return res.status(404).json({ success: false, message: "Subscription not found" });
  }

  const { plan_id, status, billing_interval, amountINR } = req.body || {};

  if (plan_id) {
    const planExists = SAAS_PLANS.some(p => p.id === plan_id);
    if (!planExists) return res.status(400).json({ success: false, message: `Invalid plan '${plan_id}'` });
    sub.plan_id = plan_id;
  }
  if (status) sub.status = status;
  if (billing_interval) sub.billing_interval = billing_interval;
  if (amountINR !== undefined) sub.amountINR = parseFloat(amountINR) || sub.amountINR;
  sub.updated_at = new Date().toISOString();

  if (supabase) {
    try {
      await supabase.from("saas_subscriptions").update({
        plan_id: sub.plan_id,
        status: sub.status,
        billing_interval: sub.billing_interval,
        amount: sub.amountINR,
        updated_at: sub.updated_at
      }).eq("id", sub.id);
    } catch (dbErr) {
      console.warn("[Admin Sub DB] Failed to update subscription in Supabase:", dbErr.message);
    }
  }

  await recordAuditLog(
    "SUBSCRIPTION_CHANGED",
    req.user?.email || "superadmin@dakshora.ai",
    "subscription",
    `Subscription ${sub.id} updated (Plan: ${sub.plan_id}, Status: ${sub.status})`,
    req
  );

  res.json({
    success: true,
    message: "Subscription updated successfully ✅",
    subscription: sub
  });
});

